				head.CFrame = cframe * CFrame.new(0, 1.5, 0)
				head.Size = Vector3.new(1, 1, 1)
				_customgrav(head)
				local torso, torsom = _limbin2parts("Torso", cframe, Vector3.new(2, 2, 1), {
					{0, 0, -20, 45},
