					{0, 0, -45, 45},
					{0, 0, -80, 80}
				})
				local larm, larmm = _limbin2parts("Left Arm", cframe * CFrame.new(-1.5, 0, 0), Vec121, {
					{0, 0, 0, 135},
					{0, 0, 0, 0},
					{0, 0, 0, 0}
				})
				local lshom = _muscleball(larm.Upper, torso.Upper, cframe * CFrame.new(-1, 0.375, 0), {
					{-0.1, 0.1, -170, 170},
