				})
				local rarm, rarmm = _limbin2parts("Right Arm", cframe * CFrame.new(1.5, 0, 0), Vec121, {
					{0, 0, 0, 135},
					{0, 0, 0, 0},
					{0, 0, 0, 0}
				})
				local rshom = _muscleball(rarm.Upper, torso.Upper, cframe * CFrame.new(1, 0.375, 0), {
