		start = os.clock()
		animator = AnimLib.Animator.new()
		animator.rig = figure
		animator.looped = true
		animator.speed = 1.127157
		if m.Alternative then
			animator.track = AnimLib.Track.fromfile(AssetGetPathFromFilename("RatDance2.anim"))
