					textvis[8] = true
				elseif eva < 7.75 then
					textvis[10] = true
				elseif eva < 7.875 then
					textvis[14] = true
				elseif eva < 8 then
					textvis[16] = true
				elseif eva < 9 then
					textvis[14] = true
				elseif eva < 10 then
