					textvis[11] = true
				elseif eva < 15 then
					textvis[16] = true
				else
					textvis[20] = true
					textvis[7] = true
				end
			end
		elseif t < 34.5 then
			local needy = t % 6
			if needy < 4.5 then
				animator2:Step(t)
			else
				animator3:Step(needy - 3)
			end
			if needy < 0.75 then
			elseif needy < 1.5 then
				textvis[22] = true
				textvis[26] = true
