AddModule(function()
	local m = {}
	m.ModuleType = "DANCE"
	m.Name = "Boogie"
	m.Description = "how is he hitting every beat"
	m.Assets = {"Boogie.anim", "Boogie.mp3"}

	m.Config = function(parent: GuiBase2d)
	end

