			end
		end
		local rt, nt, rst, lst, rht, lht = animationFunc(timingsine)
		if animationOverride then
			rt, nt, rst, lst, rht, lht = animationOverride(timingsine, rt, nt, rst, lst, rht, lht)
		end
		
