			SetC0C1Joint(j.Reference, j.C0, j.C1, scale)
		end
	end
	m.Destroy = function(figure: Model?)
		if buttonsui then
			buttonsui = buttonsui:Destroy()
		end
		if uiskeypress then
			uiskeypress:Disconnect()
		end
	end
	return m
