    SaveData.TheoBridge = type(SaveData.TheoBridge) == "table" and SaveData.TheoBridge or {}
    local options = type(SaveData.TheoBridge.Gelatek) == "table" and SaveData.TheoBridge.Gelatek or {}
    SaveData.TheoBridge.Gelatek = options

    local previousOptionsSchema = tonumber(options.SchemaVersion) or 0
    local CURRENT_OPTIONS_SCHEMA = 22
    local defaults = {
        -- Match Gelatek's original behavior: its controller can animate even
        -- when permanent death is disabled and no Uhhhhhh moveset is active.
        AnimationsDisabled = true,
        MatchAvatarRig = true,
        -- Keep controller/proxy AccessoryWelds intact, but optionally detach the
        -- real accessory handles so those controller clones can drive them.
        -- Accessories should remain part of their normal head/body assembly.
        -- Each detached handle depends on separate ownership and can drift
        -- or fall when that ownership is lost.
        BreakAccessoryWelds = false,
        DontBreakHairWelds = true,
        PermanentDeath = false,
        ResetTurnsPD = true,
        TeleportBackWhenVoided = false,
        -- Retain these JSON compatibility values; the core does not use legacy
        -- align constraints, deferred heartbeat scheduling, or pose derivatives.
        AlignReanimate = true,
        FullForceAlign = true,
        FasterHeartbeat = true,
        DynamicalVelocity = true,
        DisableTweaks = true,
        LoadLibrary = true,
        DetailedCredits = true,
        TorsoFling = false,
        BulletEnabled = false,
        BulletRunAfter = false,
        BulletLockTorso = false,
        NonPDRecoveryRadiusPercent = 5,
        PhysicalRecoveryDistance = 0,
        DirectPositionCorrection = true,
        RagdollSelfCollision = true,
        DisableDirectionalWalking = true,
        ShowMeHowILook = false,
        AntiSleep = false,
        RecoverBeforeVoid = true,
        Headless = false,
        OptimizeGame = false,
    }
    for key, value in pairs(defaults) do
        if options[key] == nil then
            options[key] = value
        end
    end
    -- These were implementation choices, not independent user features.
    -- Strip old saved values so they cannot select a second pose/physics path.
    options.CFrameFirst = nil
    options.PhysicsAccessoryHandles = nil
    options.PhysicalRecoveryDistance = math.clamp(
        tonumber(options.PhysicalRecoveryDistance) or 0, 0, 50)
    if options.PhysicalRecoveryDistance ~= options.PhysicalRecoveryDistance then options.PhysicalRecoveryDistance = 0 end
    options.DirectPositionCorrection = options.DirectPositionCorrection == true
    options.DisableDirectionalWalking = options.DisableDirectionalWalking == true
    options.ShowMeHowILook = options.ShowMeHowILook == true

    -- Schema 14 shipped accessory detachment as the default. There is no way
    -- to distinguish that inherited default from an intentional selection, so
    -- migrate once to the safe policy. The explicit advanced toggle can still
    -- be enabled again after this migration.
    if previousOptionsSchema < 15 then
        options.BreakAccessoryWelds = false
        options.DontBreakHairWelds = true
    end
    -- The old head-only switch and the all-accessory switch now have one owner.
    -- Preserve either explicit selection, including the non-PD torso workaround.
    if options.BreakHairWelds == true then options.BreakAccessoryWelds = true end
    options.BreakHairWelds = nil

    -- Keep other saved choices intact; schema 15 only migrates the unsafe
    -- accessory detachment policy above.
    options.SchemaVersion = CURRENT_OPTIONS_SCHEMA

    SaveData.AnimLibOptions =
        type(SaveData.AnimLibOptions) == "table"
        and SaveData.AnimLibOptions
        or {}
    SaveData.AnimLibOptions.ReplicationWriters =
        type(SaveData.AnimLibOptions.ReplicationWriters) == "table"
        and SaveData.AnimLibOptions.ReplicationWriters
        or {}
    local replicationWriters = SaveData.AnimLibOptions.ReplicationWriters
    local writerDefaults = {
        GelatekTorso = "Gelatek Physics",
        GelatekHead = "ReplicateCurrentAngle6D",
        LimbTorso = "ReplicateCurrentAngle6D",
        LimbHead = "ReplicateCurrentAngle6D",
        LimbRightArm = "ReplicateCurrentAngle6D",
        LimbLeftArm = "ReplicateCurrentAngle6D",
        LimbRightLeg = "ReplicateCurrentAngle6D",
        LimbLeftLeg = "ReplicateCurrentAngle6D",
    }
    for key, value in pairs(writerDefaults) do
        if replicationWriters[key] == nil
            or replicationWriters[key] == "CurrentAngle6D"
        then
            replicationWriters[key] = value
        end
    end
    if replicationWriters.GelatekTorso == "PhysicsRepRootPart" then
        replicationWriters.GelatekTorso = "PhysicsRepRootRef"
    end
    -- Preserve the explicit experimental torso choice, but migrate writer names
    -- from builds that tried to route Gelatek Torso through the limb/head paths.
    if replicationWriters.GelatekTorso ~= "Gelatek Physics"
        and replicationWriters.GelatekTorso ~= "PhysicsRepRootRef"
    then
        replicationWriters.GelatekTorso = "Gelatek Physics"
    end
    replicationWriters.GelatekHead = "ReplicateCurrentAngle6D"
    local backend = {
        Name = "Gelatek",
        DetectedRig = nil,
        ControllerRig = nil,
        Rig = nil,
        RealCharacter = nil,
        ActiveRealCharacter = nil,
        StaticRoot = nil,
        RigGeneration = 0,
        Running = false,
        LastError = nil,
        EffectivePermanentDeath = false,
        PermanentDeathFallback = false,
        ServerPreparedPermanentDeath = false,
        ResetRequested = false,
        ResetPDIntent = false,
        ResetPDCompletedSerial = nil,
        ResetPDLastError = nil,
        IgnoreSharedFling = false,
        AccessoryLifetime = {},
        ModePolicy = {},
    }

    function backend.ModePolicy.NextGeneration(resetTransition)
        return options.PermanentDeath == true
            or (resetTransition == true and options.ResetTurnsPD == true)
    end

    function backend.ModePolicy.BeginGeneration(resetTransition)
        local requestedPD = backend.ModePolicy.NextGeneration(resetTransition)
        backend.ResetPDIntent = false
        backend.ResetPDCompletedSerial, backend.ResetPDLastError = nil, nil
        return requestedPD
    end

    local originalCharacter
    local originalCameraSubject
    local originalFace
    local cameraBridgeBound = false
    local cameraBridgeConnection
    local cameraBridgeLTMs = {}
    local CAMERA_BRIDGE_NAME = "Uhhhhhh_GelatekCameraBridge"
    local gelatekVisibilityParts = setmetatable({}, { __mode = "k" })
    local scaleBridgeConnection
    local controllerSettingsCleanup
    local controllerCollisionConnection
    local ragdollCollisionFolder
    local neckBridgeConnection
    local neckBridgeLateConnection
    local neckBridgeRenderConnection
    local physicalAnimatorConnection
    local safeTrackerConnection
    local limbRecoveryConnection
    local flingBridgeConnection
    local accessoryBodyHideConnection
    local accessoryRecoveryConnection
    local accessoryBodyHideWeldStates = setmetatable({}, { __mode = "k" })
    local accessoryRecoveryStates = setmetatable({}, { __mode = "k" })
    local accessoryWeldBindings = setmetatable({}, { __mode = "k" })
    local physicalIndex = {Connections = {}}
    -- Invalidate on structural changes instead of allocating descendant/child
    -- arrays and recovery-pair records every simulation frame.
    local function getPhysicalHeadIndex(physical)
        if physicalIndex.Model ~= physical then
            for _, connection in ipairs(physicalIndex.Connections) do connection:Disconnect() end
            if physicalIndex.ControllerJoints then
                for _, connection in ipairs(physicalIndex.ControllerJoints.Connections) do connection:Disconnect() end
            end
            for _, record in pairs(physicalIndex.AccessoryRecords or {}) do
                if record.Template then pcall(function() record.Template:Destroy() end) end
            end
            physicalIndex = {Model = physical, Connections = {}, Dirty = true, Revision = 0}
            if physical then
                local function changed() physicalIndex.Dirty = true end
                for _, name in ipairs({"DescendantAdded", "DescendantRemoving", "ChildAdded", "ChildRemoved"}) do
                    local signal = physical[name]
                    if signal then table.insert(physicalIndex.Connections, signal:Connect(changed)) end
                end
            end
        end
        if physical and physicalIndex.Dirty then
            local cache = physicalIndex
            cache.Children, cache.BodyParts, cache.Joints, cache.Movers, cache.Parts = {}, {}, {}, {}, {}
            for _, child in ipairs(physical:GetChildren()) do
                table.insert(cache.Children, child)
                if child:IsA("BasePart") then table.insert(cache.BodyParts, child) end
            end
            cache.Descendants = physical:GetDescendants()
            for _, child in ipairs(cache.Descendants) do
		if child:IsA("BasePart") then table.insert(cache.Parts, child) end
                if child:IsA("JointInstance") or child:IsA("WeldConstraint")
                    or child.ClassName == "AnimationConstraint" or child.ClassName == "RigidConstraint" then
                    table.insert(cache.Joints, child)
                elseif child:IsA("BodyMover") or child:IsA("AlignPosition") or child:IsA("AlignOrientation")
                    or child:IsA("LinearVelocity") or child:IsA("AngularVelocity")
                    or child:IsA("VectorForce") or child:IsA("Torque") then
                    table.insert(cache.Movers, child)
                end
            end
            cache.Dirty, cache.Revision = false, cache.Revision + 1
        end
        return physicalIndex
    end
    local lastAppliedScale
    local lastJump = false
    local activeFling = nil
    local recentFlingTargets = {}
    local destroyHeightCaptured = false
    local originalDestroyHeight
    local staticRootPart
    local staticRootCFrame
    local poseMirrorRig
    local poseMirrorConnection
    local placeholderModel
    local placeholderParts = {}
    local placeholderActive = false
    local resetBindable
    local resetBindableConnection
    local resetInFlight = false
    local resetRequestSerial = 0
    local rebindInProgress = false
