    local capturedMaximumSimulationRadius
    local activeGenerationToken
    local torsoRepRootStates = setmetatable({}, { __mode = "k" })
    local torsoRepRootFailures = setmetatable({}, { __mode = "k" })
    local rootRepRootState = {}
