            end
        end

        local isPD = backend.EffectivePermanentDeath == true

        if physical:FindFirstChild("UpperTorso") and rig:FindFirstChild("UpperTorso") then
            -- Native R15 is one-to-one, not the segment approximation below.
            for _, partName in ipairs({"RightUpperArm", "RightLowerArm", "RightHand",
                "LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperLeg", "RightLowerLeg", "RightFoot",
                "LeftUpperLeg", "LeftLowerLeg", "LeftFoot"}) do add(partName, partName, CFrame.identity) end
            add("UpperTorso", "UpperTorso", CFrame.identity, not isPD)
            add("LowerTorso", "LowerTorso", CFrame.identity, not isPD)
            if isPD then add("Head", "Head", CFrame.identity) end
        elseif physical:FindFirstChild("UpperTorso") then
            -- Gelatek's R15 -> R6 mapping. These are the same positional offsets
            -- used by its Offsets table/CFrameAlign path.
            add("RightUpperArm", "Right Arm", CFrame.new(0, 0.4085, 0))
            add("RightLowerArm", "Right Arm", CFrame.new(0, -0.184, 0))
            add("RightHand", "Right Arm", CFrame.new(0, -0.83, 0))

            add("LeftUpperArm", "Left Arm", CFrame.new(0, 0.4085, 0))
            add("LeftLowerArm", "Left Arm", CFrame.new(0, -0.184, 0))
            add("LeftHand", "Left Arm", CFrame.new(0, -0.83, 0))

            add("RightUpperLeg", "Right Leg", CFrame.new(0, 0.575, 0))
            add("RightLowerLeg", "Right Leg", CFrame.new(0, -0.199, 0))
            add("RightFoot", "Right Leg", CFrame.new(0, -0.849, 0))

            add("LeftUpperLeg", "Left Leg", CFrame.new(0, 0.575, 0))
            add("LeftLowerLeg", "Left Leg", CFrame.new(0, -0.199, 0))
            add("LeftFoot", "Left Leg", CFrame.new(0, -0.849, 0))

            -- Torso pieces are native Gelatek physics followers in non-PD.
            -- Direct Position Correction may hard-correct their position every
            -- frame, but ordinary haymaker recovery leaves them alone.
            add("UpperTorso", "Torso", CFrame.new(0, 0.194, 0), not isPD)
            add("LowerTorso", "Torso", CFrame.new(0, -0.79, 0), not isPD)
            if isPD then
                add("Head", "Head", CFrame.identity)
            end
        else
            add("Right Arm", "Right Arm", CFrame.identity)
            add("Left Arm", "Left Arm", CFrame.identity)
            add("Right Leg", "Right Leg", CFrame.identity)
            add("Left Leg", "Left Leg", CFrame.identity)

            add("Torso", "Torso", CFrame.identity, not isPD)
            if isPD then
                add("Head", "Head", CFrame.identity)
            end
        end

        -- Detached accessories use Gelatek's exact object->target map. This is
        -- valid in PD and non-PD: non-PD destroys many AccessoryWelds too.
        if type(targetMap) == "table" then
            for _, accessory in ipairs(index.TrackedAccessories or index.Children) do
                if accessory:IsA("Accessory") then
                    local record = index.AccessoryRecords and index.AccessoryRecords[accessory]
                    local physicalHandle = record and record.Handle or accessory:FindFirstChild("Handle")
                    local controllerAccessory = targetMap[accessory]
                    local controllerHandle =
                        controllerAccessory
                        and controllerAccessory:IsA("Accessory")
                        and controllerAccessory:FindFirstChild("Handle")
                    accessoryTargets[accessory] = controllerHandle or false

                    if physicalHandle
                        and physicalHandle:IsA("BasePart")
                        and controllerHandle
                        and controllerHandle:IsA("BasePart")
                    then
                        do
                            table.insert(pairsList, {
                                Physical = physicalHandle,
                                Controller = controllerHandle,
                                Offset = CFrame.identity,
                                Name = accessory.Name .. ".Handle",
                                IsAccessory = true,
                                SourceAccessory = accessory,
                                Lifetime = record,
                            })
                        end
                    end
                end
            end
        end

        index.Recovery = {Rig = rig, Scale = scale, Map = targetMap, PD = backend.EffectivePermanentDeath,
            Revision = index.Revision, Pairs = pairsList, Targets = accessoryTargets}
        return pairsList
    end

    local function environment()
        return (getgenv and getgenv()) or shared or _G
    end

    local function restoreManagedRepRoot(state)
        return PhysicsRoot.RestoreManaged(state)
    end

    local function writeManagedRepRoot(state, part, reference, propertyName)
        if propertyName ~= nil and propertyName ~= PhysicsRoot.Property then
            return false, "retired replication-root writer"
        end
        return PhysicsRoot.WriteManaged(state, part, reference)
    end

    local function restoreGelatekTorsoWriter()
        for part, state in pairs(torsoRepRootStates) do
            local restored, reason = restoreManagedRepRoot(state)
            if restored then
                torsoRepRootStates[part] = nil
            else
                backend.TorsoRepRootLastError = reason
            end
        end
    end

    local function restoreGelatekRootRepRoot()
        restoreManagedRepRoot(rootRepRootState)
    end

    local function generationIsActive(token, rig)
        return token ~= nil
            and activeGenerationToken == token
            and backend.Running
            and backend.Rig == rig
            and rig
            and rig.Parent ~= nil
            and environment().UhhhhhhTBZGelatekRunToken == token
    end

    local function preparePermanentDeathWithServerCodeRemote()
        local activeCharacter = Player.Character
        if activeCharacter
            and activeCharacter:GetAttribute("UhhhhhhServerGelatekPrepared") == true
            and activeCharacter:GetAttribute("UhhhhhhServerGelatekPD") == true
        then
            return true, {
                NeckJointsBroken = 0,
                OwnedParts = 0,
                GenericLoadstringRemote = true,
            }
        end
        return false
    end

    local function suppressPhysicalAnimation(character)
        if typeof(character) ~= "Instance"
            or not character:IsA("Model")
            or not character.Parent
        then
            return
        end

        local animate = character:FindFirstChild("Animate")
        if animate and animate:IsA("LocalScript") then
            pcall(function()
                animate.Disabled = true
            end)
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then
            for _, child in ipairs(humanoid:GetChildren()) do
                if child:IsA("Animator") then
                    pcall(function()
                        child:Destroy()
                    end)
                end
            end
        end
    end

    local function attachPhysicalAnimationSuppression(character)
        if physicalAnimatorConnection then
            pcall(function()
                physicalAnimatorConnection:Disconnect()
            end)
            physicalAnimatorConnection = nil
        end

        suppressPhysicalAnimation(character)
        if typeof(character) ~= "Instance" or not character.Parent then
            return
        end

        local suppressionToken = activeGenerationToken

        physicalAnimatorConnection =
            character.DescendantAdded:Connect(function(instance)
                if activeGenerationToken ~= suppressionToken
                    or not backend.Running
                    or backend.RealCharacter ~= character
                then
                    return
                end

                if instance:IsA("Animator") then
                    task.defer(function()
                        if activeGenerationToken == suppressionToken
                            and backend.Running
                            and backend.RealCharacter == character
                            and instance.Parent
                            and instance:IsDescendantOf(character)
                        then
                            pcall(function()
                                instance:Destroy()
                            end)
                        end
                    end)
                elseif instance:IsA("LocalScript")
                    and instance.Name == "Animate"
                then
                    pcall(function()
                        instance.Disabled = true
                    end)
                end
            end)
    end

    local function isolatePhysicalCharacter(character)
        -- Never let a handoff reference turn the animation controller into
        -- a frozen, non-collidable physical shell.
        if character == backend.Rig or character == Reanimate.Character then
            return
        end
        if typeof(character) ~= "Instance" or not character:IsA("Model") or not character.Parent then
            return
        end
        for _, instance in ipairs(character:GetDescendants()) do
            if instance:IsA("BasePart") then
                if not isolatedPartStates[instance] then
                    isolatedPartStates[instance] = {
                        CanCollide = instance.CanCollide,
                        CanTouch = instance.CanTouch,
                        CanQuery = instance.CanQuery,
                        CollisionGroup = instance.CollisionGroup,
                    }
                end
                -- A CharacterAdded shell can overlap the persistent controller
                -- for several simulation steps before Gelatek maps its parts.
                -- Remove every contact/query path and any inherited spawn
                -- impulse for that short hand-off window.
                instance.CanCollide = false
                instance.CanTouch = false
                instance.CanQuery = false
                instance.AssemblyLinearVelocity = Vector3.zero
                instance.AssemblyAngularVelocity = Vector3.zero
            end
        end
    end

    local function restoreIsolatedPhysicalCharacter(character)
        if typeof(character) ~= "Instance" or not character:IsA("Model") or not character.Parent then
            return
        end
        for _, instance in ipairs(character:GetDescendants()) do
            if instance:IsA("BasePart") then
                local state = isolatedPartStates[instance]
                if state then
                    pcall(function()
                        instance.CanCollide = state.CanCollide
                        instance.CanTouch = state.CanTouch
                        instance.CanQuery = state.CanQuery
                        if state.CollisionGroup then instance.CollisionGroup = state.CollisionGroup end
                    end)
                    isolatedPartStates[instance] = nil
                end
            end
        end
    end

    local function enforcePhysicalShellIsolation(character)
        if character == backend.Rig or character == Reanimate.Character then
            return
        end
        if typeof(character) ~= "Instance" or not character:IsA("Model") or not character.Parent then
            return
        end
        for _, instance in ipairs(getPhysicalHeadIndex(character).Parts) do
            if instance:IsA("BasePart") then
                if not isolatedPartStates[instance] then
                    isolatedPartStates[instance] = {
                        CanCollide = instance.CanCollide,
                        CanTouch = instance.CanTouch,
                        CanQuery = instance.CanQuery,
                        CollisionGroup = instance.CollisionGroup,
                    }
                end
                -- The physical shell is only a replicated follower. It must never
                -- participate in world contacts; otherwise an occluder/wall can shove
                -- the real shell away while the invisible controller stays correct.
                if instance.CanCollide then instance.CanCollide = false end
                if instance.CanTouch then instance.CanTouch = false end
                if instance.CanQuery then instance.CanQuery = false end
            end
        end
    end

    local function collectReadyAccessories(character)
        local accessories = {}
        if typeof(character) ~= "Instance" or not character:IsA("Model") then
            return accessories, false
        end
        local allReady = true
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("Accessory") then
                if child:FindFirstChild("Handle") then
                    table.insert(accessories, child)
                else
                    allReady = false
                end
            end
        end
        return accessories, allReady
    end

    local function clearAccessoryTemplates()
        for _, template in ipairs(accessoryTemplates) do
            pcall(function()
                template:Destroy()
            end)
        end
        table.clear(accessoryTemplates)
        accessorySnapshotCaptured = false
    end

    local function snapshotAccessoryAppearance(character)
        local accessories = collectReadyAccessories(character)
        local replacements = {}
        for _, accessory in ipairs(accessories) do
            local ok, clone = pcall(function()
                return accessory:Clone()
            end)
            if ok and clone and clone:IsA("Accessory") and clone:FindFirstChild("Handle") then
                clone.Parent = nil
                table.insert(replacements, clone)
            end
        end
        clearAccessoryTemplates()
        for _, replacement in ipairs(replacements) do
            table.insert(accessoryTemplates, replacement)
        end
        accessorySnapshotCaptured = true
        return #accessoryTemplates
    end

    local function restoreMissingAccessories(character, humanoid)
        if not accessorySnapshotCaptured or #accessoryTemplates == 0 then
            return 0
        end
        local existing = {}
        for _, accessory in ipairs(collectReadyAccessories(character)) do
            existing[accessory.Name] = (existing[accessory.Name] or 0) + 1
        end
        local visited = {}
        local restored = 0
        for _, template in ipairs(accessoryTemplates) do
            local name = template.Name
            visited[name] = (visited[name] or 0) + 1
            if visited[name] > (existing[name] or 0) then
                local ok, clone = pcall(function()
                    return template:Clone()
                end)
                if ok and clone and clone:IsA("Accessory") then
                    local handle = clone:FindFirstChild("Handle")
                    if handle then
                        for _, child in ipairs(handle:GetChildren()) do
                            if child:IsA("Weld") and child.Name == "AccessoryWeld" then
                                child:Destroy()
                            end
                        end
                        clone:SetAttribute("_UhhhhhhGelatekRestoredAccessory", true)
                        local added = pcall(function()
                            humanoid:AddAccessory(clone)
                        end)
                        if not added or not clone.Parent then
                            clone.Parent = character
                        end
                        restored += 1
                    else
                        clone:Destroy()
                    end
                end
            end
        end
        return restored
    end

    local function addDescription(parent, text)
        UI.CreateText(parent, text, 9, Enum.TextXAlignment.Left)
    end

    local function persistOption(label)
        local saved, reason = SaveSettingsNow()
        if not saved then
            warn("Gelatek save failed " .. tostring(label) .. ": " .. tostring(reason))
            Util.Notify("Failed to save Gelatek setting")
        end
        return saved
    end

    local function addSwitch(parent, text, key, description)
        local control = UI.CreateSwitch(parent, text, options[key])
        control.Changed:Connect(function(value)
            options[key] = value == true
            if key == "AntiSleep" then
                environment().UhhhhhhTBZGelatekAntiSleep = options.AntiSleep
            elseif key == "DirectPositionCorrection" then
                local config = environment().GelatekReanimateConfig
                if type(config) == "table" then
                    config.DirectPositionCorrection = options.DirectPositionCorrection
                end
            end
            persistOption(text)
        end)
        if description then
            addDescription(parent, "-> " .. description)
        end
        return control
    end


    local function compatibility()
        local missing = {}
        if type(sethiddenproperty) ~= "function"
            and type(sethiddenprop) ~= "function"
            and type(set_hidden_property) ~= "function"
        then
            table.insert(missing, "sethiddenproperty")
        end
        if type(loadstring) ~= "function" then
            table.insert(missing, "loadstring")
        end
        return #missing == 0, missing
    end

    local function debugSafe(callable, fallback)
        local ok, value = pcall(callable)
        if ok then
            return value
        end
        return fallback
    end

    local function debugVector(value)
        if typeof(value) ~= "Vector3" then
            return "nil"
        end
        return string.format("%.3f,%.3f,%.3f", value.X, value.Y, value.Z)
    end

    local function debugCFrame(value)
        if typeof(value) ~= "CFrame" then
            return "nil"
        end
        local x, y, z = value:ToOrientation()
        return string.format(
            "P(%.3f,%.3f,%.3f) R(%.1f,%.1f,%.1f)",
            value.X,
            value.Y,
            value.Z,
            math.deg(x),
            math.deg(y),
            math.deg(z)
        )
    end

    local function debugPath(instance)
        if typeof(instance) ~= "Instance" then
            return "nil"
        end
        return debugSafe(function()
            return instance:GetFullName()
        end, instance.Name)
    end

    local function debugNetworkOwner(part)
        if not part or not part:IsA("BasePart") then
            return "n/a"
        end
        local ok, owned = pcall(isnetworkowner, part.AssemblyRootPart or part)
        return ok and tostring(owned) or "unsupported"
    end

    local function debugPart(label, part, lines)
        if not part or not part:IsA("BasePart") then
            table.insert(lines, label .. "=MISSING")
            return
        end
        local assemblyRoot = debugSafe(function()
            return part.AssemblyRootPart
        end, nil)
        table.insert(lines, string.format(
            "%s=%s | cf=%s | vel=%s | asmRoot=%s | owned=%s receiveAge=%s | massless=%s | priority=%s | collide=%s",
            label,
            debugPath(part),
            debugCFrame(part.CFrame),
            debugVector(part.AssemblyLinearVelocity),
            assemblyRoot and debugPath(assemblyRoot) or "nil",
            debugNetworkOwner(part),
            tostring(debugSafe(function() return part.ReceiveAge end, "n/a")),
            tostring(part.Massless),
            tostring(part.RootPriority),
            tostring(part.CanCollide)
        ))
        table.insert(lines, string.format(
            "%s physics: anchored=%s collisionGroup=%s transparency=%s localTransparency=%s sleeping=%s",
            label, tostring(part.Anchored), tostring(part.CollisionGroup),
            tostring(part.Transparency), tostring(part.LocalTransparencyModifier),
            tostring(debugSafe(function()
                return gethiddenproperty(assemblyRoot or part, "NetworkIsSleeping")
            end, "unavailable"))
        ))
    end

    local function debugFindJoint(character, part0Name, part1Name)
        local constraint, motor
        if not character then
            return constraint, motor
        end
        for _, joint in ipairs(character:GetDescendants()) do
            if Util.IsCharacterJoint(joint) then
                local p0, p1 = Util.GetCharacterJointParts(joint)
                if p0 and p1
                    and p0.Name == part0Name
                    and p1.Name == part1Name
                then
                    if joint:IsA("Motor6D") then
                        motor = joint
                    else
                        constraint = joint
                    end
                end
            end
        end
        return constraint, motor
    end

    local function debugJoint(label, character, part0Name, part1Name, lines)
        local constraint, motor =
            debugFindJoint(character, part0Name, part1Name)

        local function append(kind, joint)
            if not joint then
                table.insert(lines, label .. "." .. kind .. "=MISSING")
                return
            end

            local enabled = debugSafe(function()
                return joint.Enabled
            end, "n/a")
            local active = debugSafe(function()
                return joint.Active
            end, "n/a")
            local transform = debugSafe(function()
                return joint.Transform
            end, nil)
            local currentAngle = debugSafe(function()
                return joint.CurrentAngle
            end, "n/a")
            local desiredAngle = debugSafe(function()
                return joint.DesiredAngle
            end, "n/a")
            local repAngle = debugSafe(function()
                return gethiddenproperty(joint, "ReplicateCurrentAngle6D")
            end, nil)
            local repOffset = debugSafe(function()
                return gethiddenproperty(joint, "ReplicateCurrentOffset6D")
            end, nil)

            table.insert(lines, string.format(
                "%s.%s=%s | enabled=%s active=%s | Transform=%s | CurrentAngle=%s DesiredAngle=%s | RepAngle=%s RepOffset=%s",
                label,
                kind,
                debugPath(joint),
                tostring(enabled),
                tostring(active),
                debugCFrame(transform),
                tostring(currentAngle),
                tostring(desiredAngle),
                debugVector(repAngle),
                debugVector(repOffset)
            ))
        end

        append("Constraint", constraint)
        append("Motor", motor)
    end

    local function debugHumanoid(label, humanoid, lines)
        if not humanoid then
            table.insert(lines, label .. ".Humanoid=MISSING")
            return
        end

        table.insert(lines, string.format(
            "%s.Humanoid=%s | state=%s | Evaluate=%s | AutoRotate=%s | Sit=%s | MoveDirection=%s | WalkSpeed=%s",
            label,
            debugPath(humanoid),
            humanoid:GetState().Name,
            tostring(humanoid.EvaluateStateMachine),
            tostring(humanoid.AutoRotate),
            tostring(humanoid.Sit),
            debugVector(humanoid.MoveDirection),
            tostring(humanoid.WalkSpeed)
        ))

        local animator = humanoid:FindFirstChildOfClass("Animator")
        local animate = humanoid.Parent and humanoid.Parent:FindFirstChild("Animate")
        local tracks = {}
        if animator then
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                local animation = track.Animation
                table.insert(tracks, string.format(
                    "%s[%s] weight=%.3f speed=%.3f playing=%s",
                    track.Name,
                    animation and animation.AnimationId or "?",
                    track.WeightCurrent,
                    track.Speed,
                    tostring(track.IsPlaying)
                ))
            end
        end

        table.insert(lines, string.format(
            "%s.Animator=%s | Animate=%s disabled=%s | tracks=%d {%s}",
            label,
            animator and debugPath(animator) or "nil",
            animate and debugPath(animate) or "nil",
            animate and tostring(debugSafe(function()
                return animate.Disabled
            end, "n/a")) or "n/a",
            #tracks,
            table.concat(tracks, " ; ")
        ))
    end

    local function debugDistance(label, first, second, lines)
        if first and second
            and first:IsA("BasePart")
            and second:IsA("BasePart")
        then
            table.insert(lines, string.format(
                "%s=%.3f studs",
                label,
                (first.Position - second.Position).Magnitude
            ))
        end
    end

    local function buildGelatekRuntimeDump()
        local lines = {}
        local rig = backend.Rig
        local physical = backend.RealCharacter or originalCharacter
        local staticRoot = backend.StaticRoot or staticRootPart

        if type(Util.GetJointReplicationReport) == "function" then
            local ok, report = pcall(Util.GetJointReplicationReport, physical, rig)
            table.insert(lines, ok and report or ("Joint diagnostics failed: " .. tostring(report)))
        end

        local cRoot = rig and rig:FindFirstChild("HumanoidRootPart")
        local cTorso = rig and (
            rig:FindFirstChild("Torso")
            or rig:FindFirstChild("UpperTorso")
        )
        local cHead = rig and rig:FindFirstChild("Head")

        local pRoot = physical and physical:FindFirstChild("HumanoidRootPart")
        local pLower = physical and physical:FindFirstChild("LowerTorso")
        local pTorso = physical and (
            physical:FindFirstChild("UpperTorso")
            or physical:FindFirstChild("Torso")
        )
        local pHead = physical and physical:FindFirstChild("Head")

        table.insert(lines, "=== GELATEK RUNTIME DUMP ===")
        table.insert(lines, "clock=" .. tostring(os.clock()))
        table.insert(lines, "running=" .. tostring(backend.Running))
        table.insert(lines, "generation=" .. tostring(backend.RigGeneration))
        table.insert(lines, string.format(
            "generationOwner=%s globalOwnerMatch=%s resetSerial=%d resetInFlight=%s cameraBridge=%s",
            tostring(activeGenerationToken ~= nil),
            tostring(environment().UhhhhhhTBZGelatekRunToken == activeGenerationToken),
            resetRequestSerial,
            tostring(resetInFlight),
            cameraBridgeBound and "named" or (cameraBridgeConnection and "PreRender" or "off")
        ))
        table.insert(lines, "lastError=" .. tostring(backend.LastError))
        table.insert(lines, "startupError=" .. tostring(environment().UhhhhhhTBZGelatekStartupError or "none"))
        table.insert(lines, "lastFlingError=" .. tostring(backend.LastFlingError))
        table.insert(lines, "detectedRig=" .. tostring(backend.DetectedRig))
        table.insert(lines, "effectivePD=" .. tostring(backend.EffectivePermanentDeath))
        table.insert(lines, "MODE_POLICY requestedPD=" .. tostring(options.PermanentDeath == true)
            .. " nextNormalGenerationPD=" .. tostring(backend.ModePolicy.NextGeneration(false))
            .. " smoothCamera=" .. tostring(Reanimate.SmoothCam == true)
            .. " cameraFocusManaged=" .. tostring(Reanimate.CameraFocusManaged == true))
        table.insert(lines, "resetToPD=" .. tostring(options.ResetTurnsPD))
        table.insert(lines, "RESET_PD intent=" .. tostring(backend.ResetPDIntent)
            .. " completedSerial=" .. tostring(backend.ResetPDCompletedSerial)
            .. " error=" .. tostring(backend.ResetPDLastError or "none")
            .. " nativePD=" .. tostring(environment().UhhhhhhTBZGelatekRuntimePD))
        table.insert(lines, "fallbackPD=" .. tostring(backend.PermanentDeathFallback))
        table.insert(
            lines,
            "options=" .. game:GetService("HttpService"):JSONEncode(options)
        )
        table.insert(lines, "controller=" .. debugPath(rig))
        table.insert(lines, "physical=" .. debugPath(physical))
        table.insert(lines, "staticRoot=" .. debugPath(staticRoot))
        table.insert(lines, string.format(
            "ROTATION RotationType=%s Shiftlocked=%s MouseLocked=%s DisableDirectionalWalking=%s",
            tostring(debugSafe(function()
                return UserSettings():GetService("UserGameSettings").RotationType
            end, "n/a")),
            tostring(Reanimate.Shiftlocked),
            tostring(
                type(Reanimate.Camera) == "table"
                and type(Reanimate.Camera.IsMouseLocked) == "function"
                and Reanimate.Camera:IsMouseLocked()
                or false
            ),
            tostring(options.DisableDirectionalWalking)
        ))

        debugHumanoid(
            "C",
            rig and rig:FindFirstChildOfClass("Humanoid"),
            lines
        )
        debugHumanoid(
            "P",
            physical and physical:FindFirstChildOfClass("Humanoid"),
            lines
        )

        debugPart("C.Root", cRoot, lines)
        debugPart("C.Torso", cTorso, lines)
        debugPart("C.Head", cHead, lines)
        debugPart("P.Root", pRoot, lines)
        debugPart("P.LowerTorso", pLower, lines)
        debugPart("P.Torso", pTorso, lines)
        debugPart("P.Head", pHead, lines)
        debugPart("StaticRoot", staticRoot, lines)

        debugDistance("DIST.Root(C-P)", cRoot, pRoot, lines)
        debugDistance("DIST.Torso(C-P)", cTorso, pTorso, lines)
        debugDistance("DIST.Head(C-P)", cHead, pHead, lines)
        debugDistance("DIST.Static-C.Root", staticRoot, cRoot, lines)
        debugDistance("DIST.Static-P.Root", staticRoot, pRoot, lines)

        if pTorso and pTorso:IsA("BasePart") then
            local torsoIsRoot = debugSafe(function()
                return pTorso.AssemblyRootPart == pTorso
            end, false)
            table.insert(lines, string.format(
                "FALLBACK_AUTHORITY TorsoAssemblyRoot=%s TorsoPriority=%s TorsoMassless=%s HeadPriority=%s HeadMassless=%s RootPriority=%s RootMassless=%s",
                tostring(torsoIsRoot),
                tostring(pTorso.RootPriority),
                tostring(pTorso.Massless),
                tostring(pHead and pHead.RootPriority or "nil"),
                tostring(pHead and pHead.Massless or "nil"),
                tostring(pRoot and pRoot.RootPriority or "nil"),
                tostring(pRoot and pRoot.Massless or "nil")
            ))
        end

        local poseDebug = debugSafe(function()
            return type(Context.GetGelatekPoseDebug) == "function" and Context.GetGelatekPoseDebug(rig) or nil
        end, nil)
        poseDebug = type(poseDebug) == "table" and poseDebug or {}
        table.insert(lines, string.format(
            "ANIMATION_BRIDGE PoseCharacter=%s PoseSerial=%s CachedJoints=%s RobloxTrackActive=%s",
            debugPath(poseDebug.Character),
            tostring(poseDebug.Serial or "unavailable"),
            tostring(poseDebug.CachedJoints or 0),
            tostring(poseDebug.RobloxTrackActive == true)
        ))
        table.insert(lines, "FOLLOWER_PHASE phase=" .. tostring(backend.LastFollowerPhase or "none")
            .. " age=" .. tostring(backend.LastFollowerAt and os.clock() - backend.LastFollowerAt or "never")
            .. " paused=" .. tostring(rebindInProgress)
            .. " nativeError=" .. tostring(environment().UhhhhhhTBZGelatekFollowerError or "none")
            .. " error=" .. tostring(backend.FollowerError or "none"))

        if rig then
            debugJoint("C.RootTorso", rig, "HumanoidRootPart", "Torso", lines)
            debugJoint("C.TorsoHead", rig, "Torso", "Head", lines)
        end

        if physical then
            if physical:FindFirstChild("UpperTorso") then
                debugJoint(
                    "P.RootLower",
                    physical,
                    "HumanoidRootPart",
                    "LowerTorso",
                    lines
                )
                debugJoint(
                    "P.LowerUpper",
                    physical,
                    "LowerTorso",
                    "UpperTorso",
                    lines
                )
                debugJoint(
                    "P.UpperHead",
                    physical,
                    "UpperTorso",
                    "Head",
                    lines
                )
            else
                debugJoint(
                    "P.RootTorso",
                    physical,
                    "HumanoidRootPart",
                    "Torso",
                    lines
                )
                debugJoint(
                    "P.TorsoHead",
                    physical,
                    "Torso",
                    "Head",
                    lines
                )
            end
        end

        local env = (getgenv and getgenv()) or shared or _G
        table.insert(lines, "--- CFrameAlign ---")
        local stats = env.UhhhhhhTBZGelatekAlignStats
        if type(stats) == "table" then
            for part, stat in pairs(stats) do
                if typeof(part) == "Instance" and type(stat) == "table" then
                    table.insert(lines, string.format(
                        "%s | calls=%s owned=%s unowned=%s currentOwned=%s | targetPart=%s target=%s | errorBefore=%s errorAfter=%s blocked=%s",
                        debugPath(part),
                        tostring(stat.Calls),
                        tostring(stat.OwnedCalls),
                        tostring(stat.UnownedCalls),
                        tostring(stat.NetworkOwned),
                        tostring(stat.Part1Name),
                        debugCFrame(stat.TargetCFrame),
                        tostring(stat.ErrorBefore),
                        tostring(stat.ErrorAfter),
                        tostring(stat.LastBlockedReason or "none")
                    ))
                end
            end
        else
            table.insert(lines, "CFrameAlign stats unavailable")
        end

        if type(Reanimate.ShouldBodyHidePart) == "function" then
            table.insert(lines, string.format(
                "BodyHide Root=%s Torso=%s Head=%s",
                tostring(Reanimate.ShouldBodyHidePart("HumanoidRootPart")),
                tostring(Reanimate.ShouldBodyHidePart("Torso")),
                tostring(Reanimate.ShouldBodyHidePart("Head"))
            ))
        end

        local detachedAccessoryWelds = {}
        for weld, originalEnabled in pairs(accessoryBodyHideWeldStates) do
            if typeof(weld) == "Instance" and weld.Parent then
                local enabled = debugSafe(function()
                    return weld.Enabled
                end, "n/a")
                if enabled == false then
                    table.insert(
                        detachedAccessoryWelds,
                        string.format(
                            "%s(original=%s)",
                            debugPath(weld),
                            tostring(originalEnabled)
                        )
                    )
                end
            end
        end
        table.insert(
            lines,
            "ACCESSORY_HIDE detachedWelds="
                .. tostring(#detachedAccessoryWelds)
                .. " {"
                .. table.concat(detachedAccessoryWelds, " ; ")
                .. "}"
        )

        local recoveryNames = {}
        local recoveryPhysical = backend.RealCharacter or originalCharacter
        if rig and recoveryPhysical then
            for _, pair in ipairs(getGelatekRecoveryPairs(rig, recoveryPhysical)) do
                table.insert(recoveryNames, tostring(pair.Name))
            end
        end
        table.insert(
            lines,
            "RECOVERY_COVERAGE PD="
                .. tostring(backend.EffectivePermanentDeath)
                .. " {"
                .. table.concat(recoveryNames, ", ")
                .. "}"
        )

        local physicalAnimatorCount = 0
        local physicalAnimateState = "missing"
        if physical then
            for _, descendant in ipairs(physical:GetDescendants()) do
                if descendant:IsA("Animator") then
                    physicalAnimatorCount += 1
                end
            end
            local physicalAnimate = physical:FindFirstChild("Animate")
            if physicalAnimate and physicalAnimate:IsA("LocalScript") then
                physicalAnimateState =
                    physicalAnimate.Disabled and "disabled" or "enabled"
            end
        end
        table.insert(
            lines,
            "NONPD_ROOT_FOLLOW RootIsAssemblyRoot="
                .. tostring(
                    pRoot
                    and debugSafe(
                        function()
                            return pRoot.AssemblyRootPart == pRoot
                        end,
                        false
                    )
                    or false
                )
                .. " RootOwned="
                .. tostring(pRoot and debugNetworkOwner(pRoot) or "n/a")
                .. " PhysicalAnimators="
                .. tostring(physicalAnimatorCount)
                .. " PhysicalAnimate="
                .. tostring(physicalAnimateState)
        )

        table.insert(
            lines,
            "DIRECT_CORRECTION enabled="
                .. tostring(options.DirectPositionCorrection)
                .. " recoveryDistance="
                .. tostring(backend.NonPDRecoveryDistance)
        )
	table.insert(lines, "BODY_CHAIN retained=" .. tostring(backend.KeepBodyChain==true)
            .. " reason=" .. tostring(backend.BodyChainReason or "waiting")
            .. " root=" .. debugPath(backend.BodyChain and backend.BodyChain.Root)
            .. " owned=" .. tostring(backend.BodyChain and backend.BodyChain.Owned)
            .. " blocked=" .. tostring(backend.BodyChain and backend.BodyChain.LastError or "none"))
        table.insert(lines,"BODY_STEP error=" .. tostring(environment().UhhhhhhTBZGelatekBodyStepError or "none")
            .. " pdTransition=" .. tostring(environment().UhhhhhhTBZGelatekPDTransitionPending==true)
            .. " maintenanceSeconds=.1 fontSizing=property-event")
        local headMoverNames = {}
        if pHead then
            for _, child in ipairs(pHead:GetChildren()) do
                if child:IsA("BodyMover")
                    or child:IsA("LinearVelocity")
                    or child:IsA("AngularVelocity")
                then
                    table.insert(
                        headMoverNames,
                        child.ClassName .. ":" .. child.Name
                    )
                end
            end
        end
        table.insert(
            lines,
            "HEAD_TRANSPORT BodyMovers={"
                .. table.concat(headMoverNames, ", ")
                .. "} hidden="
                .. tostring(
                    type(Reanimate.ShouldBodyHidePart) == "function"
                    and Reanimate.ShouldBodyHidePart("Head") == true
                    or false
                )
        )
        table.insert(
            lines,
            "HEAD_TRANSPORT mode=" .. tostring(pdHeadFollower and pdHeadFollower.Mode or "waiting") .. " writes="
                .. tostring(pdHeadFollower and pdHeadFollower.Writes or 0)
                .. " propertyAccepted=" .. tostring(pdHeadFollower and pdHeadFollower.AcceptedWrites or 0)
                .. " observerVerified=false"
                .. " owned="
                .. tostring(pdHeadFollower and pdHeadFollower.LastOwned ~= nil
                    and tostring(pdHeadFollower.LastOwned) or "n/a")
                .. " error="
                .. tostring(pdHeadFollower and pdHeadFollower.LastError or "none")
                .. " positionError="
                .. tostring(pdHeadFollower and pdHeadFollower.PositionError or 0)
                .. " unownedSeconds="
                .. tostring(pdHeadFollower and pdHeadFollower.OwnershipLossSince
                    and (os.clock() - pdHeadFollower.OwnershipLossSince) or 0)
                .. " blocked=" .. tostring(pdHeadFollower and pdHeadFollower.LastBlockedReason or "none")
                .. " phase=" .. tostring(pdHeadFollower and pdHeadFollower.LastPhase or "none")
                .. " lastWriteAge=" .. tostring(pdHeadFollower and pdHeadFollower.LastSuccessfulWriteAt
                    and os.clock() - pdHeadFollower.LastSuccessfulWriteAt or "never")
                .. " accessoryError=" .. tostring(pdHeadFollower and pdHeadFollower.AccessoryError or "none")
                .. " headHideBlocked=" .. tostring(backend.HeadHideAccessoryBlockedReason or "none")
                .. " accessoryWrites=" .. tostring(pdHeadFollower and pdHeadFollower.AccessoryWrites or 0)
                .. " lifecycleWarning=" .. tostring(pdHeadFollower and pdHeadFollower.LifecycleWarning or "none")
                .. " route=" .. tostring(pdHeadFollower and pdHeadFollower.Route or "waiting")
		.. " localDisplayError=" .. tostring(pdHeadFollower and pdHeadFollower.LocalDisplayError or "none")
                .. " sampleAnchor=" .. debugPath(pdHeadFollower and pdHeadFollower.RelativeSample and pdHeadFollower.RelativeSample.Anchor)
        )
        if pdHeadFollower then
            local position, orientation = pdHeadFollower.LinearMover, pdHeadFollower.AngularMover
            table.insert(lines, "HEAD_CFRAME ownedWrites=" .. tostring(pdHeadFollower.OwnedWrites or 0)
                .. " ready=" .. tostring(pdHeadFollower.Mode == "CFrame-first owned Head"
                    and pdHeadFollower.LastOwned == true and pdHeadFollower.LastError == nil
                    and pdHeadFollower.LastBlockedReason == nil and pdHeadFollower.LastSuccessfulWriteAt ~= nil
                    and os.clock() - pdHeadFollower.LastSuccessfulWriteAt < 0.25)
                .. " control=CFrame-first-core"
                .. " position=" .. debugPath(position)
                .. " orientation=" .. debugPath(orientation)
                .. " attachment=" .. debugPath(pdHeadFollower.Attachment)
                .. " positionEnabled=" .. tostring(position and debugSafe(function() return position.Enabled end, false) or false)
                .. " orientationEnabled=" .. tostring(orientation and debugSafe(function() return orientation.Enabled end, false) or false)
                .. " nativeVelocity=" .. tostring(pdHeadFollower.NativeVelocity or "n/a")
                .. " rootRefCleared=" .. tostring(pdHeadFollower.RepRootCleared == true)
                .. " rootRefClearError=" .. tostring(pdHeadFollower.RepRootClearError or "none"))
        end

        local accessoryStateCount = 0
        local accessoryLiveStateCount = 0
        local accessoryWriteCount = 0
        local accessoryOwnership = {}
        for handle, state in pairs(accessoryRecoveryStates) do
            if handle and type(state) == "table" then
                accessoryStateCount += 1
                if handle.Parent then accessoryLiveStateCount += 1 end
                accessoryWriteCount += tonumber(state.Writes) or 0
                local source = state.OwnershipSource or "unknown"
                accessoryOwnership[source] =
                    (accessoryOwnership[source] or 0) + 1
                table.insert(lines, "ACCESSORY_FOLLOWER part=" .. debugPath(handle)
                    .. " controller=" .. debugPath(state.Controller)
                    .. " owned=" .. tostring(state.LastOwned)
                    .. " writeAge=" .. tostring(state.LastSuccessfulWriteAt and os.clock() - state.LastSuccessfulWriteAt or "never")
                    .. " blocked=" .. tostring(state.LastBlockedReason or "none")
                    .. " error=" .. tostring(state.LastWriteError or "none")
                    .. " phase=" .. tostring(state.LastPhase or "none")
                    .. " velocity=" .. tostring(state.LinearVelocity or "n/a")
                    .. " angular=" .. tostring(state.AngularVelocity or "n/a")
                    .. " rootRefCleared=" .. tostring(state.RepRootCleared == true)
                    .. " rootRefClearError=" .. tostring(state.RepRootClearError or "none"))
            end
        end
        local ownershipSummary = {}
        for source, count in pairs(accessoryOwnership) do
            table.insert(
                ownershipSummary,
                tostring(source) .. "=" .. tostring(count)
            )
        end
        table.sort(ownershipSummary)
        table.insert(
            lines,
            "ACCESSORY_TRANSPORT states="
                .. tostring(accessoryStateCount)
                .. " live=" .. tostring(accessoryLiveStateCount)
                .. " writes="
                .. tostring(accessoryWriteCount)
                .. " {"
                .. table.concat(ownershipSummary, ", ")
                .. "}"
        )

        table.insert(lines,"ACCESSORY_LIFETIME_ERROR=" .. tostring(backend.AccessoryLifetimeError or "none"))
        local trackedCount = 0
        for source, record in pairs(physicalIndex.AccessoryRecords or {}) do
            trackedCount += 1
            table.insert(lines, "ACCESSORY_LIFETIME id=" .. tostring(record.Id)
                .. " name=" .. tostring(record.Name) .. " source=" .. debugPath(source)
                .. " sourceParent=" .. debugPath(source.Parent) .. " handleParent=" .. debugPath(record.Handle and record.Handle.Parent)
                .. " sourceDestroyed=" .. tostring(record.SourceDestroyed == true)
                .. " handleDestroyed=" .. tostring(record.HandleDestroyed == true)
                .. " controller=" .. debugPath(record.Controller)
                .. " blocked=" .. tostring(record.Blocked or "none")
                .. " event=" .. tostring(record.LastEvent or "none")
                .. " repairs=" .. tostring(record.Repairs or 0)
                .. " proxyRebuilds=" .. tostring(record.ProxyRebuilds or 0))
        end
        table.insert(lines, "ACCESSORY_EXPECTED count=" .. tostring(trackedCount))

        table.insert(
            lines,
            "WRITE_METHODS GelatekTorso="
                .. tostring(replicationWriters.GelatekTorso)
                .. " GelatekHead="
                .. tostring(replicationWriters.GelatekHead)
        )
        local torsoRepRootParts = 0
        local torsoRepRootWrites = 0
        local torsoRepRootMethods = {}
        for part, state in pairs(torsoRepRootStates) do
            if part and part.Parent and state.Active and not state.RestorePending and not state.LastError then
                torsoRepRootParts += 1
                torsoRepRootWrites += tonumber(state.Writes) or 0
                torsoRepRootMethods[state.Property or PhysicsRoot.Property] = true
            end
            table.insert(lines, "TORSO_REP_ROOT part=" .. debugPath(part)
                .. " requested=" .. tostring(state.Requested or replicationWriters.GelatekTorso)
                .. " property=" .. tostring(state.Property or "none")
                .. " reference=" .. debugPath(state.Reference)
                .. " restorePending=" .. tostring(state.RestorePending == true)
                .. " fallback=" .. tostring(state.FallbackReason or "none")
                .. " error=" .. tostring(state.LastError or "none"))
        end
        local activeTorsoRepRootMethods = {}
        for method in pairs(torsoRepRootMethods) do table.insert(activeTorsoRepRootMethods, method) end
        table.sort(activeTorsoRepRootMethods)
        table.insert(
            lines,
            "PHYSICS_REP_ROOT torsoParts="
                .. tostring(torsoRepRootParts)
                .. " torsoWrites="
                .. tostring(torsoRepRootWrites)
                .. " rootFlingLinked="
                .. tostring(rootRepRootState.Active == true)
                .. " nativeTorsoFallback=true"
                .. " requested=" .. tostring(replicationWriters.GelatekTorso)
                .. " active=" .. (#activeTorsoRepRootMethods > 0 and table.concat(activeTorsoRepRootMethods, ",") or "Gelatek Physics")
                .. " fallback=" .. tostring(backend.TorsoRepRootFallbackReason or "none")
                .. " blocked=" .. tostring(backend.TorsoRepRootBlockedReason or "none")
                .. " lastError="
                .. tostring(backend.TorsoRepRootLastError)
        )

        table.insert(lines, "ROOT_REF_ADAPTER " .. PhysicsRoot.Describe())
        local rootStats = PhysicsRoot.Snapshot()
        table.insert(lines, "ROOT_REF_COST handles=" .. rootStats.Handles .. " writes=" .. rootStats.Writes
            .. " cached=" .. rootStats.Cached .. " failures=" .. rootStats.Failures
            .. " unresolvedRestores=" .. rootStats.UnverifiedRestores)
        table.insert(lines, "=== END GELATEK RUNTIME DUMP ===")
        return table.concat(lines, "\n")
    end

    backend.GetDebugDump = buildGelatekRuntimeDump
    local debugEnvironment = (getgenv and getgenv()) or shared or _G
    debugEnvironment.UhhhhhhGelatekDebugDump = function()
        local dump = buildGelatekRuntimeDump()
        warn(dump)
        return dump
    end

    local function copyRuntimeDump(dump)
        -- An executor may expose a broken local alias but a working global one.
        -- A successful pcall alone is not proof of an OS clipboard write.
        local candidates, seen = {}, {}
        local function add(candidate)
            if type(candidate) == "function" and not seen[candidate] then
                seen[candidate] = true
                table.insert(candidates, candidate)
            end
        end
        add(setclipboard)
        add(toclipboard)
        if type(debugEnvironment) == "table" then
            add(debugEnvironment.setclipboard)
            add(debugEnvironment.toclipboard)
        end
        if type(_G) == "table" then
            add(_G.setclipboard)
            add(_G.toclipboard)
        end
        local reader = type(getclipboard) == "function" and getclipboard
            or (type(debugEnvironment) == "table" and type(debugEnvironment.getclipboard) == "function"
                and debugEnvironment.getclipboard)
            or (type(_G) == "table" and type(_G.getclipboard) == "function" and _G.getclipboard)
        local requested, mismatch = false, false
        for _, candidate in ipairs(candidates) do
            local ok, result = pcall(candidate, dump)
            if ok then
                local readOk, text = false, nil
                if reader then readOk, text = pcall(reader) end
                if readOk and type(text) == "string" then
                    if text == dump then return "verified" end
                    mismatch = true
                elseif result ~= false then
                    -- nil is a normal no-return setter result. Without a usable
                    -- reader this remains a request, not a verified copy.
                    requested = true
                end
            end
        end
        if requested then return "requested" end
        return mismatch and "mismatch" or "unavailable"
    end

    local function createRuntimeDiagnostics(parent, showPage)
        local dumpPage, dumpBox, statusText
        local openDump
        parent.Destroying:Once(function()
            if dumpPage then dumpPage:Destroy() end
            if debugEnvironment.UhhhhhhGelatekOpenRuntimeState == openDump then
                debugEnvironment.UhhhhhhGelatekOpenRuntimeState = nil
            end
        end)
        local function selectDump()
            if not dumpBox or not dumpBox.Parent then return end
            pcall(function()
                dumpBox:CaptureFocus()
                dumpBox.CursorPosition = #dumpBox.Text + 1
                dumpBox.SelectionStart = 1
            end)
        end
        local copyButton, copyLabel = UI.CreateButton(parent, "Copy Gelatek Runtime State", 12)
        copyButton.Name = "CopyGelatekRuntimeState"
        copyButton.Active, copyButton.Interactable, copyButton.Selectable = true, true, true
        if copyLabel then copyLabel.Active, copyLabel.Interactable = false, false end
        openDump = function()
                local built, dump = pcall(buildGelatekRuntimeDump)
                if not built then dump = "Gelatek runtime dump failed: " .. tostring(dump) end
                warn(dump)
                -- One reusable, lazily created native page. No truncated dump,
                -- accumulating labels, or dependency on a working clipboard API.
                if not dumpPage or not dumpPage.Parent then
                    dumpPage = UI.CreatePage()
                    dumpPage.Visible, dumpPage.Interactable = false, false
                    UI.CreateButton(dumpPage, "< Back to Advanced Gelatek", 14)
                        .Activated:Connect(function() showPage(dumpPage, parent) end)
                    statusText = UI.CreateText(dumpPage, "", 11, Enum.TextXAlignment.Left)
                    UI.CreateButton(dumpPage, "Select all runtime text", 12).Activated:Connect(selectDump)
                    dumpBox = UI.CreateTextbox(dumpPage, "", "Runtime state", 10)
                    dumpBox.Name = "GelatekRuntimeState"
                    dumpBox.RichText, dumpBox.MultiLine = false, true
                    dumpBox.ClearTextOnFocus, dumpBox.TextEditable = false, true
                    dumpBox.TextXAlignment, dumpBox.TextYAlignment = Enum.TextXAlignment.Left, Enum.TextYAlignment.Top
                end
                statusText.Text, dumpBox.Text = "Runtime state ready. Select all, then Copy.", dump
                showPage(parent, dumpPage)
                selectDump()
                -- Input/focus may stay disabled until the entry tween ends.
                -- Select again after it, without waiting on any clipboard API.
                task.delay(0.3, function()
                    if dumpPage and dumpPage.Parent and dumpPage.Visible and dumpPage.Interactable then selectDump() end
                end)
                task.defer(function()
                    local state = copyRuntimeDump(dump)
                    local message = state == "verified" and "Clipboard verified. The full dump is also selected below."
                        or state == "requested" and "Copy requested, but not verified. Use Select all, then Copy if needed."
                        or state == "mismatch" and "Clipboard did not update. Use Select all, then Copy."
                        or "Clipboard unavailable. Use Select all, then Copy."
                    if statusText and statusText.Parent then statusText.Text = message end
                    pcall(StarterGui.SetCore, StarterGui, "SendNotification", {
                        Title = "Gelatek runtime state", Text = message, Duration = 5,
                    })
                end)
                return dump
        end
        copyButton.Activated:Connect(openDump)
        debugEnvironment.UhhhhhhGelatekOpenRuntimeState = openDump
        return copyButton
    end

    function backend.Config(parent)
        local ok, missing = compatibility()
        local character = Player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local detected = humanoid and humanoid.RigType.Name or "unknown"

        UI.CreateText(
            parent,
            "<b>Gelatek</b>\nDetected rig: " .. detected,
            18,
            Enum.TextXAlignment.Center
        )
        UI.CreateText(
            parent,
            "Non-PD keeps the original root and torso connected when their motors are available. PD and torso/bullet modes use detached followers.",
            10,
            Enum.TextXAlignment.Center
        )
        UI.CreateText(
            parent,
            "Head writer lives in Animation Options.",
            10,
            Enum.TextXAlignment.Center
        )
        UI.CreateSeparator(parent)

        UI.CreateText(parent, "<b>Basic</b>", 14, Enum.TextXAlignment.Left)
        addSwitch(parent, "Start PD", "PermanentDeath")
        addSwitch(parent, "Reset -> PD", "ResetTurnsPD",
            "Reset once. Come back PD. Pretty neat.")
        addSwitch(parent, "Anti-sleep", "AntiSleep",
            "Tiny follower dither. Netless still does its own thing.")
        addSwitch(parent, "Ragdoll Self Collision", "RagdollSelfCollision",
            "Let the ragdoll hit itself like a ragdoll should.")
        addSwitch(
            parent,
            "Direct Position Correction",
            "DirectPositionCorrection",
            "Corrects owned limbs and accessories before physics, including constraint alignment mode."
        )
        addSwitch(parent, "Teleport Back When Voided", "TeleportBackWhenVoided")
        addSwitch(parent, "Recover Before Void", "RecoverBeforeVoid",
            "Yanks the controller back before the void eats it.")
        addSwitch(
            parent,
            "Disable Directional Walking",
            "DisableDirectionalWalking",
            "Uses vanilla MovementRelative unshiftlocked and CameraRelative in shiftlock/first-person."
        )
        addSwitch(
            parent,
            "Show me how I look!",
            "ShowMeHowILook",
            "Preview the committed physics Head pose at full rate. Keep this off for the latest local controller pose."
        )

        UI.CreateText(parent, "<b>Physical recovery</b>", 12, Enum.TextXAlignment.Left)
        local recoveryDistance = UI.CreateSlider(
            parent, "Recovery Distance (studs)", options.PhysicalRecoveryDistance, 0, 50, 1
        )
        recoveryDistance.Changed:Connect(function(value)
            local distance = tonumber(value) or 25
            if distance ~= distance then distance = 25 end
            options.PhysicalRecoveryDistance = math.clamp(distance, 0, 50)
            recoveryDistance.Value = options.PhysicalRecoveryDistance
            backend.NonPDRecoveryDistance = options.PhysicalRecoveryDistance
            persistOption("Recovery Distance")
        end)
        UI.CreateText(parent,
            "0 = constant recovery. 1–50 = distance in studs. Head and managed accessories use their dedicated followers.",
            9, Enum.TextXAlignment.Center)

        local advancedPage = UI.CreatePage()
        advancedPage.ZIndex = 3
        advancedPage.Visible = false
        advancedPage.Interactable = false

        local function showPage(fromPage, toPage)
            if UI.Workspace and UI.Workspace.ResolvePage then
                local destination = UI.Workspace.ResolvePage(toPage)
                local source = UI.Workspace.ResolvePage(fromPage)
                if toPage == parent or (source and UI.Workspace.Pages[source].Parent == destination) then
                    UI.Workspace.Back(source or fromPage, destination or toPage)
                else
                    UI.Workspace.Open(toPage, source or fromPage)
                end
                return
            end
            if fromPage then
                fromPage.Interactable = false
                fromPage.Visible = false
            end
            toPage.Visible = true
            toPage.Interactable = true
        end

        local advancedButton = UI.CreateButton(parent, "Advanced Gelatek >", 15)
        advancedButton.Activated:Connect(function()
                showPage(parent, advancedPage)
            end)
        -- Backend selection rebuilds the embedded canvas controls. Release the
        -- old detached page with its launch control instead of leaking it.
        advancedButton.Destroying:Once(function() advancedPage:Destroy() end)

        UI.CreateButton(advancedPage, "< Back to Gelatek", 16)
            .Activated:Connect(function()
                showPage(advancedPage, parent)
            end)

        UI.CreateText(
            advancedPage,
            "<b>Advanced Gelatek</b>",
            18,
            Enum.TextXAlignment.Center
        )
        UI.CreateText(
            advancedPage,
            "The weird stuff. Touch it if you know why you're here.",
            9,
            Enum.TextXAlignment.Center
        )

        UI.CreateText(advancedPage, "<b>Rig / animation</b>", 12, Enum.TextXAlignment.Left)
        addSwitch(advancedPage, "Match Avatar Rig", "MatchAvatarRig", "Preserves R15 body and accessory joints; legacy movesets use an R6 animation driver. Applies on next reanimation.")
        addSwitch(
            advancedPage,
            "Disable Gelatek's Own Animator",
            "AnimationsDisabled",
            "The controller Roblox Animator is still preserved for generic AnimationTrack content."
        )
        addSwitch(
            advancedPage,
            "Break Accessory Welds",
            "BreakAccessoryWelds",
            "Lets controller accessory joints drive the original handles. Non-PD retains the torso ownership workaround; PD uses reversible handoffs and restores surviving welds if ownership is lost."
        )

        UI.CreateText(advancedPage, "<b>Core followers</b>", 12, Enum.TextXAlignment.Left)
        UI.CreateText(advancedPage,
            "CFrame pose control is built in. Physics only provides bounded ownership support; intact accessory assemblies stay intact.",
            9, Enum.TextXAlignment.Left)
        addSwitch(
            advancedPage,
            "Disable Tweaks",
            "DisableTweaks",
            "Disables Gelatek's ownership/stability tweaks and can lose physical parts."
        )

        UI.CreateText(advancedPage, "<b>Optional extras</b>", 12, Enum.TextXAlignment.Left)
        addSwitch(advancedPage, "Load Library", "LoadLibrary")
        addSwitch(advancedPage, "Detailed Credits", "DetailedCredits")

        UI.CreateText(advancedPage, "<b>Flinging</b>", 12, Enum.TextXAlignment.Left)
        addSwitch(advancedPage, "Torso Fling", "TorsoFling")
        addSwitch(advancedPage, "Bullet Enabled", "BulletEnabled")
        addSwitch(advancedPage, "Bullet Run After Reanimate", "BulletRunAfter")
        addSwitch(advancedPage, "Lock Bullet On Torso", "BulletLockTorso")

        UI.CreateText(advancedPage, "<b>Diagnostics</b>", 12, Enum.TextXAlignment.Left)
        createRuntimeDiagnostics(advancedPage, showPage)

        if not ok then
            UI.CreateText(
                parent,
                "Missing: " .. table.concat(missing, ", "),
                10,
                Enum.TextXAlignment.Center
            )
        end
    end

    local function snapshotWorkspaceModels()
        local result = {}
        for _, child in ipairs(workspace:GetChildren()) do
            if child:IsA("Model") then
                result[child] = true
            end
        end
        return result
    end

    local function humanoidIsDead(humanoid)
        if not humanoid or humanoid.Health <= 0 then
            return true
        end
        local ok, state = pcall(humanoid.GetState, humanoid)
        return ok and state == Enum.HumanoidStateType.Dead
    end

    local function looksLikeControllerRig(model, before, preserved)
        if not model or not model:IsA("Model") or model == originalCharacter then
            return false
        end
        if not model.Parent then
            return false
        end
        local humanoid = model:FindFirstChildOfClass("Humanoid")
        local root = model:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root or not root:IsA("BasePart") then
            return false
        end
        local bodyNames = humanoid.RigType.Name == "R15" and {
            "Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand",
            "RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
            "RightUpperLeg", "RightLowerLeg", "RightFoot",
        } or {"Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}
        for _, partName in ipairs(bodyNames) do
            local part = model:FindFirstChild(partName)
            if not part or not part:IsA("BasePart") then
                return false
            end
        end
        if humanoidIsDead(humanoid) then
            return false
        end
        local owners = environment().UhhhhhhTBZGelatekControllerOwners
        if type(owners) ~= "table"
            or owners[model] ~= activeGenerationToken
        then
            return false
        end
        -- The vendor stamps exact Instance ownership. Snapshot freshness remains
        -- a second check, except for the one deliberately preserved controller.
        return model == preserved or not before[model]
    end

    local function findControllerRig(before, preserved)
        local direct = workspace:FindFirstChild("GelatekReanimate")
            or workspace:FindFirstChild("ReanimatedRig")
            or workspace:FindFirstChild(Player.Name .. "_Fake")
        if looksLikeControllerRig(direct, before, preserved) then
            return direct
        end
        if looksLikeControllerRig(Player.Character, before, preserved) then
            return Player.Character
        end
        for _, child in ipairs(workspace:GetChildren()) do
            if looksLikeControllerRig(child, before, preserved) then
                return child
            end
        end
        return nil
    end

    local function disableBackendAnimations(rig)
        local animate = rig and rig:FindFirstChild("Animate")
        if animate and animate:IsA("LocalScript") then
            animate.Disabled = true
        end
        local humanoid = rig and rig:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if animator then
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                pcall(function()
                    track:Stop(0)
                end)
            end
        end
    end

    local function captureOriginalFace(character)
        local head = character and character:FindFirstChild("Head")
        local face = head and head:FindFirstChildWhichIsA("Decal")
        if face then
            local ok, clone = pcall(function()
                return face:Clone()
            end)
            if ok then
                originalFace = clone
            end
        end
    end

    local function ensureVisibleHead(_rig)
        -- Fake controller remains invisible.
    end

    local function hideControllerBody(rig)
        if not rig then
            return
        end
        pcall(function()
            rig:SetAttribute("UhhhhhhGelatekRespawnPlaceholder", nil)
        end)
        local showController = Reanimate.ShowControllerCharacter == true
        for _, part in ipairs(rig:GetChildren()) do
            if part:IsA("BasePart") then
                part.Transparency =
                    showController and (part.Name == "HumanoidRootPart" and 1 or 0.35) or 1
            end
        end
    end

    local function destroyRespawnPlaceholder()
        table.clear(placeholderParts)
        if placeholderModel then
            pcall(function()
                placeholderModel:Destroy()
            end)
            placeholderModel = nil
        end
    end

    local function createPlaceholderPart(sourcePart)
        local ok, proxy = pcall(function()
            return sourcePart:Clone()
        end)
        if not ok or not proxy or not proxy:IsA("BasePart") then
            proxy = Instance.new("Part")
            proxy.Name = sourcePart.Name
            proxy.Size = sourcePart.Size
            pcall(function()
                proxy.Shape = sourcePart.Shape
            end)
        end
        for _, child in ipairs(proxy:GetChildren()) do
            if not child:IsA("DataModelMesh") then
                child:Destroy()
            else
                pcall(function()
                    child.TextureId = ""
                end)
            end
        end
        proxy.Name = sourcePart.Name
        proxy.Anchored = true
        proxy.CanCollide = false
        proxy.CanQuery = false
        proxy.CanTouch = false
        proxy.CastShadow = false
        proxy.Massless = true
        proxy.Color = Color3.fromRGB(255, 45, 45)
        proxy.Material = Enum.Material.SmoothPlastic
        proxy.Transparency = 1
        pcall(function()
            proxy.TextureID = ""
        end)
        pcall(function()
            proxy.LocalTransparencyModifier = 0
        end)
        return proxy
    end

    local function ensureRespawnPlaceholder(rig)
        if placeholderModel and placeholderModel.Parent then
            return placeholderModel
        end
        destroyRespawnPlaceholder()
        local model = Instance.new("Model")
        model.Name = "_UhhhhhhGelatekResetPlaceholder"
        model.Archivable = false
        model.Parent = workspace
        placeholderModel = model
        for _, sourcePart in ipairs(rig:GetChildren()) do
            if sourcePart:IsA("BasePart") and sourcePart.Name ~= "HumanoidRootPart" then
                local proxy = createPlaceholderPart(sourcePart)
                proxy.CFrame = sourcePart.CFrame
                proxy.Size = sourcePart.Size
                proxy.Parent = model
                placeholderParts[sourcePart] = proxy
            end
        end
        return model
    end

    local function ensureStaticRoot(controllerRoot)
        if not staticRootPart or not staticRootPart.Parent then
            local part = Instance.new("Part")
            part.Name = "_UhhhhhhGelatekStaticRoot"
            part.Archivable = false
            part.Anchored = true
            part.CanCollide = false
            part.CanQuery = false
            part.CanTouch = false
            part.CastShadow = false
            part.Massless = true
            part.Transparency = 1
            part.Size = controllerRoot and controllerRoot.Size or Vector3.new(2, 2, 1)
            if staticRootCFrame then
                part.CFrame = staticRootCFrame
            elseif controllerRoot then
                part.CFrame = controllerRoot.CFrame
            end
            part.Parent = workspace
            staticRootPart = part
        end
        backend.StaticRoot = staticRootPart
        return staticRootPart
    end

    local function updatePoseMirror(rig)
        local controllerRoot = rig and rig:FindFirstChild("HumanoidRootPart")
        if controllerRoot
            and controllerRoot:IsA("BasePart")
            and controllerRoot.Parent
            and not placeholderActive
            and not rebindInProgress
        then
            staticRootCFrame = controllerRoot.CFrame
            local tracker = ensureStaticRoot(controllerRoot)
            tracker.CFrame = controllerRoot.CFrame
            tracker.Size = controllerRoot.Size
            environment().UhhhhhhTBZGelatekStaticRootCFrame = staticRootCFrame
        end

        if not placeholderActive then
            if placeholderModel then
                for _, proxy in pairs(placeholderParts) do
                    if proxy and proxy.Parent then
                        proxy.Transparency = 1
                    end
                end
            end
            return
        end

        if not placeholderModel or not placeholderModel.Parent then
            ensureRespawnPlaceholder(rig)
        end
        local transparency = 1
        if Reanimate.ShowResetPlaceholder == true then
            transparency = math.min(tonumber(Reanimate.PlaceholderTransparency) or 0.5, 0.5)
        end
        for sourcePart, proxy in pairs(placeholderParts) do
            if proxy and proxy.Parent and sourcePart and sourcePart.Parent then
                -- While reset/rebind is active the placeholder is a snapshot,
                -- not a live mirror. A dying controller can fall through the
                -- map after Roblox disables/destroys it; following that fall is
                -- what previously buried the red placeholder underground.
                local sourceMesh = sourcePart:FindFirstChildWhichIsA("DataModelMesh")
                local proxyMesh = proxy:FindFirstChildWhichIsA("DataModelMesh")
                if sourceMesh and proxyMesh then
                    pcall(function()
                        proxyMesh.Scale = sourceMesh.Scale
                        proxyMesh.Offset = sourceMesh.Offset
                    end)
                end
                proxy.Color = Color3.fromRGB(255, 45, 45)
                proxy.Material = Enum.Material.SmoothPlastic
                proxy.Transparency = transparency
            elseif proxy and proxy.Parent then
                -- If Roblox destroyed the controller during a default reset, keep
                -- the final mirrored pose frozen until its replacement is ready.
                proxy.Transparency = transparency
            end
        end
    end

    local function detachPoseMirror(destroyInfrastructure)
        if poseMirrorConnection then
            pcall(function()
                poseMirrorConnection:Disconnect()
            end)
            poseMirrorConnection = nil
        end
        poseMirrorRig = nil
        if destroyInfrastructure then
            placeholderActive = false
            destroyRespawnPlaceholder()
            if staticRootPart then
                pcall(function()
                    staticRootPart:Destroy()
                end)
                staticRootPart = nil
            end
            backend.StaticRoot = nil
            staticRootCFrame = nil
        end
    end

    local function attachPoseMirror(rig)
        if poseMirrorRig == rig and poseMirrorConnection then
            updatePoseMirror(rig)
            return
        end
        detachPoseMirror(false)
        poseMirrorRig = rig
        if placeholderModel then
            destroyRespawnPlaceholder()
        end
        hideControllerBody(rig)
        updatePoseMirror(rig)
        poseMirrorConnection = RunService.PreRender:Connect(function()
            if rig and rig.Parent then
                hideControllerBody(rig)
            end
            -- Keep applying placeholder visibility even after Roblox destroys a
            -- default-reset controller; its proxy pose intentionally stays frozen.
            updatePoseMirror(rig)
        end)
    end

    local function setRespawnPlaceholderActive(active, rig)
        placeholderActive = active == true
        if placeholderActive and rig and rig.Parent then
            ensureRespawnPlaceholder(rig)
            updatePoseMirror(rig)
        elseif not placeholderActive then
            destroyRespawnPlaceholder()
        end
    end

    local function detachCameraBridge()
        if cameraBridgeBound then
            pcall(RunService.UnbindFromRenderStep, RunService, CAMERA_BRIDGE_NAME)
            cameraBridgeBound = false
        end
        if cameraBridgeConnection then
            pcall(function()
                cameraBridgeConnection:Disconnect()
            end)
            cameraBridgeConnection = nil
        end
        if type(Reanimate.CharacterLTMs) == "table" then
            -- CharacterLTMs is shared by every backend. Remove only the exact
            -- entries this Gelatek camera bridge appended.
            for _, owned in ipairs(cameraBridgeLTMs) do
                for index = #Reanimate.CharacterLTMs, 1, -1 do
                    if Reanimate.CharacterLTMs[index] == owned then
                        table.remove(Reanimate.CharacterLTMs, index)
                        break
                    end
                end
            end
        end
        table.clear(cameraBridgeLTMs)
        for part, before in pairs(gelatekVisibilityParts) do
            if part and part.Parent then
                pcall(function()
                    part.LocalTransparencyModifier = before
                end)
            end
        end
        table.clear(gelatekVisibilityParts)
    end

    local visibilityR15ToR6 = {
        UpperTorso = "Torso", LowerTorso = "Torso",
        LeftUpperArm = "Left Arm", LeftLowerArm = "Left Arm", LeftHand = "Left Arm",
        RightUpperArm = "Right Arm", RightLowerArm = "Right Arm", RightHand = "Right Arm",
        LeftUpperLeg = "Left Leg", LeftLowerLeg = "Left Leg", LeftFoot = "Left Leg",
        RightUpperLeg = "Right Leg", RightLowerLeg = "Right Leg", RightFoot = "Right Leg",
    }

    local function getControllerVisibilityPart(rig, physicalPart)
        local accessory = physicalPart:FindFirstAncestorWhichIsA("Accessory")
        if accessory then
            local targets = environment().UhhhhhhTBZGelatekAccessoryTargets
            local proxyAccessory = type(targets) == "table" and targets[accessory]
            return proxyAccessory
                and proxyAccessory:FindFirstChild(physicalPart.Name, true)
                or nil
        end
        return rig and (rig:FindFirstChild(physicalPart.Name) or rig:FindFirstChild(visibilityR15ToR6[physicalPart.Name] or physicalPart.Name))
    end

    local function updateGelatekPhysicalVisibility(rig)
        local physical = backend.RealCharacter or originalCharacter
        if not physical or not physical.Parent then
            return
        end
        local camera = workspace.CurrentCamera
        local firstPerson = false
        if camera
            and type(Reanimate.Camera) == "table"
            and type(Reanimate.Camera.IsFirstPerson) == "function"
        then
            local read, result = pcall(Reanimate.Camera.IsFirstPerson, Reanimate.Camera)
            firstPerson = read and result == true
        end
        if not firstPerson and camera then
            firstPerson = (camera.CFrame.Position - camera.Focus.Position).Magnitude < 0.75
        end
        local cameraFade = tonumber(Reanimate.LocalTransparencyModifier) or 0
        for _, part in ipairs(getPhysicalHeadIndex(physical).Descendants) do
            if part:IsA("BasePart") and not part:FindFirstAncestorWhichIsA("Tool") then
                if gelatekVisibilityParts[part] == nil then
                    gelatekVisibilityParts[part] = part.LocalTransparencyModifier
                end
                local controllerPart = getControllerVisibilityPart(rig, part)
                local modifier = cameraFade
                if controllerPart and controllerPart:IsA("BasePart") then
                    local read, controllerModifier = pcall(function()
                        return controllerPart.LocalTransparencyModifier
                    end)
                    if read and type(controllerModifier) == "number" then
                        modifier = controllerModifier
                    end
                end
                if firstPerson then
                    if Reanimate.FirstPersonBody then
                        modifier = 0
                        if part.Name == "Head" then
                            modifier = 1
                        else
                            local weld = part:FindFirstChild("AccessoryWeld")
                            if weld and weld:IsA("JointInstance") and weld.Part1
                                and weld.Part1.Name == "Head"
                            then
                                modifier = 1
                            end
                        end
                    else
                        -- Body off means OFF. Do not wait for the camera fade to
                        -- crawl to one while the physical body fills the screen.
                        modifier = 1
                    end
                end
                pcall(function()
                    if part.LocalTransparencyModifier ~= modifier then part.LocalTransparencyModifier = modifier end
                end)
                if controllerPart and controllerPart:IsA("BasePart") then
                    pcall(function()
                        if controllerPart.LocalTransparencyModifier ~= modifier then controllerPart.LocalTransparencyModifier = modifier end
                    end)
                end
            end
        end
    end

    local function attachCameraBridge(rig)
        detachCameraBridge()
        local bridgeToken = activeGenerationToken
        Reanimate.GelatekDisableDirectionalWalking =
            options.DisableDirectionalWalking == true
        local humanoid = rig and rig:FindFirstChildOfClass("Humanoid")
        if not humanoid then
            return
        end
        pcall(function()
            humanoid.AutoRotate = true
        end)
        if type(Reanimate.CharacterLTMs) == "table" then
            for _, instance in ipairs(rig:GetDescendants()) do
                local ok = pcall(function()
                    local _ = instance.LocalTransparencyModifier
                end)
                if ok then
                    table.insert(Reanimate.CharacterLTMs, instance)
                    table.insert(cameraBridgeLTMs, instance)
                end
            end
        end
        local camera = workspace.CurrentCamera
        if camera then
            pcall(function()
                camera.CameraSubject = humanoid
            end)
        end
        local function renderBridge()
            if not generationIsActive(bridgeToken, rig) then
                return
            end
            -- Player.Character is the invisible controller after handoff, so
            -- Roblox's camera fade never reaches the visible physical shell.
            updateGelatekPhysicalVisibility(rig)
            local currentCamera = workspace.CurrentCamera
            if currentCamera and currentCamera.CameraSubject ~= humanoid then
                pcall(function()
                    currentCamera.CameraSubject = humanoid
                end)
            end
            local shouldLock = false
            if type(Reanimate.ShouldRotationType) == "function" then
                local ok, result = pcall(Reanimate.ShouldRotationType, Reanimate)
                shouldLock = ok and result == true
            end
            if not shouldLock
                and Reanimate.ShiftlockEnabled ~= false
                and type(Reanimate.Camera) == "table"
                and type(Reanimate.Camera.IsMouseLocked) == "function"
                and not Reanimate.Camera.Scriptable
            then
                local ok, result =
                    pcall(Reanimate.Camera.IsMouseLocked, Reanimate.Camera)
                shouldLock = ok and result == true
            end
            if shouldLock and type(Reanimate.CameraLockCharacter) == "function" then
                pcall(Reanimate.CameraLockCharacter)
            end
        end
        local bound = pcall(
            RunService.BindToRenderStep,
            RunService,
            CAMERA_BRIDGE_NAME,
            Enum.RenderPriority.Character.Value + 1,
            renderBridge
        )
        if bound then
            cameraBridgeBound = true
        else
            -- Some executors expose PreRender but reject named render binds.
            -- Visibility and camera ownership still get one safe writer.
            cameraBridgeConnection = RunService.PreRender:Connect(renderBridge)
        end
    end

    local function normalizedDestroyHeight(value)
        if type(value) ~= "number" or value ~= value then
            return -500
        end
        return value
    end

    local function disableVoidDestruction()
        if not destroyHeightCaptured then
            originalDestroyHeight = workspace.FallenPartsDestroyHeight
            destroyHeightCaptured = true
        end
        local global = environment()
        global.UhhhhhhTBZGelatekDestroyHeight = normalizedDestroyHeight(originalDestroyHeight)
        global.UhhhhhhTBZGelatekHiddenPartsY = global.UhhhhhhTBZGelatekDestroyHeight + 5
        pcall(function()
            workspace.FallenPartsDestroyHeight = 0 / 0
        end)
    end

    local function restoreVoidDestruction()
        if destroyHeightCaptured then
            pcall(function()
                workspace.FallenPartsDestroyHeight = originalDestroyHeight
            end)
        end
        destroyHeightCaptured = false
        originalDestroyHeight = nil
        local global = environment()
        global.UhhhhhhTBZGelatekDestroyHeight = nil
        global.UhhhhhhTBZGelatekHiddenPartsY = nil
    end

    local function characterScale()
        return math.clamp(tonumber(Reanimate.CharacterScale) or 1, 0.5, 5)
    end

    local SCALE_ATTRIBUTE = "UhhhhhhCharacterSpacingScale"

    local function applyCharacterScale(rig, force)
        if not rig or not rig.Parent then
            return false
        end
        local scale = characterScale()
        environment().UhhhhhhTBZGelatekCharacterSpacingScale = scale
        local previousScale = lastAppliedScale
        if type(previousScale) ~= "number" then
            local ok, value = pcall(rig.GetScale, rig)
            previousScale = ok and type(value) == "number" and value or 1
        end
        if not force and scale == previousScale then
            return true
        end
        local scaled = pcall(function()
            -- Model:ScaleTo owns body sizes, meshes, attachments, and joint spacing.
            -- Never rewrite Motor6D frames here: VR and jointless modules own them.
            rig:ScaleTo(scale)
            rig:SetAttribute(SCALE_ATTRIBUTE, scale)
        end)
        if not scaled then
            return false
        end
        lastAppliedScale = scale
        return true
    end

    local function jumpVelocity(humanoid)
        local useJumpPower = true
        pcall(function()
            useJumpPower = humanoid.UseJumpPower
        end)
        if useJumpPower then
            return math.max(tonumber(humanoid.JumpPower) or 0, 0)
        end
        return math.sqrt(2 * workspace.Gravity * math.max(tonumber(humanoid.JumpHeight) or 0, 0))
    end

    local function updateInfiniteJump(rig)
        local jump = type(Reanimate.Control) == "table" and Reanimate.Control.Jump == true
        if jump and not lastJump and Reanimate.InfiniteJump then
            local humanoid = rig:FindFirstChildOfClass("Humanoid")
            local root = rig:FindFirstChild("HumanoidRootPart")
            if humanoid
                and root
                and humanoid:GetState() == Enum.HumanoidStateType.Freefall
            then
                local velocity = root.AssemblyLinearVelocity
                root.AssemblyLinearVelocity = Vector3.new(velocity.X, jumpVelocity(humanoid), velocity.Z)
                pcall(function()
                    humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                end)
            end
        end
        lastJump = jump
    end

    local function restoreAccessoryBodyHideWelds()
        for weld, originalEnabled in pairs(accessoryBodyHideWeldStates) do
            if typeof(weld) == "Instance" and weld.Parent then
                pcall(function()
                    weld.Enabled = originalEnabled
                end)
            end
        end
        table.clear(accessoryBodyHideWeldStates)
    end

    local function snapAccessoryHandleToWeld(handle, weld)
        if not handle
            or not handle:IsA("BasePart")
            or not weld
            or not weld:IsA("JointInstance")
        then
            return false
        end

        local part0, part1 = weld.Part0, weld.Part1
        local c0, c1
        local okFrames = pcall(function()
            c0 = weld.C0
            c1 = weld.C1
        end)
        if not okFrames or typeof(c0) ~= "CFrame" or typeof(c1) ~= "CFrame" then
            return false
        end

        local anchor, desired
        if part0 == handle and part1 and part1:IsA("BasePart") then
            anchor = part1
            -- Weld equation: Part1*C1 = Part0*C0
            desired = part1.CFrame * c1 * (c0 * (weld:IsA("Motor6D") and weld.Transform or CFrame.identity)):Inverse()
        elseif part1 == handle and part0 and part0:IsA("BasePart") then
            anchor = part0
            desired = part0.CFrame * c0 * (weld:IsA("Motor6D") and weld.Transform or CFrame.identity) * c1:Inverse()
        end

        if not desired then
            return false
        end

        -- AssemblyRootPart can still be shared just after disabling a weld.
        -- Let the repaired binding settle instead of moving that whole assembly.
        if anchor and handle.AssemblyRootPart ~= nil
            and handle.AssemblyRootPart == anchor.AssemblyRootPart then
            return true, "intact assembly"
        end
        if not ownsPhysicalPart(handle) then
            return false, "accessory assembly is not network-owned"
        end
        return pcall(function()
            handle.CFrame = desired
            if anchor then
                handle.AssemblyLinearVelocity = anchor.AssemblyLinearVelocity
                handle.AssemblyAngularVelocity = anchor.AssemblyAngularVelocity
            end
        end)
    end

    local function captureAccessoryWeldBindings(character)
        table.clear(accessoryWeldBindings)
        for _, accessory in ipairs(character:GetChildren()) do
            if accessory:IsA("Accessory") then
                local handle = accessory:FindFirstChild("Handle")
                local weld = handle and handle:FindFirstChild("AccessoryWeld")
                if handle and handle:IsA("BasePart")
                    and weld and weld:IsA("JointInstance")
                then
                    accessoryWeldBindings[handle] = {
                        Part0 = weld.Part0,
                        Part1 = weld.Part1,
                        C0 = weld.C0,
                        C1 = weld.C1,
                        Enabled = weld.Enabled ~= false,
                        ClassName = weld.ClassName, Name = weld.Name,
                        Transform = weld:IsA("Motor6D") and weld.Transform or CFrame.identity,
                        AnchorName = weld.Part0 == handle and weld.Part1 and weld.Part1.Name
                            or weld.Part1 == handle and weld.Part0 and weld.Part0.Name,
                        HandleIsPart0 = weld.Part0 == handle,
                        RootPriority = handle.RootPriority, Massless = handle.Massless,
                    }
                end
            end
        end
        backend.AccessoryLifetime.Remember(character)
    end

    function backend.AccessoryLifetime.Remember(physical)
        local index = getPhysicalHeadIndex(physical)
        index.AccessoryRecords = index.AccessoryRecords or {}
        index.TrackedAccessories = index.TrackedAccessories or {}
        for _, source in ipairs(index.Children or {}) do
            if source:IsA("Accessory") and not index.AccessoryRecords[source] then
                local handle = source:FindFirstChild("Handle")
                if handle and handle:IsA("BasePart") then
                    local record = {Source=source,Handle=handle,Name=source.Name,
                        Id=#index.TrackedAccessories+1,Repairs=0,ProxyRebuilds=0,
                        Binding=accessoryWeldBindings[handle]}
                    local cloned, template = pcall(function() return source:Clone() end)
                    if cloned then record.Template = template end
                    index.AccessoryRecords[source] = record
                    table.insert(index.TrackedAccessories, source)
                    index.Recovery = nil
                    for _, item in ipairs({{source,"SourceDestroyed"},{handle,"HandleDestroyed"}}) do
                        if item[1].Destroying then
                            table.insert(index.Connections,item[1].Destroying:Connect(function()
                                record[item[2]] = true
                                record.LastEvent = item[2]
                                record.Blocked = "original " .. (item[2]=="HandleDestroyed" and "Handle" or "Accessory") .. " destroyed; server replacement required"
                                index.Recovery = nil
                            end))
                        end
                    end
                end
            end
        end
        return index
    end

    function backend.AccessoryLifetime.BodyAnchorOffset(name)
        -- The same segment centers used by native Gelatek's R15 followers.
        local y = name == "UpperTorso" and 0.194 or name == "LowerTorso" and -0.79
            or name:find("UpperArm", 1, true) and 0.4085 or name:find("LowerArm", 1, true) and -0.184
            or name:find("Hand", 1, true) and -0.83 or name:find("UpperLeg", 1, true) and 0.575
            or name:find("LowerLeg", 1, true) and -0.199 or name:find("Foot", 1, true) and -0.849 or 0
        return visibilityR15ToR6[name] and CFrame.new(0, y, 0) or CFrame.identity
    end

    function backend.AccessoryLifetime.RemapBodyEndpoint(joint, key, rig)
        local part = joint[key]
        local frame = key == "Part0" and "C0" or "C1"
        local exact=rig:FindFirstChild(part.Name)
        if exact then joint[key]=exact return end
        joint[frame] = backend.AccessoryLifetime.BodyAnchorOffset(part.Name) * joint[frame]
        joint[key] = rig:FindFirstChild(visibilityR15ToR6[part.Name] or part.Name)
    end

	function backend.AccessoryLifetime.RepairControllerBodyJoints(rig)
        -- Repair the cloned controller only. Upgraded R15 already has a full
        -- AnimationConstraint skeleton; a second Motor6D fights that skeleton.
        local links={{"HumanoidRootPart","LowerTorso","Root"},{"LowerTorso","UpperTorso","Waist"},{"UpperTorso","Head","Neck"}}
        for _,side in ipairs({"Left","Right"}) do
            for _,entry in ipairs({{"UpperTorso",side.."UpperArm",side.."Shoulder"},{side.."UpperArm",side.."LowerArm",side.."Elbow"},
                {side.."LowerArm",side.."Hand",side.."Wrist"},{"LowerTorso",side.."UpperLeg",side.."Hip"},
                {side.."UpperLeg",side.."LowerLeg",side.."Knee"},{side.."LowerLeg",side.."Foot",side.."Ankle"}}) do table.insert(links,entry) end
        end
        local existing,upgraded={},false
        for _,joint in ipairs(rig:GetDescendants()) do
            if Util.IsCharacterJoint(joint) then
                local p0,p1=Util.GetCharacterJointParts(joint)
                if p0 and p1 and p0.Parent==rig and p1.Parent==rig then
                    existing[p0]=existing[p0] or {}
                    existing[p0][p1]=joint
                    joint.Enabled=true
                    if joint.ClassName=="AnimationConstraint" then joint.IsKinematic=true upgraded=true end
                end
            end
        end
        for _,entry in ipairs(links) do
            local p0,p1=rig:FindFirstChild(entry[1]),rig:FindFirstChild(entry[2])
            if p0 and p1 and not (existing[p0] and existing[p0][p1]) then
                local a0=p0:FindFirstChild(entry[3].."RigAttachment")
                local a1=p1:FindFirstChild(entry[3].."RigAttachment")
                if a0 and a1 and a0:IsA("Attachment") and a1:IsA("Attachment") then
                    local joint=Instance.new(upgraded and "AnimationConstraint" or "Motor6D")
                    joint.Name=entry[3]
                    if upgraded then
                        joint.Attachment0,joint.Attachment1=a0,a1
                        joint.IsKinematic=true
                    else
                        joint.Part0,joint.Part1=p0,p1
                        joint.C0,joint.C1=a0.CFrame,a1.CFrame
                    end
                    joint.Parent=p1
                    existing[p0]=existing[p0] or {}
                    existing[p0][p1]=joint
                end
            end
        end
    end

    function backend.AccessoryLifetime.CloneController(character, template, nativeR6)
        -- Clone the whole graph once: Clone remaps even accessory motors parented
        -- under a body part, and duplicate accessory names are not identities.
        local changed, sources, clone, targets, jointSources, jointTargets = {}, {}, nil, {}, {}, {}
        local marker = "_UhhhhhhControllerCloneId"
        local jointMarker = "_UhhhhhhControllerJointCloneId"
        local ok, reason = pcall(function()
            local items = character:GetDescendants()
            table.insert(items, character)
            for _, item in ipairs(items) do
                changed[item] = {Archivable = item.Archivable}
                item.Archivable = true
                if item:IsA("Motor6D") then
                    local id=#jointSources+1 jointSources[id]=item
                    changed[item].JointMarker=item:GetAttribute(jointMarker) changed[item].JointMarked=true
                    item:SetAttribute(jointMarker,id)
                end
                if item:IsA("Accessory") and item.Parent == character then
                    local id = #sources + 1
                    sources[id] = item
                    changed[item].Marker = item:GetAttribute(marker)
                    changed[item].Marked = true
                    item:SetAttribute(marker, id)
                end
            end
            clone = character:Clone()
            assert(clone, "avatar controller clone unavailable")
            for _,item in ipairs(clone:GetDescendants()) do
                if item:IsA("Motor6D") then
                    local id=item:GetAttribute(jointMarker) item:SetAttribute(jointMarker,nil)
                    if jointSources[id] then jointTargets[jointSources[id]]=item end
                end
            end
            for _, accessory in ipairs(clone:GetChildren()) do
                if accessory:IsA("Accessory") then
                    local id = accessory:GetAttribute(marker)
                    accessory:SetAttribute(marker, nil)
                    if sources[id] then targets[sources[id]] = accessory end
                end
            end
        end)
        for item, saved in pairs(changed) do
            pcall(function()
                item.Archivable = saved.Archivable
                if saved.JointMarked then item:SetAttribute(jointMarker,saved.JointMarker) end
                if saved.Marked then item:SetAttribute(marker, saved.Marker) end
            end)
        end
        if not ok then
            if clone then clone:Destroy() end
            error(reason)
        end
        local rig = nativeR6 and clone or template:Clone()
        if not nativeR6 then
            -- Existing movesets need R6. Keep their body, but retain the real
            -- accessory graph and remap its R15 body anchors onto that body.
            for _, accessory in pairs(targets) do accessory.Parent = rig end
            for _, item in ipairs(clone:GetDescendants()) do
                if item:IsA("JointInstance") then
                    local p0, p1 = item.Part0, item.Part1
                    local a0 = p0 and p0:FindFirstAncestorOfClass("Accessory")
                    local a1 = p1 and p1:FindFirstAncestorOfClass("Accessory")
                    if a0 or a1 then
                        for _, key in ipairs({"Part0", "Part1"}) do
                            local part = item[key]
                            if part and part.Parent == clone then
                                backend.AccessoryLifetime.RemapBodyEndpoint(item, key, rig)
                            end
                        end
                        item.Parent = (a0 or a1):FindFirstChild("Handle")
                    end
                end
            end
            -- Accessory-owned joints moved with their accessories, too.
            for _, accessory in pairs(targets) do
                for _, item in ipairs(accessory:GetDescendants()) do
                    if item:IsA("JointInstance") then
                        for _, key in ipairs({"Part0", "Part1"}) do
                            local part = item[key]
                            if part and part.Parent == clone then
                                backend.AccessoryLifetime.RemapBodyEndpoint(item, key, rig)
                            end
                        end
                    end
                end
            end
            clone:Destroy()
        end
        for _, item in ipairs(rig:GetDescendants()) do
            if item:IsA("Script") or item:IsA("LocalScript") or item:IsA("Tool")
                or item.Name == "OwnershipCheck" or item.Name == "FakeHats"
                or item:IsA("BodyMover") or item:IsA("AlignPosition") or item:IsA("AlignOrientation")
                or item:IsA("LinearVelocity") or item:IsA("AngularVelocity") then
                item:Destroy()
            elseif item:IsA("BasePart") then
                item.Transparency, item.LocalTransparencyModifier = 1, 0
                item.Anchored, item.CanCollide, item.CanTouch, item.CanQuery = false, false, false, false
                item.AssemblyLinearVelocity, item.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
            elseif item:IsA("Decal") then item.Transparency = 1 end
        end
        for _, joint in ipairs(rig:GetDescendants()) do
            if joint:IsA("JointInstance") and joint.Parent and joint.Parent:IsA("BasePart") and joint.Parent.Parent == rig then
                local p0, p1 = joint.Part0, joint.Part1
                if (p0 and p0:FindFirstAncestorOfClass("Accessory")) or (p1 and p1:FindFirstAncestorOfClass("Accessory")) then
                    joint:SetAttribute("_UhhhhhhGelatekProxyJoint", true)
                end
            end
        end
        if nativeR6 then
            -- A PD avatar may already have a dead Humanoid or missing body joints.
            -- Use a live controller Humanoid, without discarding avatar content.
            local old = rig:FindFirstChildOfClass("Humanoid")
            local r15=old and old.RigType==Enum.HumanoidRigType.R15
            local humanoid = (r15 and old or template:FindFirstChildOfClass("Humanoid")):Clone()
            humanoid.Health=math.max(1,humanoid.MaxHealth or 100)
            humanoid.BreakJointsOnDeath=false
            local description = old and old:FindFirstChildOfClass("HumanoidDescription")
            if description then
                local duplicate=humanoid:FindFirstChildOfClass("HumanoidDescription")
                if duplicate then duplicate:Destroy() end
                description.Parent = humanoid
            end
            if old then old:Destroy() end
            humanoid.Parent = rig
            if r15 then
                backend.AccessoryLifetime.RepairControllerBodyJoints(rig)
            end
            for _, joint in ipairs(r15 and {} or template:GetDescendants()) do
                if joint:IsA("Motor6D") and joint.Part0 and joint.Part1 then
                    local p0, p1 = rig:FindFirstChild(joint.Part0.Name), rig:FindFirstChild(joint.Part1.Name)
                    local found = false
                    for _, existing in ipairs(rig:GetDescendants()) do
                        if existing:IsA("Motor6D") and existing.Part0 == p0 and existing.Part1 == p1 then found = true break end
                    end
                    if p0 and p1 and not found then
                        local added = joint:Clone()
                        added.Part0, added.Part1, added.Parent = p0, p1, p0
                    end
                end
            end
        end
        return rig, targets, jointTargets
    end

    function backend.AccessoryLifetime.CloneAccessoryTargets(character, rig)
        local copy, targets = backend.AccessoryLifetime.CloneController(character, rig, true)
        for _, joint in ipairs(rig:GetDescendants()) do
            if joint:GetAttribute("_UhhhhhhGelatekProxyJoint") == true then joint:Destroy() end
        end
        for _, joint in ipairs(copy:GetDescendants()) do
            if joint:IsA("JointInstance") then
                local p0, p1 = joint.Part0, joint.Part1
                local accessory = p0 and p0:FindFirstAncestorOfClass("Accessory")
                    or p1 and p1:FindFirstAncestorOfClass("Accessory")
                if accessory then
                    local parent = joint.Parent
                    for _, key in ipairs({"Part0", "Part1"}) do
                        local part = joint[key]
                        if part and part.Parent == copy then
                            backend.AccessoryLifetime.RemapBodyEndpoint(joint, key, rig)
                        end
                    end
                    if parent and parent.Parent == copy then
                        joint.Parent = rig:FindFirstChild(visibilityR15ToR6[parent.Name] or parent.Name) or accessory:FindFirstChild("Handle")
                        joint:SetAttribute("_UhhhhhhGelatekProxyJoint", true)
                    end
                end
            end
        end
        for _, accessory in pairs(targets) do accessory.Parent = rig end
        copy:Destroy()
        return targets
    end

    function backend.AccessoryLifetime.ControllerIndex(rig)
        if not rig then return nil end
        local index = physicalIndex.ControllerJoints
        if not index or index.Rig ~= rig then
            if index then for _, connection in ipairs(index.Connections) do connection:Disconnect() end end
            index = {Rig = rig, Dirty = true, Connections = {}}
            physicalIndex.ControllerJoints = index
            for _, name in ipairs({"DescendantAdded", "DescendantRemoving"}) do
                if rig[name] then table.insert(index.Connections, rig[name]:Connect(function(item)
                    if item:IsA("JointInstance") or item.ClassName=="AnimationConstraint"
                        or item:IsA("BasePart") and item.Parent==rig then index.Dirty = true end
                end)) end
            end
        end
        if index.Dirty then
            index.Revision = (index.Revision or 0) + 1
            index.Joints, index.BodyJoints, index.Motors, index.HandleJoints = {}, {}, {}, {}
            for _, joint in ipairs(rig:GetDescendants()) do
                if joint:IsA("JointInstance") or joint.ClassName=="AnimationConstraint" then
                    table.insert(index.Joints, joint)
                    if joint:IsA("Motor6D") then table.insert(index.Motors,joint) end
                    local p0,p1 = Util.GetCharacterJointParts(joint)
                    if p0 and p1 then
                        if p0.Parent==rig and p1.Parent==rig then table.insert(index.BodyJoints,joint) end
                        for _,part in ipairs({p0,p1}) do
                            index.HandleJoints[part] = index.HandleJoints[part] or {}
                            table.insert(index.HandleJoints[part],joint)
                        end
                    end
                end
            end
            index.Dirty = false
        end
        return index
    end

    function backend.AccessoryLifetime.ControllerBodyPoses(rig, live)
        local poses = {}
        local root = rig and rig:FindFirstChild("HumanoidRootPart")
        local index = backend.AccessoryLifetime.ControllerIndex(rig)
        if not root or not index then return poses end
	local committed = backend.ControllerPoseSample
        if not live and committed and committed.Rig == rig and committed.Root == root
            and os.clock() >= committed.At and os.clock() - committed.At < .25
            and committed.Revision == index.Revision then
            if committed.RootFrame == root.CFrame and committed.Poses then return committed.Poses end
            -- Every physics/render reader consumes the same completed animation
            -- pose. Rebase it onto the moving root, never pin it in world space.
            for part, offset in pairs(committed.Offsets) do
                if part.Parent == rig then poses[part] = root.CFrame * offset end
            end
            committed.RootFrame,committed.Poses = root.CFrame,poses
            return poses
        end
        local phase=environment().UhhhhhhTBZGelatekPosePhaseId
        local batch=backend.FallbackBodyPoseBatch
        if not live and phase and batch and batch.Phase==phase and batch.Rig==rig
            and batch.RootFrame==root.CFrame and batch.Revision==index.Revision then return batch.Poses end
        poses[root] = root.CFrame
        -- Transform is applied by Roblox in a later batch. Read the live joint
        -- graph now, rather than combining a fresh hat motor with an old Head.
        for _ = 1, 16 do
            local changed = false
            for _, joint in ipairs(index.BodyJoints) do
                local p0, p1 = Util.GetCharacterJointParts(joint)
                if joint.Parent and joint.Enabled ~= false and p0 and p1 and p0 ~= p1
                    and p0.Parent == rig and p1.Parent == rig then
                    local c0,c1=Util.GetCharacterJointFrames(joint)
                    local transform = Util.IsCharacterJoint(joint) and joint.Transform or CFrame.identity
                    if poses[p0] and not poses[p1] then
                        poses[p1] = poses[p0] * c0 * transform * c1:Inverse()
                        changed = true
                    elseif poses[p1] and not poses[p0] then
                        poses[p0] = poses[p1] * c1 * (c0 * transform):Inverse()
                        changed = true
                    end
                end
            end
            if not changed then break end
        end
	if not live and phase then backend.FallbackBodyPoseBatch={Phase=phase,Rig=rig,
            RootFrame=root.CFrame,Revision=index.Revision,Poses=poses} end
        return poses
    end

	function backend.AccessoryLifetime.CommitControllerPose(rig)
        local root = rig and rig:FindFirstChild("HumanoidRootPart")
        if not root then backend.ControllerPoseSample = nil return end
        local poses = backend.AccessoryLifetime.ControllerBodyPoses(rig, true)
        local offsets = {}
        for part, pose in pairs(poses) do offsets[part] = root.CFrame:ToObjectSpace(pose) end
        local index = backend.AccessoryLifetime.ControllerIndex(rig)
        backend.FallbackBodyPoseBatch=nil
        backend.ControllerPoseSample = {Rig=rig, Root=root, Offsets=offsets,
            Revision=index and index.Revision, At=os.clock(), RootFrame=root.CFrame, Poses=poses,
            Serial=(backend.ControllerPoseSample and backend.ControllerPoseSample.Serial or 0)+1}
    end

    function backend.AccessoryLifetime.ControllerBodyPose(part, poses)
        if not part then return nil end
        poses = poses or backend.AccessoryLifetime.ControllerBodyPoses(part.Parent)
        return poses[part] or part.CFrame
    end

    function backend.AccessoryLifetime.ControllerJoint(handle)
        local index = backend.AccessoryLifetime.ControllerIndex(handle and handle:FindFirstAncestorOfClass("Model"))
        if not index then return nil end
        local best, bestAnchor, bestScore
        for _, joint in ipairs(index.HandleJoints[handle] or {}) do
            if joint.Parent and joint.Enabled ~= false then
                local other = joint.Part0 == handle and joint.Part1 or joint.Part1 == handle and joint.Part0
                if other and other ~= handle and other.Parent then
                    -- A chain link also touches its parent's Handle. Prefer the
                    -- body anchor, then the motor's driven (Part1) endpoint.
                    local score = (joint:IsA("Motor6D") and 1000 or 0)
                        + (other:FindFirstAncestorOfClass("Accessory") and 0 or 100)
                        + (joint.Part1 == handle and 10 or 0)
                    if not bestScore or score > bestScore then best, bestAnchor, bestScore = joint, other, score end
                end
            end
        end
        return best, bestAnchor
    end

    function backend.AccessoryLifetime.ControllerPose(handle, visiting, depth, bodyPoses)
        visiting, depth = visiting or {}, depth or 0
        if visiting[handle] or depth >= 16 then return nil end
        visiting[handle] = true
        local joint, anchor = backend.AccessoryLifetime.ControllerJoint(handle)
        if not joint then visiting[handle] = nil return handle.CFrame end
        bodyPoses = bodyPoses or backend.AccessoryLifetime.ControllerBodyPoses(handle:FindFirstAncestorOfClass("Model"))
        local anchorPose = backend.AccessoryLifetime.ControllerBodyPose(anchor, bodyPoses)
        if anchor:FindFirstAncestorOfClass("Accessory") then
            anchorPose = backend.AccessoryLifetime.ControllerPose(anchor, visiting, depth + 1, bodyPoses)
        end
        if not anchorPose then visiting[handle] = nil return nil end
        local transform = joint:IsA("Motor6D") and joint.Transform or CFrame.identity
        local pose = joint.Part1 == handle
            and (anchorPose * joint.C0 * transform * joint.C1:Inverse())
            or (anchorPose * joint.C1 * (joint.C0 * transform):Inverse())
        visiting[handle] = nil
        return pose
    end

    function backend.AccessoryLifetime.MakeProxy(record, rig)
        if not record.Template then return nil, "no saved controller accessory template" end
        local proxy = record.Template:Clone()
        if not proxy then return nil, "controller accessory clone unavailable" end
        proxy.Name = record.Source.Name
        local handle = proxy:FindFirstChild("Handle")
        if not handle then proxy:Destroy() return nil, "saved controller template has no Handle" end
        for _, item in ipairs(proxy:GetDescendants()) do
            if item.Name == "OwnershipCheck" or item:IsA("BodyMover")
                or item:IsA("AlignPosition") or item:IsA("AlignOrientation")
                or item:IsA("LinearVelocity") or item:IsA("AngularVelocity") then item:Destroy()
            elseif item:IsA("BasePart") then
                item.Transparency,item.LocalTransparencyModifier = 1,0
                item.Anchored,item.CanCollide,item.CanTouch,item.CanQuery,item.Massless = false,false,false,false,true
            end
        end
        local anchor, c0, c1, reversed
        local saved = record.TargetWeld or record.Binding
        if saved and saved.AnchorName then
            anchor = rig:FindFirstChild(saved.AnchorName) or rig:FindFirstChild(visibilityR15ToR6[saved.AnchorName] or saved.AnchorName)
            c0,c1,reversed = saved.C0,saved.C1,saved.HandleIsPart0 == false
            if visibilityR15ToR6[saved.AnchorName] and anchor.Name ~= saved.AnchorName then
                local offset = scaledRecoveryOffset(backend.AccessoryLifetime.BodyAnchorOffset(saved.AnchorName))
                if reversed then c0 = offset * c0 else c1 = offset * c1 end
            end
        end
        if not anchor then
            local attachment = handle:FindFirstChildOfClass("Attachment")
            if attachment then
                for _, bodyPart in ipairs(rig:GetChildren()) do
                    if bodyPart:IsA("BasePart") then
                        local targetAttachment = bodyPart:FindFirstChild(attachment.Name)
                        if targetAttachment and targetAttachment:IsA("Attachment") then
                            anchor,c0,c1 = bodyPart,attachment.CFrame,targetAttachment.CFrame
                            break
                        end
                    end
                end
            end
        end
        if not anchor or not pdHeadFollower.FiniteCFrame(c0) or not pdHeadFollower.FiniteCFrame(c1) then
            proxy:Destroy()
            return nil, "controller accessory anchor unavailable"
        end
        local weld = handle:FindFirstChild("AccessoryWeld")
        local class = saved and saved.ClassName == "Motor6D" and "Motor6D" or "Weld"
        if not weld or not weld:IsA(class) then
            if weld then weld:Destroy() end
            weld=Instance.new(class) weld.Name=saved and saved.Name or "AccessoryWeld"
        end
        weld.C0,weld.C1 = c0,c1
        if class == "Motor6D" then weld.Transform = saved.Transform or CFrame.identity end
        weld.Part0,weld.Part1 = reversed and anchor or handle,reversed and handle or anchor
        weld.Enabled = true
        weld.Parent = handle
        local transform = class == "Motor6D" and weld.Transform or CFrame.identity
        handle.CFrame = reversed and (anchor.CFrame*c0*transform*c1:Inverse()) or (anchor.CFrame*c1*(c0*transform):Inverse())
        if record.TargetSize then handle.Size=record.TargetSize end
        proxy:SetAttribute("_UhhhhhhGelatekProxyAccessory",true)
        proxy:SetAttribute("_UhhhhhhGelatekSourceName",record.Source.Name)
        proxy.Parent = rig
        return proxy
    end

    function backend.AccessoryLifetime.Refresh(rig, physical)
        if not backend.Running or rebindInProgress or rig ~= backend.Rig
            or not rig or not rig.Parent or physical ~= backend.RealCharacter then return end
        local index = backend.AccessoryLifetime.Remember(physical)
        local global = environment()
        local targets = global.UhhhhhhTBZGelatekAccessoryTargets
        if type(targets) ~= "table" then targets={} global.UhhhhhhTBZGelatekAccessoryTargets=targets index.Recovery=nil end
        for source, record in pairs(index.AccessoryRecords) do
            local handle = record.Handle
            if record.SourceDestroyed or record.HandleDestroyed then
                local state=accessoryRecoveryStates[handle]
                if state then state.LastBlockedReason=record.Blocked end
                continue
            end
            -- The physical source is an identity, not a GetChildren() result.
            -- Recover the SAME original objects if they were merely unparented;
            -- a Destroying event is terminal and never replaced with a local hat.
            if not source.Parent or handle.Parent ~= source then
                if record.RetryAt and os.clock()<record.RetryAt then continue end
                local ok, reason=pcall(function()
                    if not source.Parent then source.Parent=physical end
                    if handle.Parent~=source then handle.Parent=source end
                end)
                if not ok then
                    record.Blocked="original accessory reparent failed: " .. tostring(reason)
                    record.RetryAt=os.clock()+1
                    continue
                end
                record.Repairs+=1 record.RetryAt=nil record.LastEvent="original parent restored"
                index.Recovery=nil
            end
            local proxy=targets[source]
            local controller=proxy and proxy:FindFirstChild("Handle")
            if not proxy or not proxy.Parent or not controller or not controller.Parent then
                if record.RetryAt and os.clock()<record.RetryAt then continue end
                -- Restore a still-live target-map binding before allocating a
                -- new invisible controller target. Physical originals never clone.
                local retained=record.Controller
                if retained and retained.Parent and retained.Parent.Parent==rig then
                    proxy,controller=retained.Parent,retained
                else
                    local ok, made, reason=pcall(backend.AccessoryLifetime.MakeProxy,record,rig)
                    if not ok or not made then
                        record.Blocked="controller target rebuild failed: " .. tostring(ok and reason or made)
                        record.RetryAt=os.clock()+1
                        continue
                    end
                    proxy,controller=made,made:FindFirstChild("Handle")
                    record.ProxyRebuilds+=1 record.LastEvent="controller proxy rebuilt"
                end
                targets[source]=proxy record.RetryAt=nil index.Recovery=nil
            end
            if proxy.Parent ~= rig then proxy.Parent=rig index.Recovery=nil end
            if record.Controller ~= controller then
                record.Controller=controller
                for _, child in ipairs(proxy:GetDescendants()) do
                    if child.Name=="OwnershipCheck" then child:Destroy() end
                end
            end
            local weld=backend.AccessoryLifetime.ControllerJoint(controller)
            if weld and weld:IsA("JointInstance") then
                local anchor=weld.Part0==controller and weld.Part1 or weld.Part0
                if anchor and anchor.Parent==rig then
                    local saved=record.TargetWeld or {}
                    saved.C0,saved.C1,saved.AnchorName,saved.HandleIsPart0=weld.C0,weld.C1,anchor.Name,weld.Part0==controller
                    saved.ClassName,saved.Name = weld.ClassName,weld.Name
                    saved.Transform = weld:IsA("Motor6D") and weld.Transform or CFrame.identity
                    record.TargetWeld=saved
                end
            end
            record.TargetSize=controller.Size
            record.Blocked=nil
            backend.RefreshOwnershipWarning(handle)
        end
    end

    local function shouldDetachHeadAccessory(handle)
        -- One broad switch; no separate head/hair-only physical writer.
        return options.BreakAccessoryWelds == true
            and (backend.EffectivePermanentDeath ~= true or ownsPhysicalPart(handle))
    end

    function backend.AccessoryLifetime.HeadHideReady(physical, head, requested)
        backend.HeadHideAccessoryBlockedReason = nil
        backend.HeadHideAccessoryRestorePending = false
        if not requested then return false end
        local resolver = environment().UhhhhhhTBZShouldDetachAccessoryForBodyHide
        if type(resolver) ~= "function" then return true end
        local targets = environment().UhhhhhhTBZGelatekAccessoryTargets or {}
        local index = getPhysicalHeadIndex(physical)
        local waiting
        for handle, binding in pairs(accessoryWeldBindings) do
            local ok, keep = pcall(resolver, handle, nil)
            if handle.Parent and binding.AnchorName == "Head" and ok and keep == true then
                local proxy = targets[handle.Parent]
                local controller = proxy and proxy.Parent and proxy:FindFirstChild("Handle")
                local reason
                if not ownsPhysicalPart(head) or not ownsPhysicalPart(handle) then
                    reason = "kept head accessory is not network-owned"
                elseif not controller or not controller.Parent then
                    reason = "kept head accessory target missing"
                elseif backend.HeadHideAccessoryRetryAt and os.clock() < backend.HeadHideAccessoryRetryAt then
                    reason = "waiting to retry kept head accessories"
                end
                if reason then
                    backend.HeadHideAccessoryBlockedReason = reason
                    backend.HeadHideAccessoryRestorePending = true
                    return false
                end
                local root = handle.AssemblyRootPart
                for _, part in ipairs(index.BodyParts) do
                    if not root or part.AssemblyRootPart == root then
                        waiting = "waiting for kept head accessory assembly separation"
                        break
                    end
                end
            end
        end
        backend.HeadHideAccessoryBlockedReason = waiting
        return waiting == nil
    end

    function backend.AccessoryLifetime.RollbackHeadHide()
        for handle, binding in pairs(accessoryWeldBindings) do
            if handle.Parent and binding.AnchorName == "Head" then
                local state = accessoryRecoveryStates[handle]
                -- Explicit non-PD all-break remains the torso workaround. Never
                -- fabricate its destroyed original weld or attach it back here.
                if state and state.Weld and state.Weld.Parent then
                    backend.AccessoryLifetime.RestoreManaged(handle, state)
                else
                    local weld = handle:FindFirstChild("AccessoryWeld")
                    if weld and weld:IsA("JointInstance") then
                        weld.Enabled = false
                        weld.Part0, weld.Part1, weld.C0, weld.C1 = binding.Part0, binding.Part1, binding.C0, binding.C1
                        if binding.Enabled then snapAccessoryHandleToWeld(handle, weld) end
                        weld.Enabled = binding.Enabled
                    end
                end
            end
        end
        if not backend.HeadHideAccessoryRetryAt or os.clock() >= backend.HeadHideAccessoryRetryAt then
            backend.HeadHideAccessoryRetryAt = os.clock() + 0.25
        end
    end

    local function repairAccessoryWeldBindings()
        if not backend.Running or rebindInProgress
            or options.BreakAccessoryWelds == true
        then
            return
        end
        backend.AccessoryWeldRepairError = nil
        local physical = backend.RealCharacter or originalCharacter
        -- Capture late-added accessories' actual weld offsets as well.
        if physical and physical.Parent then
            for _, accessory in ipairs(getPhysicalHeadIndex(physical).Children) do
                if accessory:IsA("Accessory") then
                    local handle = accessory:FindFirstChild("Handle")
                    local weld = handle and handle:FindFirstChild("AccessoryWeld")
                    if handle and not accessoryWeldBindings[handle]
                        and weld and weld:IsA("JointInstance")
                    then
                        local anchor = weld.Part0 == handle and weld.Part1
                            or weld.Part1 == handle and weld.Part0
                        if anchor and anchor.Parent == physical then
                            accessoryWeldBindings[handle] = {
                                Part0 = weld.Part0, Part1 = weld.Part1,
                                C0 = weld.C0, C1 = weld.C1,
                                Enabled = weld.Enabled ~= false,
                                AnchorName = anchor.Name,
                                HandleIsPart0 = weld.Part0 == handle,
                                RootPriority = handle.RootPriority, Massless = handle.Massless,
                            }
                        end
                    end
                end
            end
        end
        for handle, binding in pairs(accessoryWeldBindings) do
            local ok, reason = pcall(function()
            if shouldDetachHeadAccessory(handle) then return end
            if accessoryRecoveryStates[handle]
                and accessoryRecoveryStates[handle].Managed then return end
            if physical and physical.Parent and binding.AnchorName then
                local anchor = binding.HandleIsPart0 and binding.Part1 or binding.Part0
                if not anchor or not anchor.Parent then
                    local replacement = physical:FindFirstChild(binding.AnchorName)
                    if replacement and replacement:IsA("BasePart") then
                        if binding.HandleIsPart0 then binding.Part1 = replacement
                        else binding.Part0 = replacement end
                    end
                end
            end
            if handle.Parent and binding.Part0 and binding.Part0.Parent
                and binding.Part1 and binding.Part1.Parent
            then
                local hideResolver = environment().UhhhhhhTBZShouldDetachAccessoryForBodyHide
                if type(hideResolver) == "function" then
                    local ok, hidden = pcall(hideResolver, handle, nil)
                    if ok and hidden == true then return end
                end
                handle.Massless = true
                handle.RootPriority = -127
                local weld = handle:FindFirstChild("AccessoryWeld")
                if weld and not weld:IsA("JointInstance") then
                    -- Do not let a same-name non-joint prevent restoration.
                    weld.Name = "AccessoryWeld_Unused"
                    weld = nil
                end
                if not weld then
                    -- A local replacement Weld is not proof that the server
                    -- still has that binding. A genuinely detached original
                    -- must stay on the core owned-handle transport instead.
                    return
                end
                -- The previous repair only handled a MISSING weld. A disabled
                -- or reparented existing weld silently let the Handle fall away.
                if weld.Part0 ~= binding.Part0 or weld.Part1 ~= binding.Part1
                    or weld.C0 ~= binding.C0 or weld.C1 ~= binding.C1
                    or weld.Enabled ~= binding.Enabled then
                    weld.Enabled = false
                    weld.Part0, weld.Part1 = binding.Part0, binding.Part1
                    weld.C0, weld.C1 = binding.C0, binding.C1
                    snapAccessoryHandleToWeld(handle, weld)
                    weld.Enabled = binding.Enabled
                end
            end
            end)
            if not ok then backend.AccessoryWeldRepairError = tostring(reason) end
        end
    end

    local function updateAccessoryBodyHideWelds()
        if not backend.Running or rebindInProgress then
            return
        end

        local physical = backend.RealCharacter or originalCharacter
        if not physical or not physical.Parent then
            restoreAccessoryBodyHideWelds()
            return
        end

        local global = environment()
        local resolver =
            global.UhhhhhhTBZShouldDetachAccessoryForBodyHide
        local seen = physicalIndex.HideSeen or {}
        physicalIndex.HideSeen = seen
        table.clear(seen)
        for _, accessory in ipairs(getPhysicalHeadIndex(physical).Children) do
            if accessory:IsA("Accessory") then
                local handle = accessory:FindFirstChild("Handle")
                if handle and handle:IsA("BasePart") then
                    local weld = handle:FindFirstChild("AccessoryWeld")
                    if weld and weld:IsA("JointInstance") then
                        seen[weld] = true

                        if accessoryBodyHideWeldStates[weld] == nil then
                            local enabled = true
                            pcall(function()
                                enabled = weld.Enabled
                            end)
                            -- A temporarily broken weld must not become the
                            -- permanent hide/show baseline and undo its repair.
                            local binding = accessoryWeldBindings[handle]
                            if binding then enabled = binding.Enabled end
                            accessoryBodyHideWeldStates[weld] = enabled
                        end

                        local shouldDetach = shouldDetachHeadAccessory(handle)
                        if type(resolver) == "function" then
                            local ok, result =
                                pcall(resolver, handle, nil)
                            shouldDetach = shouldDetach or (ok and result == true)
                        end
                        local binding = accessoryWeldBindings[handle]
                        if not ownsPhysicalPart(handle)
                            or (binding and binding.AnchorName == "Head"
                                and backend.HeadHideAccessoryRetryAt and os.clock() < backend.HeadHideAccessoryRetryAt) then
                            shouldDetach = false
                        end

                        local originalEnabled =
                            accessoryBodyHideWeldStates[weld]

                        local managed = accessoryRecoveryStates[handle]
                            and accessoryRecoveryStates[handle].Managed
                        if shouldDetach or managed then
                            pcall(function()
                                weld.Enabled = false
                            end)
                        else
                            -- The Head writer restores a visible pose first.
                            -- A PreSimulation hide callback must not reconnect a
                            -- kept hat to the previous underworld Head target.
                            if binding and binding.AnchorName == "Head" and backend.HeadHideApplied then continue end
                            local currentlyEnabled =
                                debugSafe(function()
                                    return weld.Enabled
                                end, originalEnabled)

                            if originalEnabled == true
                                and currentlyEnabled == false
                            then
                                -- Move the independent Handle onto the exact
                                -- weld solution before merging it back into the
                                -- Head/Torso assembly.
                                snapAccessoryHandleToWeld(handle, weld)
                            end

                            pcall(function()
                                weld.Enabled = originalEnabled
                            end)
                        end
                    end
                end
            end
        end

        for weld, originalEnabled in pairs(accessoryBodyHideWeldStates) do
            if not seen[weld] then
                if typeof(weld) == "Instance" and weld.Parent then
                    pcall(function()
                        weld.Enabled = originalEnabled
                    end)
                end
                accessoryBodyHideWeldStates[weld] = nil
            end
        end
    end
	
	function backend.AccessoryLifetime.Service(rig,physical)
        if not physical or not physical.Parent or not rig or not rig.Parent then return end
        local index= getPhysicalHeadIndex(physical)
        local controller=backend.AccessoryLifetime.ControllerIndex(rig)
        local now=os.clock()
        local hidden=type(Reanimate.ShouldBodyHidePart)=="function" and Reanimate.ShouldBodyHidePart("Head") == true
        local prior=backend.AccessoryMaintenance
        if prior and prior.Rig==rig and prior.Physical==physical
            and prior.Revision==index.Revision and prior.ControllerRevision==controller.Revision
            and prior.BreakWelds==options.BreakAccessoryWelds and prior.Hidden==hidden
            and prior.PD==backend.EffectivePermanentDeath and now>=prior.At and now-prior.At<.1 then return end
        backend.AccessoryMaintenance={Rig=rig,Physical=physical,Revision=index.Revision,
            ControllerRevision=controller.Revision,BreakWelds=options.BreakAccessoryWelds,
            Hidden=hidden,PD=backend.EffectivePermanentDeath,At=now}
        local inventoryOk,inventoryError=pcall(backend.AccessoryLifetime.Refresh,rig,physical)
        backend.AccessoryLifetimeError=not inventoryOk and tostring(inventoryError) or nil
        local repairOk,repairError=pcall(repairAccessoryWeldBindings)
        local hideOk,hideError=pcall(updateAccessoryBodyHideWelds)
        pdHeadFollower.AccessoryError=not repairOk and tostring(repairError)
            or not hideOk and tostring(hideError) or backend.AccessoryWeldRepairError
    end

