    local function gelatekTorsoWriterBlocked()
        return options.TorsoFling == true
            or (
                options.BulletEnabled == true
                and options.BulletLockTorso == true
            )
    end

    local function writeGelatekTorso(
        rig,
        physicalPart,
        controllerTorso,
        targetCFrame
    )
        local function releasePhysicalPart()
            local state = torsoRepRootStates[physicalPart]
            if state then
                local restored, reason = restoreManagedRepRoot(state)
                if restored then torsoRepRootStates[physicalPart] = nil
                else backend.TorsoRepRootLastError = reason end
            end
        end
        local requestedMethod = replicationWriters.GelatekTorso
        if backend.EffectivePermanentDeath == true
            or rebindInProgress
            or Reanimate.UsePhysicsRepRootPart == false
            or gelatekTorsoWriterBlocked()
            or requestedMethod ~= "PhysicsRepRootRef"
        then
            releasePhysicalPart()
            if requestedMethod == "Gelatek Physics" then torsoRepRootFailures[physicalPart] = nil end
            backend.TorsoRepRootBlockedReason = "inactive mode or Physics Glue disabled"
            return false
        end

        local global = environment()
        if global.UhhhhhhTBZGelatekFlingActive == true then
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "fling active"
            return false
        end

        local physical = backend.RealCharacter or originalCharacter
        local physicalRoot = global.UhhhhhhTBZGelatekPhysicalRoot
        if not physical
            or not physical.Parent
            or typeof(physicalPart) ~= "Instance"
            or not physicalPart:IsA("BasePart")
            or not physicalPart:IsDescendantOf(physical)
            or typeof(controllerTorso) ~= "Instance"
            or not controllerTorso:IsA("BasePart")
            or not controllerTorso:IsDescendantOf(rig)
            or typeof(targetCFrame) ~= "CFrame"
            or typeof(physicalRoot) ~= "Instance"
            or not physicalRoot:IsA("BasePart")
            or not physicalRoot.Parent
            or not physicalRoot:IsDescendantOf(physical)
            or physicalRoot == physicalPart
        then
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "invalid original part, root, controller, or pose"
            return false
        end

        local validTorsoPart = physicalPart.Name == "Torso"
            or physicalPart.Name == "UpperTorso"
            or physicalPart.Name == "LowerTorso"
        if not validTorsoPart then
            releasePhysicalPart()
            return false
        end
        if not ownsPhysicalPart(physicalRoot) or not ownsPhysicalPart(physicalPart) then
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "real torso/root assembly is not network-owned"
            return false
        end
        if type(Reanimate.ShouldBodyHidePart) == "function"
            and Reanimate.ShouldBodyHidePart("Torso") == true then
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "torso intentionally hidden"
            return false
        end

        local sameAssembly = false
        pcall(function()
            sameAssembly = physicalRoot.AssemblyRootPart
                == physicalPart.AssemblyRootPart
        end)
        if sameAssembly then
            -- A replication-root link is only useful while Gelatek has split the
            -- root and torso into separate assemblies. Never fight a live root joint.
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "root and torso still share an assembly"
            return false
        end

        -- The link is an optional replication reference, never a replacement
        -- for Gelatek's per-frame CFrame target and native netless velocity.
        local rootOffset = physical:FindFirstChild("UpperTorso")
            and CFrame.new(0, 0.194 * characterScale(), 0)
            or CFrame.identity
        local expectedRootCFrame = controllerTorso.CFrame * rootOffset
        local referenceError =
            (physicalRoot.Position - expectedRootCFrame.Position).Magnitude
        local maximumReferenceError = math.max(12 * characterScale(), 8)
        if referenceError > maximumReferenceError then
            -- A voided, flinging, or temporarily unowned HRP must never drag the
            -- visible torso with it. Native Gelatek remains the per-frame fallback.
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "real root is separated from its controller pose"
            return false
        end

        local state = torsoRepRootStates[physicalPart]
        if not state then
            state = { Writes = 0 }
            torsoRepRootStates[physicalPart] = state
        end
        local failures = torsoRepRootFailures[physicalPart]
        if not failures or failures.Requested ~= requestedMethod
            or failures.RetrySerial ~= PhysicsRoot.RetrySerial
            or failures.NextProbe and os.clock() >= failures.NextProbe
        then
            failures = {Requested = requestedMethod, RetrySerial = PhysicsRoot.RetrySerial}
            torsoRepRootFailures[physicalPart] = failures
        end
        local linked, reason = false, failures[requestedMethod]
        local selectedMethod = requestedMethod
        if not reason then
            linked, reason = writeManagedRepRoot(state, physicalPart, physicalRoot, selectedMethod)
        end
        state.Requested = requestedMethod
        state.FallbackReason = not linked and reason or nil
        backend.TorsoRepRootFallbackReason = state.FallbackReason
        if not linked then
            failures[selectedMethod] = reason
            failures.NextProbe = os.clock() + 5
            backend.TorsoRepRootLastError = reason
            local restored, restoreError = restoreManagedRepRoot(state)
            if restored then torsoRepRootStates[physicalPart] = nil
            else backend.TorsoRepRootLastError = restoreError end
            if not backend.TorsoRepRootWarned then
                backend.TorsoRepRootWarned = true
                warn("Gelatek " .. requestedMethod .. " writer fell back: " .. tostring(reason))
                Util.Notify("Torso replication link unavailable; using Gelatek Physics")
            end
            return false
        end

        if not state.NativePhysicsActive then
            -- Drop angular carry-over from the retired root-velocity copier.
            -- Subsequent motion stays with Gelatek's existing physics pass.
            pcall(function() physicalPart.AssemblyAngularVelocity = Vector3.zero end)
            state.NativePhysicsActive = true
        end
        state.LastTarget = targetCFrame
        state.ReferenceError = referenceError
        backend.TorsoRepRootLastError = nil
        backend.TorsoRepRootWarned = false
        backend.TorsoRepRootBlockedReason = nil
        -- Returning false is intentional: CFrameAlign must execute its native
        -- correction even while the hidden link is successfully installed.
        return false
    end

    -- PD transports the detached real Head with CFrame. Non-PD keeps its Neck
    -- connected and borrows Limb's replicated joint offset/angle writer.
    pdHeadFollower = {
        Head = nil, LastTarget = nil, LastError = nil, LastOwned = nil, Writes = 0,
        LinearMover = nil, AngularMover = nil, SavedProperties = nil,
        OwnershipLossSince = nil, PositionError = 0,
        JointStates = setmetatable({}, {__mode = "k"}),
        ExternalMovers = setmetatable({}, {__mode = "k"}),
        AccessoryProperties = setmetatable({}, {__mode = "k"}),
        LastStepAt = nil, LastSuccessfulWriteAt = nil, LastBlockedReason = nil,
        LastPhase = nil, AccessoryError = nil, AccessoryWrites = 0,
        Mode = "waiting", SampledTarget = nil, AcceptedWrites = 0,
        NeckChannels = {}, NeckRevision = nil, Torso = nil, SavedTorso = nil,
        HumanoidConfigured = false, LifecycleWarning = nil, OwnedWrites = 0,
    }

    resetPDHeadFollower = function()
        backend.HeadHideApplied, backend.HeadHideAccessoryRetryAt = nil, nil
        backend.HeadHideAccessoryBlockedReason, backend.HeadHideAccessoryRestorePending = nil, nil
        for _, channel in ipairs(pdHeadFollower.NeckChannels) do
            local joint, saved = channel.Joint, channel.Saved
            if joint.Parent then
                pcall(function()
                    if saved.Transform then
                        Util.SetCharacterJointTransform(joint, saved.Transform)
                        joint.Transform = saved.Transform
                    end
                    if saved.IsKinematic ~= nil then joint.IsKinematic = saved.IsKinematic end
                    if saved.Enabled ~= nil then joint.Enabled = saved.Enabled end
                end)
            end
        end
        local torso, torsoSaved = pdHeadFollower.Torso, pdHeadFollower.SavedTorso
        if torso and torso.Parent and torsoSaved then
            pcall(function()
                torso.RootPriority, torso.Massless = torsoSaved.RootPriority, torsoSaved.Massless
            end)
        end
        for _, mover in pairs({pdHeadFollower.LinearMover, pdHeadFollower.AngularMover, pdHeadFollower.Attachment}) do
            if mover then pcall(function() mover:Destroy() end) end
        end
        local head, saved = pdHeadFollower.Head, pdHeadFollower.SavedProperties
        if head then PhysicsRoot.Release(head) end
        if head and head.Parent and saved then
            pcall(function()
                head.RootPriority, head.Massless = saved.RootPriority, saved.Massless
                head.CustomPhysicalProperties = saved.CustomPhysicalProperties
                head.CanCollide, head.CanTouch, head.Anchored = saved.CanCollide, saved.CanTouch, saved.Anchored
            end)
        end
        for joint, savedJoint in pairs(pdHeadFollower.JointStates) do
            if joint.Parent then pcall(function()
                if savedJoint.Attached then
                    joint.Attachment0, joint.Attachment1 = savedJoint.Attachment0, savedJoint.Attachment1
                else joint.Part0, joint.Part1 = savedJoint.Part0, savedJoint.Part1 end
                joint.Enabled = savedJoint.Enabled
            end) end
        end
        for mover, properties in pairs(pdHeadFollower.ExternalMovers) do
            if mover.Parent then
                for property, value in pairs(properties) do
                    pcall(function() mover[property] = value end)
                end
            end
        end
        for handle, properties in pairs(pdHeadFollower.AccessoryProperties) do
            if handle.Parent then
                pcall(function()
                    handle.RootPriority, handle.Massless = properties.RootPriority, properties.Massless
                end)
            end
        end
        local humanoid = pdHeadFollower.Humanoid
        if humanoid and humanoid.Parent and pdHeadFollower.SavedHumanoid then
            for property, value in pairs(pdHeadFollower.SavedHumanoid) do
                pcall(function() humanoid[property] = value end)
            end
        end
        table.clear(pdHeadFollower.JointStates)
        table.clear(pdHeadFollower.ExternalMovers)
        table.clear(pdHeadFollower.AccessoryProperties)
        table.clear(pdHeadFollower.NeckChannels)
        pdHeadFollower.NeckRevision, pdHeadFollower.Torso, pdHeadFollower.SavedTorso = nil, nil, nil
        pdHeadFollower.Head, pdHeadFollower.Humanoid, pdHeadFollower.SavedHumanoid = nil, nil, nil
        pdHeadFollower.LinearMover, pdHeadFollower.AngularMover, pdHeadFollower.SavedProperties = nil, nil, nil
        pdHeadFollower.LastTarget, pdHeadFollower.SampledTarget, pdHeadFollower.LastError = nil, nil, nil
	pdHeadFollower.RelativeSample = nil
        pdHeadFollower.LocalDisplayError = nil
        pdHeadFollower.LastOwned, pdHeadFollower.OwnershipLossSince = nil, nil
        pdHeadFollower.PositionError, pdHeadFollower.Writes, pdHeadFollower.AccessoryWrites = 0, 0, 0
        pdHeadFollower.AcceptedWrites = 0
        pdHeadFollower.LastStepAt, pdHeadFollower.LastSuccessfulWriteAt = nil, nil
        pdHeadFollower.LastBlockedReason, pdHeadFollower.LastPhase, pdHeadFollower.AccessoryError = nil, nil, nil
        pdHeadFollower.HumanoidConfigured, pdHeadFollower.LifecycleWarning = false, nil
        pdHeadFollower.Attachment, pdHeadFollower.NativeVelocity, pdHeadFollower.RepRootCleared = nil, nil, false
        pdHeadFollower.RepRootClearError = nil
        pdHeadFollower.OwnedWrites = 0
        pdHeadFollower.Mode = "waiting"
        pdHeadFollower.Route = nil
    end
    restoreGelatekHeadWriter = resetPDHeadFollower

    local function finiteCFrame(value)
        if typeof(value) ~= "CFrame" then return false end
        local x,y,z,a,b,c,d,e,f,g,h,i = value:GetComponents()
        return x==x and y==y and z==z and a==a and b==b and c==c
            and d==d and e==e and f==f and g==g and h==h and i==i
            and math.abs(x)<math.huge and math.abs(y)<math.huge and math.abs(z)<math.huge
            and math.abs(a)<math.huge and math.abs(b)<math.huge and math.abs(c)<math.huge
            and math.abs(d)<math.huge and math.abs(e)<math.huge and math.abs(f)<math.huge
            and math.abs(g)<math.huge and math.abs(h)<math.huge and math.abs(i)<math.huge
    end

    local function finiteVector3(value)
        if typeof(value) ~= "Vector3" then return false end
        return value.X == value.X and value.Y == value.Y and value.Z == value.Z
            and math.abs(value.X) < math.huge and math.abs(value.Y) < math.huge
            and math.abs(value.Z) < math.huge
    end
    pdHeadFollower.FiniteCFrame = finiteCFrame

	-- Keep the original player root connected in normal non-PD. Splitting this
    -- assembly made the torso depend on a new ownership allocation; PhysicsRootRef
    -- cannot allocate ownership. Only the root receives a physical CFrame write.
    local bodyChain = {Joints={}, Targets={}, Properties={}}
    backend.BodyChain = bodyChain
    local function captureBodyChainJoint(joint)
        local saved={Transform=joint.Transform,Enabled=joint.Enabled}
        if joint.ClassName=="AnimationConstraint" then saved.IsKinematic=joint.IsKinematic end
        return saved
    end
    function backend.AccessoryLifetime.BodyChainJoint(physical, a, b)
        local index = getPhysicalHeadIndex(physical)
        local key = a.."/"..b
        if index.BodyChainRevision ~= index.Revision then
            index.BodyChainRevision,index.BodyChainMotors = index.Revision,{}
        end
        local cached = index.BodyChainMotors[key]
        if cached and cached.Parent then
            local p0,p1 = Util.GetCharacterJointParts(cached)
            if p0 and p1 and ((p0.Name==a and p1.Name==b) or (p0.Name==b and p1.Name==a)) then return cached end
        end
        for _, joint in ipairs(index.Joints) do
            if joint.Parent and Util.IsCharacterJoint(joint) then
                local p0, p1 = Util.GetCharacterJointParts(joint)
                if p0 and p1 and ((p0.Name==a and p1.Name==b) or (p0.Name==b and p1.Name==a)) then
                    index.BodyChainMotors[key] = joint
                    return joint
                end
            end
        end
    end
    function backend.AccessoryLifetime.CanKeepBodyChain(physical)
        if gelatekTorsoWriterBlocked() then return false, "torso/bullet mode needs a detached torso" end
        local lower = physical and physical:FindFirstChild("LowerTorso")
        local torso = physical and (physical:FindFirstChild("UpperTorso") or physical:FindFirstChild("Torso"))
        if not torso or not backend.AccessoryLifetime.BodyChainJoint(physical,"HumanoidRootPart",lower and "LowerTorso" or "Torso") then
            return false, "original root joint missing"
        end
        if lower and not backend.AccessoryLifetime.BodyChainJoint(physical,"LowerTorso","UpperTorso") then
            return false, "original waist joint missing"
        end
        return true
    end
    function backend.AccessoryLifetime.ResetBodyChain()
        for joint, saved in pairs(bodyChain.Joints) do
            if joint.Parent then pcall(function()
                if saved.DetachedForPD then
                    if saved.Attached then joint.Attachment0,joint.Attachment1=saved.Attachment0,saved.Attachment1
                    else joint.Part0,joint.Part1=saved.Part0,saved.Part1 end
                end
                joint.Transform, joint.Enabled = saved.Transform, saved.Enabled
                if saved.IsKinematic~=nil then joint.IsKinematic=saved.IsKinematic end
            end) end
        end
        for part, saved in pairs(bodyChain.Properties) do
            if part.Parent then pcall(function() part.RootPriority, part.Massless = saved.RootPriority, saved.Massless end) end
        end
        table.clear(bodyChain.Joints) table.clear(bodyChain.Properties) table.clear(bodyChain.Targets)
        bodyChain.Physical, bodyChain.Suspended, bodyChain.LastError = nil, nil, nil
    end
    function backend.AccessoryLifetime.SuspendBodyChainForFling(root)
        if not backend.KeepBodyChain then return end
        local physical = backend.RealCharacter or originalCharacter
        for _, childName in ipairs({"Torso","LowerTorso"}) do
            local joint = physical and backend.AccessoryLifetime.BodyChainJoint(physical,"HumanoidRootPart",childName)
            if joint then
                bodyChain.Joints[joint] = bodyChain.Joints[joint] or captureBodyChainJoint(joint)
                joint.Enabled = false
            end
        end
        bodyChain.Suspended = true
        table.clear(bodyChain.Targets)
    end
    function backend.AccessoryLifetime.DetachBodyChainForPD(physical)
        quiesceGelatekFollowerSupport()
        backend.AccessoryLifetime.ResetBodyChain()
        for _, link in ipairs({{"HumanoidRootPart","Torso"},{"HumanoidRootPart","LowerTorso"},{"LowerTorso","UpperTorso"}}) do
            local joint = backend.AccessoryLifetime.BodyChainJoint(physical,link[1],link[2])
            if joint then
                local saved=captureBodyChainJoint(joint)
                saved.DetachedForPD=true
                if joint.ClassName=="AnimationConstraint" then
                    saved.Attached,saved.Attachment0,saved.Attachment1=true,joint.Attachment0,joint.Attachment1
                else saved.Part0,saved.Part1=joint.Part0,joint.Part1 end
                bodyChain.Joints[joint] = saved
                joint.Enabled = false
                if joint.ClassName=="AnimationConstraint" then joint.Attachment1=nil
                else joint.Part1 = nil end -- release the actual rigid endpoint during PD
            end
        end
        backend.KeepBodyChain = false
    end
    function backend.AccessoryLifetime.UpdateBodyChain(rig, physical, poseOnly, poses)
        if not backend.KeepBodyChain then return false end
        if environment().UhhhhhhTBZGelatekFlingActive then return false end
        if bodyChain.Physical and bodyChain.Physical ~= physical then backend.AccessoryLifetime.ResetBodyChain() end
        bodyChain.Physical = physical
        local canKeep, reason = backend.AccessoryLifetime.CanKeepBodyChain(physical)
        if not canKeep then
            backend.AccessoryLifetime.ResetBodyChain()
            backend.KeepBodyChain, backend.BodyChainReason = false, reason
            local config = environment().GelatekReanimateConfig
            if config then config.CurrentAngleBodyChain = false end
            return false
        end
        local root = physical:FindFirstChild("HumanoidRootPart")
        local controllerRoot = rig:FindFirstChild("HumanoidRootPart")
        if not root or not controllerRoot then bodyChain.LastError = "real/controller root missing" return false end
        local targets = {[root]=backend.AccessoryLifetime.ControllerBodyPose(controllerRoot,poses)}
        for _, name in ipairs({"Torso","LowerTorso","UpperTorso"}) do
            local part = physical:FindFirstChild(name)
            if part then
                local controller = rig:FindFirstChild(name) or rig:FindFirstChild("Torso")
                local target = controller and backend.AccessoryLifetime.ControllerBodyPose(controller,poses)
                if target and controller.Name ~= name then target *= scaledRecoveryOffset(backend.AccessoryLifetime.BodyAnchorOffset(name)) end
                if target and type(Reanimate.ResolveBodyHideTargetCFrame)=="function" then
                    target = Reanimate.ResolveBodyHideTargetCFrame(part,target,name,false)
                end
                targets[part] = target
            end
        end
        for _, name in ipairs({"HumanoidRootPart","Torso","LowerTorso","UpperTorso"}) do
            local part = physical:FindFirstChild(name)
            if part and not finiteCFrame(targets[part]) then bodyChain.LastError = "invalid body-chain target" return false end
        end
        -- A fling temporarily isolates the root. Rejoin only at the controller
        -- root after ownership returns, never at the fling destination.
        if bodyChain.Suspended then
            if poseOnly or not ownsPhysicalPart(root) then return false end
            root.CFrame = targets[root]
        end
        local owned = ownsPhysicalPart(root)
        bodyChain.Owned, bodyChain.Root = owned, root
        if not owned then
            bodyChain.OwnershipLossSince = bodyChain.OwnershipLossSince or os.clock()
            bodyChain.LastError = "original root assembly not owned; server assignment required"
            return false
        end
        bodyChain.OwnershipLossSince = nil
        local accepted = true
        local lower = physical:FindFirstChild("LowerTorso")
        local links = {{"HumanoidRootPart",lower and "LowerTorso" or "Torso"}}
        if lower then table.insert(links,{"LowerTorso","UpperTorso"}) end
        for _, link in ipairs(links) do
            local joint = backend.AccessoryLifetime.BodyChainJoint(physical,link[1],link[2])
            if not joint then bodyChain.LastError = "original body-chain joint missing" return false end
            local p0,p1 = Util.GetCharacterJointParts(joint)
            if not p0 or not p1 or not targets[p0] or not targets[p1] then
                bodyChain.LastError = "original body-chain joint missing" return false
            end
            bodyChain.Joints[joint] = bodyChain.Joints[joint] or captureBodyChainJoint(joint)
            local offset = targets[p0]:ToObjectSpace(targets[p1])
            if not poseOnly then accepted = Util.SetCharacterJointOffset(joint,offset,nil,true)==true and accepted end
            Util.SetCharacterJointLocalOffset(joint,offset)
            joint.Enabled = true
        end
        for part in pairs(targets) do
            bodyChain.Properties[part] = bodyChain.Properties[part] or {RootPriority=part.RootPriority,Massless=part.Massless}
            local priority,massless = part==root and 127 or 0,part~=root
            if part.RootPriority~=priority then part.RootPriority=priority end
            if part.Massless~=massless then part.Massless=massless end
        end
        bodyChain.Targets, bodyChain.Suspended = targets, false
        bodyChain.LastError = not accepted and "body-chain CurrentAngle submission failed" or nil
        return accepted
    end

    local function headStillSharesBodyAssembly(physical, head)
        local root = head.AssemblyRootPart
        if not root then return true end
        for _, part in ipairs(getPhysicalHeadIndex(physical).BodyParts) do
            if part ~= head and part:IsA("BasePart") and part.AssemblyRootPart == root then
                return true
            end
        end
        return false
    end

    function pdHeadFollower.IsDetachedFromBody(physical, head)
        if not physical or not physical.Parent or not head or not head:IsA("BasePart")
            or head.Parent ~= physical or head ~= physical:FindFirstChild("Head")
            or headStillSharesBodyAssembly(physical, head) then return false end
        -- Assembly information can lag a joint edit. Require both a separate
        -- assembly and no surviving body link before rescuing a non-PD Head.
        -- Accessory welds are allowed: they should travel with this Head.
        for _, joint in ipairs(getPhysicalHeadIndex(physical).Joints) do
            if joint.Parent then
                local p0, p1 = Util.GetCharacterJointParts(joint)
                if not p0 and (joint.ClassName == "RigidConstraint" or joint.ClassName == "AnimationConstraint") then
                    p0 = joint.Attachment0 and joint.Attachment0:FindFirstAncestorWhichIsA("BasePart")
                    p1 = joint.Attachment1 and joint.Attachment1:FindFirstAncestorWhichIsA("BasePart")
                end
                local other = p0 == head and p1 or (p1 == head and p0 or nil)
                if other and other.Parent == physical and other:IsA("BasePart") then return false end
            end
        end
        return true
    end

    function pdHeadFollower.PhysicalHumanoidIsDead(physical)
        local humanoid = physical and physical:FindFirstChildOfClass("Humanoid")
        if not humanoid then return false end
        return debugSafe(function() return humanoid.Health <= 0 end, false)
            or (Enum.HumanoidStateType.Dead ~= nil
                and debugSafe(function() return humanoid:GetState() end, nil) == Enum.HumanoidStateType.Dead)
    end

	function backend.AccessoryLifetime.PrepareResetNeck(physical,head)
        if not head or not head.Parent then return end
        backend.ResetPDNeckStates=backend.ResetPDNeckStates or {}
        for _,joint in ipairs(getPhysicalHeadIndex(physical).Joints) do
            local p0,p1=Util.GetCharacterJointParts(joint)
            local other=p0==head and p1 or p1==head and p0
            if other and other.Parent==physical and (other.Name=="Torso" or other.Name=="UpperTorso") then
                local attached=joint.ClassName=="AnimationConstraint" or joint.ClassName=="RigidConstraint"
                if not backend.ResetPDNeckStates[joint] then
                    backend.ResetPDNeckStates[joint]=attached and {
                        Attached=true,Attachment0=joint.Attachment0,Attachment1=joint.Attachment1,Enabled=joint.Enabled,
                    } or {Part0=joint.Part0,Part1=joint.Part1,Enabled=joint.Enabled}
                end
                joint.Enabled=false
                if attached then joint.Attachment1=nil else joint.Part1=nil end
            end
        end
    end
    function backend.AccessoryLifetime.RestoreResetNeck()
        for joint,saved in pairs(backend.ResetPDNeckStates or {}) do
            if joint.Parent then pcall(function()
                if saved.Attached then joint.Attachment0,joint.Attachment1=saved.Attachment0,saved.Attachment1
                else joint.Part0,joint.Part1=saved.Part0,saved.Part1 end
                joint.Enabled=saved.Enabled
            end) end
        end
        backend.ResetPDNeckStates=nil
    end

    function pdHeadFollower.UpdateResetHandoff(physical, head)
	if backend.ResetPDIntent == true and options.ResetTurnsPD == true
            and backend.Running and not rebindInProgress
            and pdHeadFollower.PhysicalHumanoidIsDead(physical)
            and environment().UhhhhhhTBZGelatekPDTransitionPending ~= true then
            environment().UhhhhhhTBZGelatekPDTransitionPending = true
            quiesceGelatekFollowerSupport()
            backend.AccessoryLifetime.PrepareResetNeck(physical,head)
        end
        if backend.ResetPDIntent ~= true or options.ResetTurnsPD ~= true
            or rebindInProgress or not backend.Running
            or not pdHeadFollower.IsDetachedFromBody(physical, head) or not pdHeadFollower.PhysicalHumanoidIsDead(physical) then
            return false
        end
        local promote = environment().UhhhhhhTBZGelatekPromoteResetPD
        if type(promote) ~= "function" then return false end
        local ok, promoted = pcall(promote, physical, head)
        backend.ResetPDLastError = not ok and tostring(promoted) or nil
        if not ok or promoted ~= true then return false end
        backend.ResetPDIntent = false
        backend.ResetPDCompletedSerial = resetRequestSerial
        if type(Util.Notify) == "function" then Util.Notify("Reset -> PD") end
        return true
    end

    local function suspendCompetingHeadMovers(part)
        for _, mover in ipairs(getPhysicalHeadIndex(backend.RealCharacter or originalCharacter).Movers) do
            if mover.Parent == part and mover ~= pdHeadFollower.LinearMover and mover ~= pdHeadFollower.AngularMover then
                local property, replacement
                if mover:IsA("BodyVelocity") or mover:IsA("BodyPosition") then
                    property, replacement = "MaxForce", Vector3.zero
                elseif mover:IsA("BodyAngularVelocity") or mover:IsA("BodyGyro") then
                    property, replacement = "MaxTorque", Vector3.zero
                elseif mover:IsA("AlignPosition") or mover:IsA("AlignOrientation")
                    or mover:IsA("LinearVelocity") or mover:IsA("AngularVelocity")
                    or mover:IsA("VectorForce") or mover:IsA("Torque") then
                    property, replacement = "Enabled", false
                end
                if property then
                    if not pdHeadFollower.ExternalMovers[mover] then
                        pdHeadFollower.ExternalMovers[mover] = {[property] = mover[property]}
                    end
                    mover[property] = replacement
                end
            end
        end
    end

    local function suspendGelatekHeadLifecycle(reason)
        environment().UhhhhhhTBZGelatekFollowersPaused = true
        pdHeadFollower.LifecycleWarning = reason
        quiesceGelatekFollowerSupport()
        if type(Reanimate.SuspendPhysicsHead) == "function" then
            pcall(Reanimate.SuspendPhysicsHead, reason or "Gelatek character transition")
        elseif type(Reanimate.ReleasePhysicsHead) == "function" then
            pcall(Reanimate.ReleasePhysicsHead)
        end
    end
    local function resumeGelatekHeadLifecycle()
        environment().UhhhhhhTBZGelatekFollowersPaused = false
        pdHeadFollower.LifecycleWarning = nil
        if type(Reanimate.ResumePhysicsHead) == "function" then pcall(Reanimate.ResumePhysicsHead) end
    end

    local function writeGelatekCurrentAngleHead(physical, head, target, controllerTorso, bodyPoses, poseOnly)
        if not physical or not physical.Parent or not head or not head.Parent or not finiteCFrame(target) then
            pdHeadFollower.LastBlockedReason = "missing real Head or invalid joint target"
            return false
        end
        local torso = physical:FindFirstChild("UpperTorso") or physical:FindFirstChild("Torso")
        if not torso or not finiteCFrame(torso.CFrame) then
            pdHeadFollower.LastBlockedReason = "non-PD joint transport needs the real torso"
            return false
        end
        if pdHeadFollower.Head ~= head or pdHeadFollower.Torso ~= torso
            or pdHeadFollower.Mode ~= "ReplicateCurrentAngle6D" then
            resetPDHeadFollower()
            pdHeadFollower.Head, pdHeadFollower.Torso = head, torso
            pdHeadFollower.Mode = "ReplicateCurrentAngle6D"
            pdHeadFollower.SavedProperties = {
                RootPriority = head.RootPriority, Massless = head.Massless,
                CustomPhysicalProperties = head.CustomPhysicalProperties,
                CanCollide = head.CanCollide, CanTouch = head.CanTouch, Anchored = head.Anchored,
            }
            pdHeadFollower.SavedTorso = {RootPriority = torso.RootPriority, Massless = torso.Massless}
        end
        local index = getPhysicalHeadIndex(physical)
        if pdHeadFollower.NeckRevision ~= index.Revision then
            local channels = pdHeadFollower.NeckChannels
            for _, joint in ipairs(index.Joints) do
                if joint.Parent and (joint:IsA("Motor6D") or joint.ClassName == "AnimationConstraint") then
                    local part0, part1 = Util.GetCharacterJointParts(joint)
                    if (part0 == torso and part1 == head) or (part0 == head and part1 == torso) then
                        local found = false
                        for _, channel in ipairs(channels) do if channel.Joint == joint then found = true break end end
                        if not found then
                            table.insert(channels, {
                                Joint = joint,
                                Saved = {
                                    Transform = debugSafe(function() return joint.Transform end, CFrame.identity),
                                    Enabled = debugSafe(function() return joint.Enabled end, true),
                                    IsKinematic = debugSafe(function() return joint.IsKinematic end, nil),
                                },
                            })
                        end
                    end
                end
            end
            pdHeadFollower.NeckRevision = index.Revision
        end
        -- Keep the body as this assembly's root. The connected Head receives
        -- no physical CFrame/velocity writes; the Neck owns transport and display.
        if head.RootPriority~=-127 then head.RootPriority=-127 end
        if head.Massless~=true then head.Massless=true end
        local torsoPriority=backend.KeepBodyChain and not bodyChain.Suspended and 0 or 127
        local torsoMassless=backend.KeepBodyChain == true and not bodyChain.Suspended
        if torso.RootPriority~=torsoPriority then torso.RootPriority=torsoPriority end
        if torso.Massless~=torsoMassless then torso.Massless=torsoMassless end
        -- Derive the intended pose from the controller's torso. Compensating
        -- against a fallen, unowned physical torso hid ownership loss locally
        -- and sent a huge compensating Neck offset instead of the actual pose.
        local basis = controllerTorso and backend.AccessoryLifetime.ControllerBodyPose(controllerTorso, bodyPoses) or torso.CFrame
        if controllerTorso and torso.Name == "UpperTorso" and controllerTorso.Name == "Torso" then
            basis *= scaledRecoveryOffset(backend.AccessoryLifetime.BodyAnchorOffset("UpperTorso"))
        end
	-- The torso may be hidden through its retained root/waist joints. Neck
        -- offsets must use that intended torso pose so a visible Head stays put.
        if backend.KeepBodyChain and bodyChain.Physical==physical and bodyChain.Targets[torso] then
            basis = bodyChain.Targets[torso]
        end
        if not finiteCFrame(basis) then
            pdHeadFollower.LastBlockedReason = "invalid controller torso pose"
            return false
        end
        local relative = basis:ToObjectSpace(target)
        local wrote, channelsPresent, displayError, writeError = false, false, nil, nil
        for _, channel in ipairs(pdHeadFollower.NeckChannels) do
            local joint = channel.Joint
            if joint.Parent then
                local part0, part1 = Util.GetCharacterJointParts(joint)
                if (part0 == torso and part1 == head) or (part0 == head and part1 == torso) then
                    channelsPresent = true
                    joint.Enabled = true
                    local offset = part0 == head and relative:Inverse() or relative
                    -- Only simulation commits submit the two upstream channels.
                    -- Rendering can display the full Neck pose without rewriting
                    -- that outgoing sample or proving another client's pose.
                    if not poseOnly and ownsPhysicalPart(torso) then
                        local accepted = Util.SetCharacterJointOffset(joint, offset, nil, true)
                        wrote = accepted == true or wrote
                        if accepted ~= true then
                            local stats = Util.CharacterJointReplicationStats
                            local record = stats and stats.Joints and stats.Joints[joint]
                            writeError = record and record.LastError or "Neck replication submission failed"
                        end
                    end
                    local displayed, reason = Util.SetCharacterJointLocalOffset(joint, offset)
                    if displayed ~= true then displayError = tostring(reason or "Neck local display unavailable") end
                end
            end
        end
        pdHeadFollower.LastOwned = ownsPhysicalPart(torso)
        pdHeadFollower.PositionError = (head.Position - target.Position).Magnitude
        pdHeadFollower.LocalDisplayError = displayError
        if poseOnly then
            return channelsPresent and pdHeadFollower.LastOwned == true
                and pdHeadFollower.LastSuccessfulWriteAt ~= nil
                and os.clock() - pdHeadFollower.LastSuccessfulWriteAt < .25
                and pdHeadFollower.LastBlockedReason == nil
        end
        pdHeadFollower.LastError = not wrote and writeError or nil
        if not channelsPresent then
            pdHeadFollower.LastBlockedReason = "real Neck joint missing"
            return false
        end
        if not pdHeadFollower.LastOwned then
            pdHeadFollower.OwnershipLossSince = pdHeadFollower.OwnershipLossSince or os.clock()
            pdHeadFollower.LastBlockedReason = "real torso assembly is not owned; observer pose unverified"
            return false
        end
	if not wrote then pdHeadFollower.LastBlockedReason = "Neck writer rejected target" return false end
        pdHeadFollower.AcceptedWrites += 1
        pdHeadFollower.OwnershipLossSince = nil
        pdHeadFollower.LastTarget, pdHeadFollower.LastSuccessfulWriteAt = target, os.clock()
        pdHeadFollower.LastBlockedReason = nil
        pdHeadFollower.Writes += 1
        return true
    end

    local function writeGelatekPhysicsHead(physical, physicalHead, controllerHead, target, dt, poseOnly)
        if not physical or not physical.Parent or not physicalHead or not physicalHead.Parent
            or not controllerHead or not controllerHead.Parent or not finiteCFrame(target) then
            pdHeadFollower.LastBlockedReason = "missing real/controller Head or invalid target"
            return false
        end
        if pdHeadFollower.Head ~= physicalHead or pdHeadFollower.Mode ~= "CFrame-first owned Head" then
            local nativeVelocity = pdHeadFollower.NativeVelocity
            resetPDHeadFollower()
            pdHeadFollower.NativeVelocity = nativeVelocity
            pdHeadFollower.Mode = "CFrame-first owned Head"
            pdHeadFollower.Head = physicalHead
            pdHeadFollower.LastTarget = physicalHead.CFrame
            pdHeadFollower.SavedProperties = {
                RootPriority = physicalHead.RootPriority, Massless = physicalHead.Massless,
                CustomPhysicalProperties = physicalHead.CustomPhysicalProperties,
                CanCollide = physicalHead.CanCollide, CanTouch = physicalHead.CanTouch,
                Anchored = physicalHead.Anchored,
            }
        end
        local humanoid = physical:FindFirstChildOfClass("Humanoid")
        if humanoid and pdHeadFollower.Humanoid ~= humanoid then
            pdHeadFollower.Humanoid = humanoid
            pdHeadFollower.HumanoidConfigured, pdHeadFollower.LifecycleWarning = false, nil
            pdHeadFollower.SavedHumanoid = {
                RequiresNeck = humanoid.RequiresNeck, BreakJointsOnDeath = humanoid.BreakJointsOnDeath,
                AutoRotate = humanoid.AutoRotate,
            }
        end
        pdHeadFollower.PositionError = (physicalHead.Position - target.Position).Magnitude
        local ok, reason = pcall(function()
            if humanoid then
                humanoid.RequiresNeck, humanoid.BreakJointsOnDeath, humanoid.AutoRotate = false, false, false
            end
            -- Release the actual rigid endpoints, not only Enabled. A revived
            -- Neck, upgraded joint or attachment link must not keep this Head
            -- in the corpse assembly. The original handles and their welds stay.
            for _, joint in ipairs(getPhysicalHeadIndex(physical).Joints) do
                if joint.Parent and (joint:IsA("JointInstance") or joint:IsA("WeldConstraint")
                    or joint.ClassName == "AnimationConstraint" or joint.ClassName == "RigidConstraint") then
                    local p0, p1 = Util.GetCharacterJointParts(joint)
                    local attached = joint.ClassName == "RigidConstraint" or joint.ClassName == "AnimationConstraint"
                    if attached and not p0 then
                        p0 = joint.Attachment0 and joint.Attachment0:FindFirstAncestorWhichIsA("BasePart")
                        p1 = joint.Attachment1 and joint.Attachment1:FindFirstAncestorWhichIsA("BasePart")
                    end
                    local other = p0 == physicalHead and p1 or (p1 == physicalHead and p0 or nil)
                    if other and not other:FindFirstAncestorOfClass("Accessory") then
                        if not pdHeadFollower.JointStates[joint] then
                            pdHeadFollower.JointStates[joint] = attached
                                and {Enabled = joint.Enabled ~= false, Attached = true,
                                    Attachment0 = joint.Attachment0, Attachment1 = joint.Attachment1}
                                or {Enabled = joint.Enabled ~= false, Part0 = joint.Part0, Part1 = joint.Part1}
                        end
                        joint.Enabled = false
                        if attached then joint.Attachment1 = nil else joint.Part1 = nil end
                    end
                end
            end
            physicalHead.Anchored, physicalHead.CanCollide, physicalHead.CanTouch = false, false, false
            physicalHead.RootPriority, physicalHead.Massless = 127, false
            physicalHead.CustomPhysicalProperties = pdHeadFollower.SavedProperties.CustomPhysicalProperties
            suspendCompetingHeadMovers(physicalHead)
            if headStillSharesBodyAssembly(physical, physicalHead) then
                if pdHeadFollower.LinearMover then pdHeadFollower.LinearMover.Enabled = false end
                if pdHeadFollower.AngularMover then pdHeadFollower.AngularMover.Enabled = false end
                pdHeadFollower.LastBlockedReason = "waiting for Head/body assembly separation"
                return false
            end
            -- A successful local target assignment is NOT an ownership claim.
            -- Never let an unowned head mark this writer ready and suppress
            -- native recovery. Also never move a still-connected body through it.
            pdHeadFollower.LastOwned = ownsPhysicalPart(physicalHead)
            local marker = physicalHead:FindFirstChild("OwnershipCheck")
            if marker then marker.Transparency = pdHeadFollower.LastOwned and 1 or 0 marker.SurfaceTransparency = 1 end
            if not pdHeadFollower.LastOwned then
                pdHeadFollower.OwnershipLossSince = pdHeadFollower.OwnershipLossSince or os.clock()
                pdHeadFollower.LastBlockedReason = "real Head assembly is not network-owned; remote pose unavailable"
                return false
            end
            pdHeadFollower.OwnershipLossSince = nil
            local antiSleep = options.AntiSleep == true and math.sin(os.clock() * 15) * 0.0015 or 0
            local corrected = target + Vector3.new(0, antiSleep, 0)
            physicalHead.CFrame = corrected
            if not poseOnly then
                -- Pose distance never becomes a chase force or a launch velocity.
                local netless = tonumber(Reanimate.NetlessVelocity) or 25.1
                if netless ~= netless or math.abs(netless) == math.huge then netless = 25.1 end
                netless = math.clamp(netless, 25.01, 50)
                local root = controllerHead.Parent:FindFirstChild("HumanoidRootPart")
                local velocity = root and root.AssemblyLinearVelocity or Vector3.zero
                if not finiteVector3(velocity) then velocity = Vector3.zero end
                local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
                if horizontal.Magnitude > netless then horizontal = horizontal.Unit * netless end
                physicalHead.AssemblyLinearVelocity = Vector3.new(horizontal.X, netless, horizontal.Z)
                physicalHead.AssemblyAngularVelocity = Vector3.zero
            end
            if not pdHeadFollower.RepRootCleared then
                local ok, cleared, reason = pcall(Util.ClearPhysicsRepRootRef, physicalHead)
                pdHeadFollower.RepRootCleared = ok and cleared == true
                if pdHeadFollower.RepRootCleared then
                    pdHeadFollower.RepRootClearError = nil
                else
                    pdHeadFollower.RepRootClearError = tostring(ok and reason or cleared)
                end
            end
            return true
        end)
        pdHeadFollower.LastError = not ok and tostring(reason) or nil
        if not ok or reason ~= true then return false end
        pdHeadFollower.LastTarget, pdHeadFollower.LastSuccessfulWriteAt = target, os.clock()
        pdHeadFollower.LastBlockedReason = nil
        pdHeadFollower.Writes += 1
        pdHeadFollower.OwnedWrites += 1
        for _, accessory in ipairs(getPhysicalHeadIndex(physical).Children) do
            if accessory:IsA("Accessory") then
                local handle = accessory:FindFirstChild("Handle")
                local weld = handle and handle:FindFirstChild("AccessoryWeld")
                if handle and handle:IsA("BasePart") and weld and weld:IsA("JointInstance")
                    and weld.Enabled ~= false and (weld.Part0 == physicalHead or weld.Part1 == physicalHead) then
                    if not pdHeadFollower.AccessoryProperties[handle] then
                        pdHeadFollower.AccessoryProperties[handle] = {RootPriority = handle.RootPriority, Massless = handle.Massless}
                    end
                    handle.RootPriority, handle.Massless = -127, true
                    suspendCompetingHeadMovers(handle)
                end
            end
        end
        return true
    end

    quiesceGelatekFollowerSupport = function()
        -- Stop only movers created by this follower. Pausing or rejecting a
        -- target never rewrites an assembly's linear or angular velocity.
        for _, mover in pairs({pdHeadFollower.LinearMover, pdHeadFollower.AngularMover}) do
            if mover.Parent then pcall(function()
                if mover.Enabled then mover.Enabled = false end
            end) end
        end
        for _, state in pairs(accessoryRecoveryStates) do
            if state.Managed then pcall(function()
                if state.LinearMover and state.LinearMover.MaxForce ~= Vector3.zero then
                    state.LinearMover.MaxForce = Vector3.zero
                end
                if state.AngularMover and state.AngularMover.MaxTorque ~= Vector3.zero then
                    state.AngularMover.MaxTorque = Vector3.zero
                end
            end) end
        end
    end

    local function updateGelatekBodyChain(rig, dt, poseOnly, bodyPoses)
        if not backend.Running or rebindInProgress or not rig or not rig.Parent
            or environment().UhhhhhhTBZGelatekFollowersPaused then
            pdHeadFollower.LastBlockedReason = "bridge paused or controller missing"
            return false
        end
        local physical = backend.RealCharacter or originalCharacter
	if not physical or not physical.Parent then
            pdHeadFollower.LastBlockedReason = "real character missing"
            return false
        end
        local controllerHead = rig:FindFirstChild("Head")
        local head = physical and physical.Parent and physical:FindFirstChild("Head")
	pdHeadFollower.UpdateResetHandoff(physical, head)
        bodyPoses = bodyPoses or backend.AccessoryLifetime.ControllerBodyPoses(rig)
        if poseOnly and options.ShowMeHowILook ~= true then
            bodyPoses = backend.AccessoryLifetime.ControllerBodyPoses(rig,true)
        end
        if backend.KeepBodyChain then backend.AccessoryLifetime.UpdateBodyChain(rig,physical,poseOnly,bodyPoses) end
        if not controllerHead or not head then
            pdHeadFollower.LastBlockedReason = "real or controller Head missing"
            quiesceGelatekFollowerSupport()
            return false
        end
        if environment().UhhhhhhTBZGelatekPDTransitionPending then
            pdHeadFollower.LastBlockedReason = "follower handoff paused"
            return false
        end
        if backend.EffectivePermanentDeath == true and environment().UhhhhhhTBZGelatekPermaReady ~= true then
            pdHeadFollower.LastBlockedReason = "PD handoff not ready"
            return false
        end
        local detached = pdHeadFollower.IsDetachedFromBody(physical, head)
        bodyPoses = bodyPoses or backend.AccessoryLifetime.ControllerBodyPoses(rig)
        local target = backend.AccessoryLifetime.ControllerBodyPose(controllerHead, bodyPoses)
        local requestedHide = type(Reanimate.ShouldBodyHidePart) == "function" and Reanimate.ShouldBodyHidePart("Head") == true
        local hidden = backend.AccessoryLifetime.HeadHideReady(physical, head, requestedHide)
        if hidden and type(Reanimate.ResolveBodyHideTargetCFrame) == "function" then
            target = Reanimate.ResolveBodyHideTargetCFrame(head, target, "Head", false)
        end
        local controllerTorso = rig:FindFirstChild("UpperTorso") or rig:FindFirstChild("Torso")
        local anchor = (backend.EffectivePermanentDeath == true or detached)
            and rig:FindFirstChild("HumanoidRootPart") or controllerTorso
        local basis = anchor and backend.AccessoryLifetime.ControllerBodyPose(anchor, bodyPoses)
        local realTorso = physical:FindFirstChild("UpperTorso") or physical:FindFirstChild("Torso")
        if anchor == controllerTorso and realTorso and realTorso.Name == "UpperTorso"
            and controllerTorso and controllerTorso.Name == "Torso" and finiteCFrame(basis) then
            basis *= scaledRecoveryOffset(backend.AccessoryLifetime.BodyAnchorOffset("UpperTorso"))
        end
        local now, sample = os.clock(), nil
        if finiteCFrame(basis) and finiteCFrame(target) then
            local relative = basis:ToObjectSpace(target)
            -- Roblox handles transport cadence. A local 20 Hz sample-and-hold
            -- made smooth Neck animation visibly step, even with frame smoothing.
            sample = {Head=head, Anchor=anchor, Offset=relative, At=now,
                Show=options.ShowMeHowILook == true, Hidden=hidden, Detached=detached,
                PD=backend.EffectivePermanentDeath}
        end
        local written
        if backend.EffectivePermanentDeath == true or detached then
            written = writeGelatekPhysicsHead(physical, head, controllerHead, target, dt, poseOnly)
            pdHeadFollower.Route = backend.EffectivePermanentDeath == true and "PD" or "detached Head recovery"
        else
            written = writeGelatekCurrentAngleHead(physical, head, target,
                controllerTorso, bodyPoses, poseOnly)
            pdHeadFollower.Route = "connected non-PD joint"
        end
        if written then
            pdHeadFollower.SampledTarget = target
		pdHeadFollower.RelativeSample = sample
            backend.HeadHideApplied = hidden
            if backend.HeadHideAccessoryRestorePending and (head.Position - controllerHead.Position).Magnitude <= 4 then
                backend.AccessoryLifetime.RollbackHeadHide()
            end
        end
        return written
    end

    local function pdHeadWriterIsCurrent(head)
        return pdHeadFollower.Mode == "CFrame-first owned Head" and not rebindInProgress and head ~= nil and head.Parent ~= nil
            and pdHeadFollower.Head == head and pdHeadFollower.LastSuccessfulWriteAt ~= nil
            and os.clock() - pdHeadFollower.LastSuccessfulWriteAt < 0.25
            and pdHeadFollower.LastError == nil and pdHeadFollower.LastBlockedReason == nil
            and pdHeadFollower.LastOwned == true and ownsPhysicalPart(head)
            and not headStillSharesBodyAssembly(backend.RealCharacter or originalCharacter, head)
    end
    local function stepGelatekHeadBridge(rig, dt, phase, bodyPoses)
        backend.AccessoryLifetime.Service(rig,backend.RealCharacter or originalCharacter)
        local headOk, result = pcall(updateGelatekBodyChain, rig, dt, phase == "RenderPose" or phase == "ControllerPose", bodyPoses)
        pdHeadFollower.LastStepAt, pdHeadFollower.LastPhase = os.clock(), phase
        if not headOk then pdHeadFollower.LastError = tostring(result) end
        if not headOk or result ~= true then quiesceGelatekFollowerSupport() end
        environment().UhhhhhhTBZGelatekPDHeadWriterActive = headOk and result == true
            and pdHeadWriterIsCurrent(pdHeadFollower.Head) or false
        return headOk and result == true
    end

    local function resolveGelatekAccessoryTargetCFrame(handle, controllerHandle, bodyPoses)
        local targetCFrame = backend.AccessoryLifetime.ControllerPose(controllerHandle, nil, nil, bodyPoses) or controllerHandle.CFrame
        local global = environment()
        local resolver = global.UhhhhhhTBZGetBodyHideTargetInfo

        if type(resolver) == "function" then
            local ok, shouldHide, anchorName =
                pcall(resolver, handle, controllerHandle, nil, true)
            if ok and shouldHide == true
                and type(Reanimate.ResolveBodyHideTargetCFrame) == "function"
            then
                targetCFrame =
                    Reanimate.ResolveBodyHideTargetCFrame(
                        handle,
                        targetCFrame,
                        anchorName,
                        false
                    )
            end
        end
        return targetCFrame
    end

    local function restoreAccessoryRecoveryState(handle, state)
        PhysicsRoot.Release(handle)
            if type(state) == "table" then
                if state.LinearMover then state.LinearMover:Destroy() end
                if state.AngularMover then state.AngularMover:Destroy() end
                for mover, properties in pairs(state.ExternalMovers or {}) do
                    if mover.Parent then for key, value in pairs(properties) do mover[key] = value end end
                end
            end
            if handle and handle.Parent and type(state) == "table" then
                pcall(function()
                    if state.Massless ~= nil then
                        handle.Massless = state.Massless
                    end
                    handle.CustomPhysicalProperties =
                        state.CustomPhysicalProperties
                    if state.RootPriority ~= nil then handle.RootPriority = state.RootPriority end
                    if state.Anchored ~= nil then handle.Anchored = state.Anchored end
                    if state.CanCollide ~= nil then handle.CanCollide = state.CanCollide end
                    if state.CanTouch ~= nil then handle.CanTouch = state.CanTouch end
                end)
            end
            if type(state) == "table" and state.Weld and state.Weld.Parent then
                local weld = state.Weld
                weld.Enabled = false
                local binding = accessoryWeldBindings[handle]
                if binding and binding.Part0 and binding.Part0.Parent
                    and binding.Part1 and binding.Part1.Parent then
                    weld.Part0, weld.Part1 = binding.Part0, binding.Part1
                    weld.C0, weld.C1 = binding.C0, binding.C1
                    if weld:IsA("Motor6D") and binding.Transform then weld.Transform = binding.Transform end
                end
                -- Place only a separate, owned Handle on the saved weld's
                -- exact solution before merging it with the visible Head.
                if state.WeldEnabled then snapAccessoryHandleToWeld(handle, weld) end
                weld.Enabled = state.WeldEnabled
            end
    end
    function backend.AccessoryLifetime.RestoreManaged(handle, state)
        restoreAccessoryRecoveryState(handle, state)
        accessoryRecoveryStates[handle] = nil
    end
    restoreAccessoryRecoveryStates = function()
        for handle, state in pairs(accessoryRecoveryStates) do restoreAccessoryRecoveryState(handle, state) end
        table.clear(accessoryRecoveryStates)
    end

    local function writeCFrameGelatekAccessory(pair, dt, poseOnly, bodyPoses)
        local handle, controller = pair.Physical, pair.Controller
        if not handle or not handle.Parent or not controller or not controller.Parent then return false end
        -- Only a committed physics pose may touch the original server Handle.
        -- Controller/render callbacks otherwise made local hats look smoother
        -- than the pose/velocity sample observers actually received.
        if poseOnly or environment().UhhhhhhTBZGelatekFollowersPaused then return false end
        local state = accessoryRecoveryStates[handle]
        local target = resolveGelatekAccessoryTargetCFrame(handle, controller, bodyPoses)
        if not finiteCFrame(target) then
            if state then
                state.LastBlockedReason = "invalid controller accessory pose"
                state.SampleCFrame, state.SampleAt = nil, nil
            end
            return false
        end
        if not state or not state.Managed then
            state = {Managed = true, LastCFrame = handle.CFrame, Writes = 0, ExternalMovers = {},
                RootPriority = handle.RootPriority, Massless = handle.Massless,
                CustomPhysicalProperties = handle.CustomPhysicalProperties,
                Anchored = handle.Anchored, CanCollide = handle.CanCollide, CanTouch = handle.CanTouch,
                Physics = PhysicalProperties.new(0.05, 0, 0, 0, 0)}
            accessoryRecoveryStates[handle] = state
            local binding = accessoryWeldBindings[handle]
            if binding then
                if binding.RootPriority ~= nil then state.RootPriority = binding.RootPriority end
                if binding.Massless ~= nil then state.Massless = binding.Massless end
            end
        end
        state.Controller = controller
        local weld = handle:FindFirstChild("AccessoryWeld")
        if weld and weld:IsA("JointInstance") then
            if state.Weld ~= weld then
                state.Weld, state.WeldEnabled = weld, weld.Enabled ~= false
                local binding = accessoryWeldBindings[handle]
                if binding then state.WeldEnabled = binding.Enabled end
            end
            weld.Enabled = false
        end
        local index, root = getPhysicalHeadIndex(backend.RealCharacter or originalCharacter), handle.AssemblyRootPart
        local sharesBody = root == nil
        for _, part in ipairs(index.BodyParts) do
            if part.AssemblyRootPart == root then sharesBody = true break end
        end
        local assemblyAccessory = root and root:FindFirstAncestorOfClass("Accessory")
        if assemblyAccessory and assemblyAccessory ~= handle.Parent then sharesBody = true end
        if sharesBody then
            if state.LinearMover then state.LinearMover.MaxForce = Vector3.zero end
            if state.AngularMover then state.AngularMover.MaxTorque = Vector3.zero end
            state.LastBlockedReason = "waiting for accessory/body assembly separation"
            state.SampleCFrame, state.SampleAt = nil, nil
            return false
        end
        -- No head-only exception: hair, face, neck, back and other handles all
        -- use their original server part and exact invisible-controller target.
        for _, mover in ipairs(index.Movers) do
            if mover.Parent == handle and mover ~= state.LinearMover and mover ~= state.AngularMover then
                local property, replacement
                if mover:IsA("BodyVelocity") or mover:IsA("BodyPosition") then property, replacement = "MaxForce", Vector3.zero
                elseif mover:IsA("BodyAngularVelocity") or mover:IsA("BodyGyro") then property, replacement = "MaxTorque", Vector3.zero
                else property, replacement = "Enabled", false end
                if not state.ExternalMovers[mover] then state.ExternalMovers[mover] = {[property] = mover[property]} end
                mover[property] = replacement
            end
        end
        handle.Anchored, handle.CanCollide, handle.CanTouch = false, false, false
        handle.RootPriority, handle.Massless = 127, false
        handle.CustomPhysicalProperties = state.Physics
        -- This path has no velocity/position chase mover. Copy the original
        -- server handle only once it has its own, locally owned assembly.
        for _, key in ipairs({"LinearMover", "AngularMover"}) do
            if state[key] then state[key]:Destroy(); state[key] = nil end
        end
        state.LastOwned = ownsPhysicalPart(handle)
        state.OwnershipSource = state.LastOwned and "owned assembly" or "unowned assembly"
        if not state.LastOwned then
            state.LastBlockedReason = "accessory assembly is not network-owned"
            state.SampleCFrame, state.SampleAt = nil, nil
            return false
        end
        local now = os.clock()
        local netless = tonumber(Reanimate.NetlessVelocity) or 25.1
        if netless ~= netless or math.abs(netless) == math.huge then netless = 25.1 end
        netless = math.clamp(netless, 25.01, 50)
        local rig = controller:FindFirstAncestorOfClass("Model")
        local rootPart = rig and rig:FindFirstChild("HumanoidRootPart")
        local velocity = rootPart and rootPart.AssemblyLinearVelocity or Vector3.zero
        if not finiteVector3(velocity) then velocity = Vector3.zero end
        local angular = Vector3.zero
        local elapsed = state.SampleAt and now - state.SampleAt or 0
        if finiteCFrame(state.SampleCFrame) and elapsed > 1e-5 and elapsed <= .25 then
            local displacement = target.Position - state.SampleCFrame.Position
            -- A teleport/hide transition is a discontinuity, not a launch impulse.
            if displacement.Magnitude <= math.max(6, netless * elapsed * 4) then
                velocity = displacement / elapsed
                if not finiteVector3(velocity) then velocity = Vector3.zero end
                if Reanimate.UseAngularVelocity == true then
                    local axis, angle = (target.Rotation * state.SampleCFrame.Rotation:Inverse()):ToAxisAngle()
                    if finiteVector3(axis) and angle == angle and math.abs(angle) < math.huge then
                        angular = axis * math.min(angle / elapsed, 40)
                        if not finiteVector3(angular) then angular = Vector3.zero end
                    end
                end
            end
        end
        local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
        if horizontal.Magnitude > netless then horizontal = horizontal.Unit * netless end
        handle.AssemblyLinearVelocity = Vector3.new(horizontal.X, netless, horizontal.Z)
        handle.AssemblyAngularVelocity = angular
        local antiSleep = options.AntiSleep and math.sin(now * 15) * .0015 or 0
        handle.CFrame = target + Vector3.new(0, antiSleep, 0)
        local clearOk, cleared, clearReason = pcall(Util.ClearPhysicsRepRootRef, handle)
        state.RepRootCleared = clearOk and cleared == true
        state.RepRootClearError = not state.RepRootCleared and tostring(clearOk and (clearReason or "root reference clear unverified") or cleared) or nil
        state.SampleCFrame, state.SampleAt = target, now
        state.LinearVelocity, state.AngularVelocity = handle.AssemblyLinearVelocity, angular
        state.LastCFrame, state.LastBlockedReason, state.LastWriteError = target, nil, nil
        state.LastSuccessfulWriteAt = now
        state.Writes += 1
        return true
    end

    local function writeDetachedGelatekAccessory(pair, dt, poseOnly, bodyPoses)
        if poseOnly then return false end
        local handle = pair and pair.Physical
        local controllerHandle = pair and pair.Controller
        if pair and pair.Lifetime and (pair.Lifetime.SourceDestroyed or pair.Lifetime.HandleDestroyed) then
            local state=handle and accessoryRecoveryStates[handle]
            if state then state.LastBlockedReason=pair.Lifetime.Blocked end
            return false
        end
        if not handle
            or not handle:IsA("BasePart")
            or not handle.Parent
            or not controllerHandle
            or not controllerHandle:IsA("BasePart")
            or not controllerHandle.Parent
        then
            local state = handle and accessoryRecoveryStates[handle]
            if state then
                state.LastBlockedReason = "missing real or controller accessory Handle"
                state.SampleCFrame, state.SampleAt = nil, nil
            end
            return false
        end
        -- Core transport is not permission to sever an intact real weld.
        -- Preserve the original assembly unless
        -- the user explicitly enabled detachment or this handle is hidden.
        local resolver = environment().UhhhhhhTBZShouldDetachAccessoryForBodyHide
        local hiddenOk, hidden = false, false
        if type(resolver) == "function" then hiddenOk, hidden = pcall(resolver, handle, controllerHandle) end
        local binding = accessoryWeldBindings[handle]
        local rollback = (backend.EffectivePermanentDeath == true and not ownsPhysicalPart(handle))
            or (binding and binding.AnchorName == "Head" and backend.HeadHideAccessoryRestorePending)
        if rollback then
            local state = accessoryRecoveryStates[handle]
            if state then
                state.LastOwned = ownsPhysicalPart(handle) state.LastBlockedReason = "accessory handoff paused"
                state.SampleCFrame, state.SampleAt = nil, nil
            end
            if not (binding and binding.AnchorName == "Head" and backend.HeadHideApplied) then
                if state and state.Weld and state.Weld.Parent then backend.AccessoryLifetime.RestoreManaged(handle, state) end
            end
            local weld = handle:FindFirstChild("AccessoryWeld")
            if weld and weld:IsA("JointInstance") then return false end
        end
        if not shouldDetachHeadAccessory(handle) and not (hiddenOk and hidden == true and not rollback) then
            local state = accessoryRecoveryStates[handle]
            if state and state.Managed and state.Weld and state.Weld.Parent then
                restoreAccessoryRecoveryState(handle, state)
                accessoryRecoveryStates[handle] = nil
                repairAccessoryWeldBindings()
            end
            local weld = handle:FindFirstChild("AccessoryWeld")
            if weld and weld:IsA("JointInstance") and weld.Enabled ~= false
                and weld.Part0 and weld.Part0.Parent and weld.Part1 and weld.Part1.Parent then
                return false
            end
        end
        local ok, result = pcall(writeCFrameGelatekAccessory, pair, dt, poseOnly, bodyPoses)
        if not ok then
            local state = accessoryRecoveryStates[handle]
            if state then state.LastWriteError = tostring(result) end
            backend.AccessoryTransportError = tostring(result)
        end
        return ok and result == true
    end

    local function attachScaleBridge(rig)
        detachScaleBridge()
        backend.LastControllerPoseAt = nil
        local bridgeToken = activeGenerationToken
        assert(bridgeToken ~= nil, "Gelatek bridge has no generation owner")
        local function bridgeIsActive()
            return generationIsActive(bridgeToken, rig)
        end
        local global = environment()
        global.UhhhhhhTBZGelatekControllerBodyPose = function(part)
            if bridgeIsActive() and part and part.Parent == rig then
                return backend.AccessoryLifetime.ControllerBodyPose(part)
            end
            return nil
        end
        global.UhhhhhhTBZGelatekPDHeadWriterActive = false
        global.UhhhhhhTBZGelatekPDHeadWriterReady = function(head)
            return bridgeIsActive() and pdHeadWriterIsCurrent(head)
        end
        global.UhhhhhhTBZRestoreRepRoots = function()
            restoreGelatekTorsoWriter()
            restoreGelatekRootRepRoot()
            PhysicsRoot.RestoreAll()
        end
        global.UhhhhhhTBZGelatekTorsoWriter = function(
            physicalPart,
            controllerPart,
            targetCFrame
        )
            if not bridgeIsActive()
                or typeof(physicalPart) ~= "Instance"
                or not (
                    physicalPart.Name == "Torso"
                    or physicalPart.Name == "UpperTorso"
                    or physicalPart.Name == "LowerTorso"
                )
            then
                return false
            end
		if backend.KeepBodyChain and not bodyChain.Suspended then
                return true -- root + CurrentAngle own this connected assembly
            end
            return writeGelatekTorso(
                rig,
                physicalPart,
                controllerPart,
                targetCFrame
            )
        end
        if replicationWriters.GelatekTorso == "PhysicsRepRootRef"
            and gelatekTorsoWriterBlocked()
        then
            backend.TorsoRepRootLastError =
                "disabled by a torso/bullet fling mode"
            backend.TorsoRepRootWarned = true
            Util.Notify("Torso replication link paused by the active Gelatek mode")
        end
        attachPhysicalAnimationSuppression(
            backend.RealCharacter or originalCharacter
        )
        applyCharacterScale(rig, true)
        controllerSettingsCleanup = Context.ControllerSettings({
            Rig = rig, Reanimate = Reanimate, RunService = RunService,
        })
        local generationSafePivot = rig:GetPivot()
        local initialRoot = rig:FindFirstChild("HumanoidRootPart")
        assert(
            initialRoot and initialRoot:IsA("BasePart"),
            "Gelatek controller lost HumanoidRootPart before bridge attachment"
        )
        local floatSafeY = initialRoot.Position.Y
        scaleBridgeConnection = RunService.Heartbeat:Connect(function()
            if not bridgeIsActive() then
                return
            end
            Reanimate.GelatekDisableDirectionalWalking =
                options.DisableDirectionalWalking == true
            applyCharacterScale(rig)
            updateInfiniteJump(rig)
            global.UhhhhhhTBZGelatekAntiSleep = options.AntiSleep == true
            if backend.EffectivePermanentDeath == true
                or Reanimate.UsePhysicsRepRootPart == false
                or gelatekTorsoWriterBlocked()
                or replicationWriters.GelatekTorso ~= "PhysicsRepRootRef"
                or global.UhhhhhhTBZGelatekFlingActive == true
            then
                restoreGelatekTorsoWriter()
            else
                local physical = backend.RealCharacter or originalCharacter
                local physicalRoot = global.UhhhhhhTBZGelatekPhysicalRoot
                local controllerTorso = rig:FindFirstChild("Torso")
                    or rig:FindFirstChild("UpperTorso")
                if not physical
                    or not physical.Parent
                    or typeof(physicalRoot) ~= "Instance"
                    or not physicalRoot.Parent
                    or not ownsPhysicalPart(physicalRoot)
                    or not controllerTorso
                then
                    restoreGelatekTorsoWriter()
                else
                    local rootOffset = physical:FindFirstChild("UpperTorso")
                        and CFrame.new(0, 0.194 * characterScale(), 0)
                        or CFrame.identity
                    local expectedRoot = controllerTorso.CFrame * rootOffset
                    if (physicalRoot.Position - expectedRoot.Position).Magnitude
                        > math.max(12 * characterScale(), 8)
                    then
                        restoreGelatekTorsoWriter()
                    end
                end
            end
        end)

        -- Compatibility notification for controller tracking. The independent
        -- phase callbacks below consume its completed controller pose.
        global.UhhhhhhTBZGelatekRenderHeadSync = function()
            if not bridgeIsActive() or rebindInProgress then
                return false
            end
            -- Tracking already changed the controller Head; this function
            -- reports readiness without introducing another writer.
            return pdHeadWriterIsCurrent(pdHeadFollower.Head)
        end

        -- Shared maintenance owns weld repair/hiding; it is invalidated by rig
        -- changes and switches, and does not run a second full accessory scan.

        -- The proxy owns locomotion. Detached physical followers stay isolated.
        -- Collision is shared with Limb; this name set is only for void recovery.
        local controllerBodyNames = {
            Head = true, Torso = true, UpperTorso = true, LowerTorso = true,
            HumanoidRootPart = true,
            ["Left Arm"] = true, ["Right Arm"] = true,
            ["Left Leg"] = true, ["Right Leg"] = true,
            LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
            RightUpperArm = true, RightLowerArm = true, RightHand = true,
            LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
            RightUpperLeg = true, RightLowerLeg = true, RightFoot = true,
        }
        local collisionErrorReported = false
        controllerCollisionConnection = RunService.PreSimulation:Connect(function(dt)
            if not bridgeIsActive() then
                return
            end
            enforcePhysicalShellIsolation(backend.RealCharacter or originalCharacter)
            local humanoid = rig:FindFirstChildOfClass("Humanoid")
            local root = rig:FindFirstChild("HumanoidRootPart")
            if not humanoid or not root then
                return
            end
            local stateName = "Physics"
            local collisionOk, collisionResult = pcall(
                Reanimate.ApplyControllerCollision,
                rig,
                humanoid,
                root,
                true
            )
            if collisionOk and type(collisionResult) == "string" then
                stateName = collisionResult
            else
                local stateOk, state = pcall(humanoid.GetState, humanoid)
                if stateOk and state then
                    stateName = state.Name
                end
                if not collisionOk and not collisionErrorReported then
                    collisionErrorReported = true
                    warn("Gelatek collision bridge recovered: " .. tostring(collisionResult))
                end
            end
            local passive = not table.find(
                {"Running", "Jumping", "Freefall", "Landed", "Climbing", "Swimming"}, stateName)
            if options.RagdollSelfCollision == false and passive then
                if not ragdollCollisionFolder then
                    ragdollCollisionFolder = Instance.new("Folder")
                    ragdollCollisionFolder.Name = "_UhhhhhhOptionalRagdollSelfCollision"
                    ragdollCollisionFolder.Parent = rig
                    local parts = {}
                    for _, part in ipairs(rig:GetChildren()) do
                        if part:IsA("BasePart") and controllerBodyNames[part.Name] then
                            table.insert(parts, part)
                        end
                    end
                    for i, part in ipairs(parts) do
                        for j = i + 1, #parts do
                            local exclusion = Instance.new("NoCollisionConstraint")
                            exclusion.Part0, exclusion.Part1 = part, parts[j]
                            exclusion.Parent = ragdollCollisionFolder
                        end
                    end
                end
            elseif ragdollCollisionFolder then
                ragdollCollisionFolder:Destroy()
                ragdollCollisionFolder = nil
            end
            if rebindInProgress then
                isolatePhysicalCharacter(pendingPhysicalCharacter)
            end
            if options.RecoverBeforeVoid then
                local floor = environment().UhhhhhhTBZGelatekDestroyHeight or -500
                -- A detached limb below the root must not repeatedly teleport
                -- the whole ragdoll while its controller root is still safe.
                local predictedY = root.Position.Y
                    + math.min(root.AssemblyLinearVelocity.Y, 0) * math.clamp(dt or 0, 0, 0.25)
                if math.min(root.Position.Y, predictedY) < floor + 80 then
                    -- Move the whole controller, including jointless parts.
                    pcall(function()
                        rig:PivotTo(generationSafePivot + Vector3.new(0, 3, 0))
                        for _, part in ipairs(rig:GetChildren()) do
                            if part:IsA("BasePart") and controllerBodyNames[part.Name] then
                                part.AssemblyLinearVelocity = Vector3.zero
                                part.AssemblyAngularVelocity = Vector3.zero
                            end
                        end
                    end)
                end
            end
            pcall(function()
                rig:SetAttribute(
                    "_Uhhhhhh_SeatWeldActive",
                    stateName == "Seated" and (humanoid.Sit or humanoid.SeatPart ~= nil)
                )
            end)
        end)

        local safeParams = RaycastParams.new()
        safeParams.FilterType = Enum.RaycastFilterType.Exclude
        safeParams.RespectCanCollide = true
        safeParams.IgnoreWater = false
        safeTrackerConnection = RunService.PostSimulation:Connect(function()
            if not bridgeIsActive() or rebindInProgress then
                return
            end
            local humanoid = rig:FindFirstChildOfClass("Humanoid")
            local root = rig:FindFirstChild("HumanoidRootPart")
            if not humanoid or not root or not root:IsA("BasePart") then
                return
            end

            -- Excluding rig excludes both the controller and Gelatek's nested
            -- physical Character. Non-collidable helper parts are ignored by
            -- RespectCanCollide, so they cannot become LastSafe.
            safeParams.FilterDescendantsInstances = { rig }
            local scale = math.max(tonumber(Reanimate.CharacterScale) or 1, 0.001)
            local maximumGroundDistance = 3 * scale + 8 + humanoid.HipHeight
            local safe = true
            local void = true
            for i = 1, 8 do
                local offset =
                    CFrame.Angles(0, (i / 4) * math.pi, 0)
                        :VectorToWorldSpace(Vector3.new(0, 0, -0.5 * scale))
                local hit = workspace:Raycast(
                    root.Position + offset,
                    Vector3.new(0, -65536, 0),
                    safeParams
                )
                if hit then
                    void = false
                end
                if not hit or hit.Distance > maximumGroundDistance then
                    safe = false
                end
            end
            if safe then
                Reanimate.LastSafeCFrame = root.CFrame
                generationSafePivot = rig:GetPivot()
            end
            local stateOk, state = pcall(humanoid.GetState, humanoid)
            if (stateOk and state.Name == "Climbing") or not void then
                floatSafeY = root.Position.Y
            elseif Reanimate.PatchmaVoidFloat then
                -- Same no-ground-below trigger as Limb; translate the whole
                -- controller to retain relative jointless/ragdoll poses.
                pcall(function()
                    rig:PivotTo(rig:GetPivot() + Vector3.new(0, floatSafeY - root.Position.Y, 0))
                    for _, part in ipairs(rig:GetChildren()) do
                        if part:IsA("BasePart") and controllerBodyNames[part.Name] then
                            part.AssemblyLinearVelocity *= Vector3.new(1, 0, 1)
