	["BlaaBlaaReanim/System/runtime/steve110/loader.lua"] = [=[
-- Module tree compatible with Steve 1.1.0's script.Parent/require architecture.
-- Stock UI modules are embedded locally; no mutable DEV binary executes at startup.
return function(rootPath)
    local cache, loading, nodes = {}, {}, {}
    local base = getfenv(1)
    local Loader = {Version = "1.1.0 DEV", PayloadSHA256 = "87e733744c6a574a1a68e4bef8e681f91c6342893ef1f43cb207d28ab55ffeee"}
    local function node(path)
        if nodes[path] then return nodes[path] end
        local current = {ModulePath = path}
        nodes[path] = current
        local parent = path:match("^(.*)/[^/]+$")
        if parent then current.Parent = node(parent) end
        return setmetatable(current, {__index = function(_, key)
            assert(type(key) == "string" and key:match("^[%w_]+$"), "invalid module child")
            return node(path .. "/" .. key)
        end})
    end
    function Loader.Seed(path, value)
        assert(type(path) == "string" and value ~= nil, "invalid module export")
        cache[path] = value
    end
    function Loader.Require(value)
        local path = type(value) == "table" and rawget(value, "ModulePath") or value
        assert(type(path) == "string" and path:match("^[%w_/]+$") and not path:find("..", 1, true), "invalid module path")
        if cache[path] ~= nil then return cache[path] end
        assert(not loading[path], "circular module dependency: " .. path)
        loading[path] = true
        local ok, result = pcall(function()
            local filename = rootPath .. "/" .. path .. ".lua"
            local chunk, failure = loadstring(readfile(filename), "@Steve110/" .. path)
            assert(type(chunk) == "function", tostring(failure))
            setfenv(chunk, setmetatable({script = node(path), require = Loader.Require}, {__index = base}))
            return chunk()
        end)
        loading[path] = nil
        if not ok then error("Steve110 " .. path .. ": " .. tostring(result), 2) end
        assert(result ~= nil, "module returned nil: " .. path)
        cache[path] = result
        return result
    end
    function Loader.ReadData(path)
        assert(path:match("^[%w_/]+$"), "invalid data path")
        return readfile(rootPath .. "/" .. path .. ".lua")
    end
    return Loader
end
