	local HBC0 = CFrame.new(0, -3.94, 2.94, 1, 0, 0, 0, 0, 1, 0, -1, 0):Inverse()
	local lerps = {
		idle = function(timingsine, rt, nt, rst, lst, rht, lht)
			rt = RC0 * CFrame.Angles(math.rad(10), 0, math.rad(60))
