				x = tostring(x):lower()
				local exp = x:split("e")
				x = exp[1]
				local dec = x:split(".")
				if #dec > 1 then
					x = dec[1]
					dec = dec[2]:sub(1, 3)
					while dec:sub(-1, -1) == "0" do
						dec = dec:sub(1, -2)
					end
					if #dec > 0 then
						x ..= "." .. dec
					end
				end
				if #exp > 1 then
					x ..= "e" .. exp[2]
