	["BlaaBlaaReanim/System/runtime/steve110/main/assetcache.lua"] = [=[
-- Verified-byte cache and bounded worker queue shared by the mod download adapters.
return function(Context)
    local Cache = {Entries = {}}
    local now = Context.Clock or os.clock
    local scheduler = Context.Task or task
    local warning = Context.Warn or warn
    local capacity, cursor, slots = math.max(16, tonumber(Context.MaximumEntries) or 256), 1, {}
    local function remember(path, valid, nextCheck)
        local existing = Cache.Entries[path]
        if existing then existing.Valid, existing.NextCheck = valid, nextCheck return existing end
        local old = slots[cursor]
        if old and Cache.Entries[old.Path] == old.Record then Cache.Entries[old.Path] = nil end
        local record = {Valid = valid, NextCheck = nextCheck}
        Cache.Entries[path], slots[cursor] = record, {Path = path, Record = record}
        cursor = cursor % capacity + 1
        return record
    end
    local function usable(body)
        return type(body) == "string" and #body > 0
            and not body:sub(1, 256):lower():match("^%s*<!doctype html")
            and not body:sub(1, 256):lower():match("^%s*<html")
            and body:sub(1, 14) ~= "404: Not Found"
    end
    function Cache.Invalidate(path) Cache.Entries[path] = nil end
    function Cache.Verified(path) remember(path, true, now() + 1) end
    function Cache.Has(path)
        local record = Cache.Entries[path]
        if record and now() < record.NextCheck then return record.Valid end
        local exists, present = pcall(Context.IsFile, path)
        if not exists or not present then
            remember(path, false, now() + 0.1)
            return false
        end
        if record and record.Valid then
            record.NextCheck = now() + 1
            return true -- bytes were already checked; do not reread whole MP3/anim each frame
        end
        local ok, body = pcall(Context.ReadFile, path)
        local valid = ok and usable(body)
        if valid and Context.Validate then
            local validated, result = pcall(Context.Validate, path, body)
            valid = validated and result == true
        end
        remember(path, valid, now() + (valid and 1 or 0.1))
        return valid
    end
    function Cache.Queue(workerCount)
        assert(type(workerCount) == "number" and workerCount >= 1 and workerCount % 1 == 0, "invalid asset worker count")
        local queue, active, head = {}, 0, 1
        local Queue = {}
        local function pump()
            while active < workerCount and queue[head] do
                local callback = queue[head];queue[head] = false;head += 1;active += 1
                scheduler.spawn(function()
                    local ok, failure = pcall(callback)
                    active -= 1
                    if not ok then warning("Asset queue job: " .. tostring(failure)) end
                    pump()
                end)
            end
            if active == 0 and not queue[head] then table.clear(queue);head = 1 end
        end
        function Queue.Push(callback) table.insert(queue, callback);pump() end
        return Queue
    end
    return Cache
end
