return function(label, maximum)
    local text, hadErrors = "", false
    maximum = maximum or 48000
    local log = {}
    function log.Reset(value) text, hadErrors = "", false; log.Append(value) end
    function log.Set(value)
        value = tostring(value or "")
        hadErrors = hadErrors or value:find("[ERROR]", 1, true) ~= nil
        text = value
        if #text > maximum then
            local start = #text - maximum + 129
            local newline = text:find("\n", start, true)
            start = newline and newline + 1 or start
            -- A byte boundary must not split UTF-8 used in community names.
            while start <= #text and text:byte(start) >= 128 and text:byte(start) < 192 do start += 1 end
            text = "[LOG] Older entries omitted.\n" .. text:sub(start)
        end
        label.Text = text
    end
    function log.Append(value) log.Set(text .. tostring(value or "")) end
    function log.HasErrors() return hadErrors end
    return setmetatable(log, {__index = function(_, key) if key == "Text" then return text end end,
        __newindex = function(_, key, value) assert(key == "Text", "Unknown log field"); log.Set(value) end})
end
