-- Optional controller pose effects. Original physical assemblies are never edited here.
return function(ctx)
    local api, saved = {}, ctx.SaveData.CharacterMotionSettings
    if type(saved) ~= "table" then saved = {} ctx.SaveData.CharacterMotionSettings = saved end
    local function number(value, fallback, minimum, maximum)
        value = tonumber(value)
        if not value or value ~= value or math.abs(value) == math.huge then value = fallback end
        return math.clamp(value, minimum, maximum)
    end
    for _, key in ipairs({"InverseKinematics", "DirectionalWalking", "FrameSmoothing"}) do saved[key] = saved[key] == true end
    saved.IKStrength = number(saved.IKStrength, .65, 0, 1)
    saved.TurnResponse = number(saved.TurnResponse, 10, 1, 30)
    saved.FrameRate = number(saved.FrameRate, 60, 15, 120)
    saved.ReviewTime = number(saved.ReviewTime, 15, 1, 120)
    saved.TrackScope = saved.TrackScope == "All AnimLib tracks" and saved.TrackScope or "Low frame rate tracks"
    saved.SmoothFacing = saved.SmoothFacing ~= false
    saved.R6IKMethod = saved.R6IKMethod == "Rigid leg" and saved.R6IKMethod or "Virtual knee"
    saved.ContactResponse = number(saved.ContactResponse,14,1,30)
    saved.IKBlendTime = number(saved.IKBlendTime,.14,.03,.4)
    saved.IKMaxTilt = number(saved.IKMaxTilt,25,5,60)
    saved.LeanAngle = number(saved.LeanAngle,15,0,35)
    saved.LegAngle = number(saved.LegAngle,25,0,60)
    api.Settings = saved
    local adapter=ctx.RigAdapter
    local function owner(rig) return adapter and adapter.Owner(rig) or rig end
	local function poseJoint(joint) return joint:IsA("Motor6D") or joint.ClassName=="AnimationConstraint" end
    local function jointParts(joint)
        if adapter then return adapter.JointParts(joint) end
        return joint.Part0,joint.Part1
    end
    local function jointFrames(joint)
        if adapter then return adapter.JointFrames(joint) end
        return joint.C0,joint.C1
    end
    local clock = ctx.Clock or os.clock
    local state = {Corrections = {}, Connections = {}, Joints = {}, Contacts={}, Rest={}, Blends={}, Direction=Vector3.zero, Dt=1/60}
    local function finiteNumber(value) return type(value)=="number" and value==value and math.abs(value)<math.huge end
    local function finiteVector(value)
        return typeof(value)=="Vector3" and finiteNumber(value.X) and finiteNumber(value.Y) and finiteNumber(value.Z)
    end
    local function finitePose(value)
        if typeof(value)~="CFrame" then return false end
        for _,component in ipairs({value:GetComponents()}) do if not finiteNumber(component) then return false end end
        return true
    end
    local stunStates = {Dead=true, Physics=true, PlatformStanding=true, Ragdoll=true, FallingDown=true}
    function api.IsStunned(rig, humanoid)
        if not rig or not humanoid then return true end
        for _, owner in ipairs({rig, humanoid}) do
            for _, name in ipairs({"Stunned", "IsStunned", "Stun", "Ragdolled", "KnockedDown"}) do
                local value = owner:GetAttribute(name)
                if value == true or type(value) == "number" and value > 0 then return true end
            end
        end
        return humanoid.Health <= 0 or humanoid.PlatformStand == true or stunStates[humanoid:GetState().Name] == true
    end
    function api.BeforePose(rig)
        rig=owner(rig)
        if state.Rig ~= rig then return end
        for joint, correction in pairs(state.Corrections) do
            -- Restore only our overlay; a newer module pose wins.
            if joint.Parent and joint.Transform == correction.Written then joint.Transform = correction.Base end
        end
        table.clear(state.Corrections)
    end
    function api.BaseTransform(joint)
        local correction=state.Corrections[joint]
        return correction and joint.Transform == correction.Written and correction.Base or joint.Transform
    end
    local function releaseTurn()
        if state.Humanoid and state.Humanoid.Parent and state.AutoRotate ~= nil then
            state.Humanoid.AutoRotate = state.AutoRotate
        end
        state.Humanoid, state.AutoRotate = nil, nil
    end
    local function bindRig(rig)
        if state.Rig ~= rig then
            api.BeforePose(state.Rig)
            releaseTurn()
            for _, c in ipairs(state.Connections) do c:Disconnect() end
            state.Rig, state.Dirty, state.Connections, state.Joints = rig, true, {}, {}
            state.Contacts,state.Rest,state.Blends,state.Direction={},{},{},Vector3.zero
            if rig then
                for _, event in ipairs({"DescendantAdded", "DescendantRemoving"}) do
                    table.insert(state.Connections, rig[event]:Connect(function(item)
                        if poseJoint(item) or item:IsA("BasePart") and item.Parent==rig then state.Dirty = true end
                    end))
                end
            end
        end
        if rig and state.Dirty then
            state.Joints = {}
            local live={}
            for _, joint in ipairs(rig:GetDescendants()) do
                local p0,p1
                if poseJoint(joint) then p0,p1=jointParts(joint) end
                if p0 and p1 and p0.Parent==rig and p1.Parent==rig then
                    table.insert(state.Joints, joint)
                    live[joint]=true
                    local rest=state.Rest[joint]
                    if not rest or rest.Part0~=p0 or rest.Part1~=p1 then
                        local c0,c1=jointFrames(joint)
                        state.Rest[joint]={Part0=p0,Part1=p1,C0=c0,C1=c1}
                    end
                end
            end
            for joint in pairs(state.Rest) do
                if not live[joint] then state.Rest[joint],state.Blends[joint]=nil,nil end
            end
            state.Dirty = false
        end
    end
    function api.BodyPoses(rig)
        bindRig(rig)
        local poses, incoming = {}, {}
        local root = rig and rig:FindFirstChild("HumanoidRootPart")
        if not root or not finitePose(root.CFrame) then return poses, incoming end
        poses[root] = root.CFrame
        for _ = 1, 16 do
            local changed = false
            for _, joint in ipairs(state.Joints) do
                local p0, p1 = jointParts(joint)
                if joint.Parent and joint.Enabled ~= false and p0 and p1 and p0 ~= p1 and p0.Parent == rig and p1.Parent == rig then
                    incoming[p1] = joint
                    local c0,c1=jointFrames(joint)
                    if poses[p0] and not poses[p1] and finitePose(c0) and finitePose(c1) and finitePose(joint.Transform) then
                        local pose=poses[p0] * c0 * joint.Transform * c1:Inverse()
                        if finitePose(pose) then poses[p1],changed=pose,true end
                    end
                end
            end
            if not changed then break end
        end
        return poses, incoming
    end
    local function rotationBetween(a, b)
        if not finiteVector(a) or not finiteVector(b) or a.Magnitude < 1e-6 or b.Magnitude < 1e-6 then return CFrame.identity end
        a, b = a.Unit, b.Unit
        local dot = math.clamp(a:Dot(b), -1, 1)
        local cross = a:Cross(b)
        if cross.Magnitude < 1e-6 then
            if dot > 0 then return CFrame.identity end
            cross = a:Cross(math.abs(a.Y) < .9 and Vector3.new(0,1,0) or Vector3.new(1,0,0))
        end
        return CFrame.fromAxisAngle(cross.Unit, math.acos(dot))
    end
    local function rotateAt(pose, origin, rotation, destination)
        return CFrame.new(destination or origin) * rotation * CFrame.new(-origin) * pose
    end
    local function writeTransform(joint,written)
        if not finitePose(written) then state.Blends[joint]=nil return false end
        local old=state.Corrections[joint]
        state.Corrections[joint]={Base=old and old.Base or joint.Transform,Written=written}
        joint.Transform=written
        return true
    end
    local function writeJoint(joint, parentPose, childPose, confidence, length, now)
        local base = joint.Transform
	local c0,c1=jointFrames(joint)
        if not finitePose(base) or not finitePose(parentPose) or not finitePose(childPose)
            or not finitePose(c0) or not finitePose(c1)
            or not finiteNumber(confidence) or not finiteNumber(length) or length<=0 or not finiteNumber(now) then
            state.Blends[joint]=nil return nil
        end
        if confidence<=0 then
            state.Blends[joint]=nil
            return parentPose * c0 * base * c1:Inverse()
        end
        local solved = c0:Inverse() * parentPose:ToObjectSpace(childPose) * c1
        -- Filter only the terrain offset. The animation's own snapping, timing,
        -- C0/C1 changes and Transform remain the baseline on every call.
        local delta=base:ToObjectSpace(solved)
        if not finitePose(delta) then state.Blends[joint]=nil return nil end
        local axis,angle=delta:ToAxisAngle()
        if not finiteVector(axis) or not finiteNumber(angle) then state.Blends[joint]=nil return nil end
        local limit=math.rad(saved.IKMaxTilt)
        local position=delta.Position
        if position.Magnitude>length*.2 then position=position.Unit*length*.2 end
        delta=CFrame.new(position)*CFrame.fromAxisAngle(axis,math.min(angle,limit))
        local prior=state.Blends[joint]
        if prior and (not finitePose(prior.Delta) or not finiteNumber(prior.At)) then prior=nil state.Blends[joint]=nil end
        local elapsed=prior and math.clamp(now-prior.At,0,.1) or state.Dt
        local filtered=(prior and prior.Delta or CFrame.identity):Lerp(delta,1-math.exp(-elapsed/saved.IKBlendTime))
        local written = base*CFrame.identity:Lerp(filtered,saved.IKStrength*confidence)
        if not finitePose(filtered) or not writeTransform(joint,written) then state.Blends[joint]=nil return nil end
        state.Blends[joint]={Delta=filtered,At=now}
        return parentPose * c0 * written * c1:Inverse()
    end
    local function restPose(joint,parentPose)
        local rest=state.Rest[joint]
        return parentPose*rest.C0*rest.C1:Inverse()
    end
    local function swingWeight(lift,length)
        local t=math.clamp((lift/length-.025)/.15,0,1)
        return 1-t*t*(3-2*t)
    end
    api.SolveTwoBone = function(hip, knee, endPoint, target, pole)
        if not finiteVector(hip) or not finiteVector(knee) or not finiteVector(endPoint)
            or not finiteVector(target) or not finiteVector(pole) then return nil end
        local l1, l2 = (knee-hip).Magnitude, (endPoint-knee).Magnitude
        local delta = target-hip
        if not finiteNumber(l1) or not finiteNumber(l2) or not finiteNumber(delta.Magnitude)
            or l1 < 1e-5 or l2 < 1e-5 or delta.Magnitude < 1e-5 then return nil end
        local direction = delta.Unit
        local distance = math.clamp(delta.Magnitude, math.abs(l1-l2)+1e-5, l1+l2-1e-5)
        local along = (l1*l1-l2*l2+distance*distance)/(2*distance)
        local bend = pole-direction*pole:Dot(direction)
        if bend.Magnitude < 1e-5 then bend = direction:Cross(Vector3.new(1,0,0)) end
        if bend.Magnitude < 1e-5 then bend = direction:Cross(Vector3.new(0,0,1)) end
        local solvedKnee,solvedEnd=hip+direction*along+bend.Unit*math.sqrt(math.max(0,l1*l1-along*along)), hip+direction*distance
        if finiteVector(solvedKnee) and finiteVector(solvedEnd) then return solvedKnee,solvedEnd end
    end
    -- Robert's uploaded R6IK models an imaginary upper limb, then displays
    -- the lower segment. This analytic adaptation writes Transform, not C0.
    function api.SolveR6Virtual(pose,hip,bottom,target,pole)
        if not finitePose(pose) or not finiteVector(hip) or not finiteVector(bottom) or not finiteVector(target) then return pose end
        local length=(bottom-hip).Magnitude
        if length<1e-5 then return pose end
        local knee=hip+(bottom-hip)*.5
        local newKnee,newBottom=api.SolveTwoBone(hip,knee,bottom,target,pole)
        if not newKnee then return pose end
        return rotateAt(pose,bottom,rotationBetween(hip-bottom,newKnee-newBottom),newBottom)
    end
    local function selected(name)
        local mask=ctx.SaveData.AnimLibOptions and ctx.SaveData.AnimLibOptions.DisabledAnimationParts
        if not mask then return true end
        local canonical
        if name:find("Torso",1,true) then canonical="Torso"
        elseif name:find("Arm",1,true) or name:find("Hand",1,true) then canonical=name:sub(1,4)=="Left" and "Left Arm" or "Right Arm"
        elseif name:find("Leg",1,true) or name:find("Foot",1,true) then canonical=name:sub(1,4)=="Left" and "Left Leg" or "Right Leg" end
        return mask[name]~=true and (not canonical or mask[canonical]~=true)
    end
    local function applyDirection(rig,humanoid)
        if not saved.DirectionalWalking then return end
        local name=humanoid:GetState().Name
        if name~="Running" and name~="RunningNoPhysics" and name~="Landed" then return end
        local poses,incoming=api.BodyPoses(rig)
        local root=rig:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local direction=state.Direction
        local torso=rig:FindFirstChild("UpperTorso") or rig:FindFirstChild("Torso")
        local motor=torso and incoming[torso]
        local parent=motor and jointParts(motor)
        if motor and selected(torso.Name) and poses[torso] and poses[parent] then
            local c0,c1=jointFrames(motor)
            local pivot=(poses[torso]*c1).Position
            local tilt=root.CFrame.Rotation*CFrame.Angles(math.rad(direction.Z*5),0,math.rad(-direction.X*saved.LeanAngle))*root.CFrame.Rotation:Inverse()
            local target=rotateAt(poses[torso],pivot,tilt)
            writeTransform(motor,c0:Inverse()*poses[parent]:ToObjectSpace(target)*c1)
        end
        poses,incoming=api.BodyPoses(rig)
        -- Positive Y yaw turns the visible forward vector toward the left.
        -- Keep the lateral sign while backing up, including diagonal steps.
        local angle=math.rad(-direction.X*saved.LegAngle)
        for _,side in ipairs({"Left","Right"}) do
            local limb=rig:FindFirstChild(side.."UpperLeg") or rig:FindFirstChild(side.." Leg")
            local m=limb and incoming[limb]
            local parent=m and jointParts(m)
            if m and selected(limb.Name) and poses[limb] and poses[parent] then
                local c0,c1=jointFrames(m)
                local pivot=(poses[limb]*c1).Position
                local target=rotateAt(poses[limb],pivot,CFrame.fromAxisAngle(root.CFrame.UpVector,angle))
                writeTransform(m,c0:Inverse()*poses[parent]:ToObjectSpace(target)*c1)
            end
        end
    end
    local function probe(rig,side,pose,part,hip)
        local root=rig:FindFirstChild("HumanoidRootPart")
        local bottom=(pose*CFrame.new(0,-part.Size.Y/2,0)).Position
        if bottom.Y>=hip.Y then state.Contacts[side]=nil return nil end
        local now=clock()
        local prior=state.Contacts[side]
        if prior and prior.HitPart and not prior.HitPart.Parent then prior=nil state.Contacts[side]=nil end
        local reach=math.max((bottom-hip).Magnitude,part.Size.Y)+.1
        if prior and now-prior.At<1/30 and (bottom-prior.Bottom).Magnitude<.12 and math.abs(hip.Y-prior.HipY)<.12 then
            if prior.HitPart and prior.HitPart.Parent and prior.Local then
                local moved=prior.HitPart.CFrame:PointToWorldSpace(prior.Local)
                local ground=prior.HitPart.CFrame:PointToWorldSpace(prior.GroundLocal or prior.Local)
                return {Position=Vector3.new(bottom.X,moved.Y,bottom.Z),GroundHeight=ground.Y,Normal=prior.Normal,Supported=true}
            end
            return prior.Hit
        end
        local radius=math.min(part.Size.X,part.Size.Z)*.22
        local hits={}
        for _,offset in ipairs({Vector3.zero,Vector3.new(radius,0,0),Vector3.new(-radius,0,0),Vector3.new(0,0,radius),Vector3.new(0,0,-radius)}) do
            local origin=Vector3.new(bottom.X,hip.Y-.01,bottom.Z)+offset
            local hit=ctx.World:Raycast(origin,Vector3.new(0,-reach,0),state.Raycast)
            if hit and finiteVector(hit.Position) and finiteVector(hit.Normal)
                and hit.Position.Y<hip.Y-.01 and hit.Normal.Y>=.5 then table.insert(hits,hit)
            elseif offset==Vector3.zero then state.Contacts[side]=nil return nil end
        end
        local center=hits[1]
        if not center then state.Contacts[side]=nil return nil end
        local support=0
        for _,hit in ipairs(hits) do if math.abs(hit.Position.Y-center.Position.Y)<=math.max(.05,part.Size.Y*.05) then support+=1 end end
        if support<4 then state.Contacts[side]=nil return nil end
        local position,normal=center.Position,center.Normal
        if prior then
            local elapsed=math.min(now-prior.At,.1)
            local alpha=1-math.exp(-saved.ContactResponse*math.max(elapsed,0))
            if math.abs(position.Y-prior.Hit.Position.Y)<part.Size.Y then
                position=Vector3.new(position.X,prior.Hit.Position.Y+(position.Y-prior.Hit.Position.Y)*alpha,position.Z)
                normal=prior.Normal:Lerp(normal,alpha).Unit
            end
        end
        local hit={Position=position,GroundHeight=center.Position.Y,Normal=normal,Supported=true}
        local partHit=center.Instance
        state.Contacts[side]={At=now,Bottom=bottom,HipY=hip.Y,Hit=hit,Normal=normal,
            HitPart=partHit and partHit:IsA("BasePart") and partHit or nil,
            GroundLocal=partHit and partHit:IsA("BasePart") and partHit.CFrame:PointToObjectSpace(center.Position) or nil,
            Local=partHit and partHit:IsA("BasePart") and partHit.CFrame:PointToObjectSpace(position) or nil}
        return hit
    end
    function api.ApplyIK(rig)
        local source=rig
        rig=owner(rig)
        bindRig(rig)
        api.BeforePose(rig)
        if adapter then adapter.Apply(source) end
        if not rig or not rig.Parent or ctx.Reanimate.Character~=rig then return end
        local humanoid=rig:FindFirstChildOfClass("Humanoid")
        if api.IsStunned(rig,humanoid) or humanoid.Sit then state.Contacts,state.Blends={},{} return end
        applyDirection(rig,humanoid)
        if not saved.InverseKinematics or saved.IKStrength<=0 then state.Blends={} return end
        local name=humanoid:GetState().Name
        if name=="Jumping" or name=="Freefall" or name=="Climbing" or name=="Swimming" then state.Contacts,state.Blends={},{} return end
        local poses,incoming=api.BodyPoses(rig)
        if not state.Raycast then
            state.Raycast=RaycastParams.new() state.Raycast.FilterType=Enum.RaycastFilterType.Exclude
            state.Raycast.IgnoreWater=true state.Raycast.RespectCanCollide=true
        end
        local exclusions={rig}
        if ctx.Player and ctx.Player.Character then table.insert(exclusions,ctx.Player.Character) end
        state.Raycast.FilterDescendantsInstances=exclusions
        local contacts={}
        for _,side in ipairs({"Left","Right"}) do
            local limb=rig:FindFirstChild(side.."UpperLeg") or rig:FindFirstChild(side.." Leg")
            local m=limb and incoming[limb]
            local part=rig:FindFirstChild(side.."Foot") or limb
            local lower=rig:FindFirstChild(side.."LowerLeg")
            if m and selected(limb.Name) and selected(part.Name) and (not lower or selected(lower.Name)) and poses[limb] and poses[part] then
                local _,c1=jointFrames(m)
                contacts[side]=probe(rig,side,poses[part],part,(poses[limb]*c1).Position)
            end
        end
        -- Leave both authored legs alone on level ground. The overlay is for
        -- terrain correction, not a replacement walking/dance cycle.
        local level=contacts.Left and contacts.Right and math.abs(contacts.Left.GroundHeight-contacts.Right.GroundHeight)<.05
            and contacts.Left.Normal.Y>.995 and contacts.Right.Normal.Y>.995
        local now=clock()
        for _, side in ipairs({"Left", "Right"}) do
            local upper = rig:FindFirstChild(side .. "UpperLeg") or rig:FindFirstChild(side .. " Leg")
            local lower, foot = rig:FindFirstChild(side .. "LowerLeg"), rig:FindFirstChild(side .. "Foot")
            local hipJoint = upper and incoming[upper]
            local upperPose = upper and poses[upper]
            if not hipJoint or not upperPose then continue end
            local parentPose = poses[jointParts(hipJoint)]
            local _,hipC1=jointFrames(hipJoint)
            local hip = (upperPose * hipC1).Position
            local endPart = foot or upper
            local endPose = poses[endPart]
            if not endPose then continue end
            local bottom = (endPose * CFrame.new(0,-endPart.Size.Y/2,0)).Position
            local hit=contacts[side]
            local kneeJoint, ankleJoint = lower and incoming[lower], foot and incoming[foot]
            if not hit or bottom.Y>=hip.Y then
                for _,joint in ipairs({hipJoint,kneeJoint,ankleJoint}) do state.Blends[joint]=nil end
                continue
            end
            local resting=restPose(hipJoint,parentPose)
            local restingHip=(resting*state.Rest[hipJoint].C1).Position
            if kneeJoint and ankleJoint then
                resting=restPose(ankleJoint,restPose(kneeJoint,resting))
            end
            local restBottom=(resting*CFrame.new(0,-endPart.Size.Y/2,0)).Position
            local length=math.max((restBottom-restingHip).Magnitude,.01)
            -- Lift is authored clearance, measured against the neutral leg
            -- below the current torso. Preserve it instead of planting a kick.
            local lift=math.max(0,bottom.Y-restBottom.Y)
            local confidence=swingWeight(lift,length)
            if level then
                writeJoint(hipJoint,parentPose,upperPose,confidence,length,now)
                if kneeJoint and ankleJoint then
                    writeJoint(kneeJoint,upperPose,poses[lower],confidence,length,now)
                    writeJoint(ankleJoint,poses[lower],endPose,confidence,length,now)
                end
                continue
            end
            local height=bottom.Y+math.clamp(hit.Position.Y+lift-bottom.Y,-length*.2,length*.2)
            local target=Vector3.new(bottom.X,math.min(height,hip.Y-.01),bottom.Z)
            if kneeJoint and ankleJoint and jointParts(kneeJoint) == upper and jointParts(ankleJoint) == lower and poses[lower] then
                local _,kneeC1=jointFrames(kneeJoint)
                local _,ankleC1=jointFrames(ankleJoint)
                local footRotation = rotationBetween(endPose.UpVector, hit.Normal) * endPose.Rotation
                local footPose = CFrame.new(target + footRotation.UpVector*endPart.Size.Y/2) * footRotation
                local ankle = (footPose*ankleC1).Position
                if ankle.Y >= hip.Y then continue end
                local knee = (poses[lower]*kneeC1).Position
                local oldAnkle = (endPose*ankleC1).Position
                local axis=oldAnkle-hip
                if not finiteVector(axis) or axis.Magnitude<1e-5 then
                    -- Fully folded/custom legs have no bend axis. Keep their
                    -- authored pose and discard terrain history, not NaN joints.
                    state.Blends[hipJoint],state.Blends[kneeJoint],state.Blends[ankleJoint]=nil,nil,nil
                    continue
                end
                local legAxis=axis.Unit
                local pole = knee-hip-legAxis*(knee-hip):Dot(legAxis)
                -- A straight leg has no authored bend plane. Use its facing
                -- after directional rotation, rather than the torso's facing.
                if pole.Magnitude < .001 then pole = upperPose.LookVector
                elseif pole:Dot(upperPose.LookVector)<0 then pole=-pole end
                local newKnee, newAnkle = api.SolveTwoBone(hip,knee,oldAnkle,ankle,pole)
                if not newKnee then continue end
                local upperTarget = rotateAt(upperPose,hip,rotationBetween(knee-hip,newKnee-hip))
                local lowerTarget = rotateAt(poses[lower],knee,rotationBetween(oldAnkle-knee,newAnkle-newKnee),newKnee)
                writeJoint(hipJoint,parentPose,upperTarget,confidence,length,now)
                writeJoint(kneeJoint,upperTarget,lowerTarget,confidence,length,now)
                footPose = footPose + (newAnkle-ankle)
                writeJoint(ankleJoint,lowerTarget,footPose,confidence,length,now)
            else
                -- Both R6 methods preserve visible leg size. Virtual knee can
                -- translate its motor; rigid leg keeps the hip pivot fixed.
                local corrected = saved.R6IKMethod=="Virtual knee"
                    and api.SolveR6Virtual(upperPose,hip,bottom,target,upperPose.LookVector)
                    or rotateAt(upperPose,hip,rotationBetween(bottom-hip,target-hip))
                writeJoint(hipJoint,parentPose,corrected,confidence,length,now)
            end
        end
    end
    function api.Prepare(dt)
        local rig = ctx.Reanimate.Character
        bindRig(rig)
        -- Preparing input must not strip the visible overlay. Animation writers
        -- and ApplyIK restore it immediately before replacing the pose; removing
        -- it in PreAnimation exposed an uncorrected leg to early physics readers.
        state.Dt=number(dt,0,0,.1)
        local root=rig and rig:FindFirstChild("HumanoidRootPart")
        local h=rig and rig:FindFirstChildOfClass("Humanoid")
        local direction=Vector3.zero
        if root and h and saved.DirectionalWalking and not api.IsStunned(rig,h) and not h.Sit then
            local name=h:GetState().Name
            if name=="Running" or name=="RunningNoPhysics" or name=="Landed" then direction=root.CFrame:VectorToObjectSpace(h.MoveDirection) end
        end
        if not finiteVector(direction) then direction=Vector3.zero end
        if not finiteVector(state.Direction) then state.Direction=Vector3.zero end
        state.Direction=state.Direction:Lerp(direction,1-math.exp(-saved.TurnResponse*state.Dt))
        local humanoid = rig and rig:FindFirstChildOfClass("Humanoid")
        local root = rig and rig:FindFirstChild("HumanoidRootPart")
        if not rig or not rig.Parent or not humanoid or not root or not saved.DirectionalWalking or not saved.SmoothFacing or api.IsStunned(rig,humanoid)
            or humanoid.Sit or humanoid:GetState().Name == "Climbing" or humanoid:GetState().Name == "Swimming" then releaseTurn() return end
        if state.Humanoid ~= humanoid then
            releaseTurn()
            -- Respect a moveset which already owns root rotation.
            if not humanoid.AutoRotate then return end
            state.Humanoid, state.AutoRotate = humanoid, humanoid.AutoRotate
        end
        humanoid.AutoRotate = false
        local direction = humanoid.MoveDirection
        local camera = ctx.Reanimate.Camera
        if ctx.Reanimate.Shiftlocked or camera and camera.IsMouseLocked and camera:IsMouseLocked() then
            direction = camera and camera.CFrame.LookVector or direction
        end
        direction = Vector3.new(direction.X,0,direction.Z)
        if not finiteVector(direction) or not finitePose(root.CFrame) or direction.Magnitude < .001 then return end
        local target = CFrame.lookAt(root.Position,root.Position+direction.Unit,Vector3.new(0,1,0))
        local alpha = 1-math.exp(-saved.TurnResponse*number(dt,0,0,.1))
        root.CFrame = CFrame.new(root.Position) * root.CFrame.Rotation:Lerp(target.Rotation,alpha)
    end

    function api.CreateFrameCache(ease)
        local cache = {Entries={}, Count=0, PoseCount=0, Builds=0, Reviews=0, Hits=0}
        local function remove(track)
            local entry = cache.Entries[track]
            if entry then cache.PoseCount -= entry.PoseCount or 0 cache.Count -= 1 cache.Entries[track] = nil end
        end
        function cache.Clear(track)
            if track then remove(track) else table.clear(cache.Entries) cache.Count,cache.PoseCount=0,0 end
        end
        local function oldest(except)
            local key, time
            for track, entry in pairs(cache.Entries) do
                if track ~= except and (not time or entry.LastUsed < time) then key,time=track,entry.LastUsed end
            end
            return key
        end
        local function changed(track, entry)
            if track.Time ~= entry.Duration or #track.Keyframes ~= #entry.Snapshot then return true end
            for i, frame in ipairs(track.Keyframes) do
                local before = entry.Snapshot[i]
                if frame.Time ~= before.Time or #frame.Poses ~= #before.Poses then return true end
                for j, pose in ipairs(frame.Poses) do
                    local old = before.Poses[j]
                    if pose.Name ~= old.Name or pose.CFrame ~= old.CFrame or pose.Weight ~= old.Weight
                        or pose.EasingStyle ~= old.EasingStyle or pose.EasingDirection ~= old.EasingDirection then return true end
                end
            end
            return false
        end
        local function build(track, now)
            while cache.Count >= 8 do remove(oldest()) end
            local entry = {Duration=track.Time, Snapshot={}, Channels={}, Frames={}, PoseCount=0, LastUsed=now, Reviewed=now, Rate=saved.FrameRate, Scope=saved.TrackScope}
            cache.Entries[track],cache.Count=entry,cache.Count+1
            local total, names = 0, 0
            for i, frame in ipairs(track.Keyframes) do
                local snapshot = {Time=frame.Time, Poses={}}
                entry.Snapshot[i] = snapshot
                for j, pose in ipairs(frame.Poses) do
                    total += 1
                    if total > 8192 then entry.Skip=true return entry end
                    local copy = {Time=frame.Time,Name=pose.Name,CFrame=pose.CFrame,Weight=pose.Weight,EasingStyle=pose.EasingStyle,EasingDirection=pose.EasingDirection}
                    snapshot.Poses[j] = copy
                    if pose.Weight > 0 then
                        if not entry.Channels[pose.Name] then entry.Channels[pose.Name] = {} names += 1 end
                        if names > 64 then entry.Skip=true return entry end
                        table.insert(entry.Channels[pose.Name],copy)
                    end
                end
            end
            entry.Names = names
            for _, channel in pairs(entry.Channels) do table.sort(channel,function(a,b) return a.Time < b.Time end) end
            cache.Builds += 1
            return entry
        end
        local function sampleChannel(channel, t)
            local lo,hi=1,#channel
            while lo < hi do local mid=math.ceil((lo+hi)/2) if channel[mid].Time <= t then lo=mid else hi=mid-1 end end
            local a,b=channel[lo],channel[lo+1]
            if t < a.Time or not b then return a.CFrame end
            local alpha=math.clamp((t-a.Time)/math.max(b.Time-a.Time,1e-8),0,1)
            local style=a.EasingStyle or "Linear"
            if style ~= "Linear" and style ~= "Constant" then return a.CFrame:Lerp(b.CFrame,ease(alpha,style,a.EasingDirection)) end
            local previous,nextPose=channel[math.max(1,lo-1)],channel[math.min(#channel,lo+2)]
            local span=b.Time-a.Time
            local v0=(b.CFrame.Position-previous.CFrame.Position)*(span/math.max(b.Time-previous.Time,1e-8))
            local v1=(nextPose.CFrame.Position-a.CFrame.Position)*(span/math.max(nextPose.Time-a.Time,1e-8))
            local t2,t3=alpha*alpha,alpha*alpha*alpha
            local p=a.CFrame.Position*(2*t3-3*t2+1)+v0*(t3-2*t2+alpha)+b.CFrame.Position*(-2*t3+3*t2)+v1*(t3-t2)
            local x,y=a.CFrame.Position,b.CFrame.Position
            p=Vector3.new(math.clamp(p.X,math.min(x.X,y.X),math.max(x.X,y.X)),math.clamp(p.Y,math.min(x.Y,y.Y),math.max(x.Y,y.Y)),math.clamp(p.Z,math.min(x.Z,y.Z),math.max(x.Z,y.Z)))
            return CFrame.new(p)*a.CFrame.Rotation:Lerp(b.CFrame.Rotation,t2*(3-2*alpha))
        end
        function cache.Sample(track,t)
            if not saved.FrameSmoothing or track.FrameSmoothing == false then return nil end
            if type(track.Time) ~= "number" or track.Time ~= track.Time or track.Time <= 0 or track.Time == math.huge or #track.Keyframes < 2 then return nil end
            if track.FrameSmoothing ~= true and saved.TrackScope ~= "All AnimLib tracks" and (#track.Keyframes-1)/track.Time >= 30 then return nil end
            local now=clock()
            local entry=cache.Entries[track]
            if entry and (entry.Rate ~= saved.FrameRate or entry.Scope ~= saved.TrackScope) then remove(track) entry=nil end
            if entry and now-entry.Reviewed >= saved.ReviewTime then
                cache.Reviews += 1
                if entry.Skip or changed(track,entry) then remove(track) entry=nil else entry.Reviewed=now end
            end
            if not entry then entry=build(track,now) end
            entry.LastUsed=now
            if entry.Skip then return nil end
            local function frame(index)
                local slot=index%128
                local cached=entry.Frames[slot]
                if cached and cached.Index == index then cache.Hits += 1 return cached.Poses end
                if cached then cache.PoseCount -= entry.Names entry.PoseCount -= entry.Names end
                while cache.PoseCount+entry.Names > 8192 and cache.Count > 1 do remove(oldest(track)) end
                local poses={}
                for name, channel in pairs(entry.Channels) do poses[name]=sampleChannel(channel,math.min(index/entry.Rate,entry.Duration)) end
                entry.Frames[slot]={Index=index,Poses=poses}
                cache.PoseCount += entry.Names entry.PoseCount += entry.Names
                return poses
            end
            t=number(t,0,0,entry.Duration)
            local index=math.floor(t*entry.Rate)
            local a,b=frame(index),frame(index+1)
            local start,finish=index/entry.Rate,math.min((index+1)/entry.Rate,entry.Duration)
            local alpha=finish > start and (t-start)/(finish-start) or 0
            local poses={}
            for name, pose in pairs(a) do poses[name]=pose:Lerp(b[name],math.clamp(alpha,0,1)) end
            return poses
        end
        api.FrameCache=cache
        return cache
    end
    function api.ConfigureUI(UI,parent,save)
        local function switch(label,key)
            UI.CreateSwitch(parent,label,saved[key]).Changed:Connect(function(value)
                saved[key]=value
                if key == "InverseKinematics" and not value then api.BeforePose(state.Rig) end
                if (key == "DirectionalWalking" or key == "SmoothFacing") and not value then releaseTurn() end
                if key == "FrameSmoothing" and api.FrameCache then api.FrameCache.Clear() end
                save()
            end)
        end
        switch("Inverse Kinematics", "InverseKinematics")
        switch("Directional Walking", "DirectionalWalking")
        switch("Smooth Character Facing", "SmoothFacing")
        switch("Frame Smoothing (AnimLib)", "FrameSmoothing")
        local function slider(label,key,minimum,maximum,precision)
            UI.CreateSlider(parent,label,saved[key],minimum,maximum,precision).Changed:Connect(function(value) saved[key]=number(value,saved[key],minimum,maximum) save() end)
        end
        local methods={"Virtual knee","Rigid leg"}
        UI.CreateDropdown(parent,"R6 IK Method",methods,table.find(methods,saved.R6IKMethod)).Changed:Connect(function(i)
            saved.R6IKMethod=methods[i] or methods[1] api.BeforePose(state.Rig) state.Blends={} save()
        end)
        slider("Ground Contact Response","ContactResponse",1,30,.5)
        slider("IK Blend Time (seconds)","IKBlendTime",.03,.4,.01)
        slider("Maximum IK Tilt (degrees)","IKMaxTilt",5,60,1)
        slider("Directional Lean (degrees)","LeanAngle",0,35,1)
        slider("Directional Leg Angle (degrees)","LegAngle",0,60,1)
        slider("IK Strength","IKStrength",0,1,.05)
        slider("Turn Response","TurnResponse",1,30,.5)
        slider("Smoothing Frames / Second","FrameRate",15,120,0)
        slider("Smoothing Review Time (seconds)","ReviewTime",1,120,0)
        local scopes={"Low frame rate tracks","All AnimLib tracks"}
        UI.CreateDropdown(parent,"Smooth Tracks",scopes,table.find(scopes,saved.TrackScope) or 1).Changed:Connect(function(value) saved.TrackScope=scopes[value] or scopes[1] if api.FrameCache then api.FrameCache.Clear() end save() end)
    end
    function api.Destroy()
        api.BeforePose(state.Rig)
        releaseTurn()
        for _, connection in ipairs(state.Connections) do connection:Disconnect() end
        if api.FrameCache then api.FrameCache.Clear() end
        state.Rest,state.Contacts,state.Blends={},{},{}
        state.Rig=nil
    end
    return api
end
