	["BlaaBlaaReanim/System/runtime/steve110/main/community_diagnostics.lua"] = [=[
-- Addon errors are inspectable, bounded and quiet unless explicitly enabled.
-- This is not a global warn hook: core, ownership and filesystem warnings stay visible.
return function(deps)
    local records, keys = {}, {}
    local api = {}
    local function clipped(value, maximum)
        local text = tostring(value or "")
        if #text <= maximum then return text end
        local stop = maximum
        while stop > 0 and text:byte(stop + 1) >= 128 and text:byte(stop + 1) < 192 do stop -= 1 end
        return text:sub(1, stop) .. "…"
    end
    function api.Enabled() return deps.Settings.CommunityDiagnosticsEnabled == true end
    function api.Report(kind, name, source, reason, notification)
        kind, name, source, reason = clipped(kind, 64), clipped(name, 256), clipped(source, 256), clipped(reason, 2048)
        local key = kind .. "\0" .. name .. "\0" .. source
        local entry = keys[key]
        if entry and entry.Reason == reason then entry.Count += 1; return entry end
        if entry then
            entry.Reason, entry.Count = reason, entry.Count + 1
        else
            if #records == 24 then keys[table.remove(records, 1).Key] = nil end
            entry = {Key = key, Kind = kind, Name = name, Source = source, Reason = reason, Count = 1}
            table.insert(records, entry)
            keys[key] = entry
        end
        if api.Enabled() then
            deps.Warn(("Uhhhhhh %s [%s] (%s): %s"):format(kind, name, source, reason))
            if notification and deps.Notify then deps.Notify(notification) end
        end
        return entry
    end
    function api.Describe()
        if #records == 0 then return "No addon errors recorded this session." end
        local rows = {"Addon errors (most recent 24; quiet by default):"}
        for i = #records, 1, -1 do
            local entry = records[i]
            table.insert(rows, ("\n[%s] %s\nSource: %s\n%s\nOccurrences: %d"):format(
                entry.Kind, entry.Name, entry.Source, entry.Reason, entry.Count))
        end
        return table.concat(rows, "\n")
    end
    function api.Clear() table.clear(records); table.clear(keys) end
    return api
end
]=],
	["BlaaBlaaReanim/System/runtime/steve110/main/controller_reset.lua"] = [=[
-- Refresh an externally bound controller IN PLACE. Gelatek's follower closures
-- retain its body parts; destroying/replacing that model would retire the run.
local Reset = {}
local partProperties = {"Size", "Color", "Material", "Transparency", "LocalTransparencyModifier",
    "Reflectance", "Anchored", "CanCollide", "CanTouch", "CanQuery", "Massless", "RootPriority"}
local humanoidProperties = {"WalkSpeed", "JumpPower", "JumpHeight", "UseJumpPower", "HipHeight",
    "AutoRotate", "PlatformStand", "RequiresNeck", "BreakJointsOnDeath"}
local function properties(instance, names)
    local values = {}
    for _, name in ipairs(names) do values[name] = instance[name] end
    return values
end
local function restoreProperties(instance, values)
    for name, value in pairs(values) do instance[name] = value end
end
local function isExcluded(instance, excluded)
    return excluded ~= nil and (instance == excluded or instance:IsDescendantOf(excluded))
end
local function scaleController(rig, scale, excluded)
    if not excluded or not excluded:IsDescendantOf(rig) then rig:ScaleTo(scale) return end
    -- ScaleTo walks descendants too. Keep the real shell in the world while
    -- scaling the controller, and restore its parent even if scaling fails.
    local parent = excluded.Parent
    excluded.Parent = rig.Parent
    local ok, reason = pcall(rig.ScaleTo, rig, scale)
    excluded.Parent = parent
    if not ok then error(reason, 0) end
end
function Reset.Capture(rig, excluded)
    local root = assert(rig:FindFirstChild("HumanoidRootPart"), "controller has no root")
    local snapshot = {Rig = rig, Root = root, Excluded = excluded, Scale = rig:GetScale(), Instances = {}, Parents = {}, Parts = {}, Joints = {}}
    for _, instance in ipairs(rig:GetDescendants()) do
        if isExcluded(instance, excluded) then continue end
        snapshot.Instances[instance] = true
        snapshot.Parents[instance] = instance.Parent
        if instance:IsA("BasePart") then
            table.insert(snapshot.Parts, {Instance = instance, Values = properties(instance, partProperties),
                PhysicalProperties = instance.CustomPhysicalProperties,
                Offset = root.CFrame:ToObjectSpace(instance.CFrame)})
        elseif instance:IsA("JointInstance") then
            table.insert(snapshot.Joints, {Instance = instance, Parent = instance.Parent, Name = instance.Name,
                Class = instance.ClassName, Part0 = instance.Part0, Part1 = instance.Part1,
                C0 = instance.C0, C1 = instance.C1, Enabled = instance.Enabled,
                MaxVelocity = instance:IsA("Motor6D") and instance.MaxVelocity or nil,
                Attributes = instance:GetAttributes()})
	elseif instance.ClassName=="AnimationConstraint" then
            table.insert(snapshot.Joints, {Instance=instance, Parent=instance.Parent, Name=instance.Name,
                Class=instance.ClassName, Attachment0=instance.Attachment0, Attachment1=instance.Attachment1,
                Enabled=instance.Enabled, IsKinematic=instance.IsKinematic, Attributes=instance:GetAttributes()})
        elseif instance:IsA("Humanoid") then
            snapshot.Humanoid, snapshot.HumanoidValues = instance, properties(instance, humanoidProperties)
        end
    end
    return snapshot
end
function Reset.Restore(snapshot, scale)
    local rig, root = snapshot.Rig, snapshot.Root
    assert(rig.Parent and root.Parent, "bound controller/root no longer exists")
    -- Rescue baseline objects moved into a moveset-created folder before that
    -- folder is removed. Never destroy a bound limb as a cleanup side effect.
    for instance, parent in pairs(snapshot.Parents) do
        if instance.Parent and instance.Parent ~= parent then instance.Parent = parent end
    end
    for _, record in ipairs(snapshot.Parts) do
        assert(record.Instance:IsDescendantOf(rig), "a moveset destroyed a bound controller part; reanimate again")
    end
    assert(snapshot.Humanoid and snapshot.Humanoid:IsDescendantOf(rig),
        "a moveset destroyed the bound controller Humanoid; reanimate again")
    local rootCFrame = root.CFrame
    scaleController(rig, snapshot.Scale, snapshot.Excluded)
    -- Remove leftover moveset-created constraints/effects without touching the
    -- original controller, its proxy accessories, or physical character shell.
    for _, instance in ipairs(rig:GetDescendants()) do
        if not isExcluded(instance, snapshot.Excluded) and not snapshot.Instances[instance] then instance:Destroy() end
    end
    for _, record in ipairs(snapshot.Parts) do
        local part = record.Instance
        restoreProperties(part, record.Values)
        part.CustomPhysicalProperties = record.PhysicalProperties
        part.CFrame = rootCFrame * record.Offset
        part.AssemblyLinearVelocity, part.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
    end
    for _, record in ipairs(snapshot.Joints) do
        local joint = record.Instance
        if not joint:IsDescendantOf(rig) then
            joint = Instance.new(record.Class)
            record.Instance = joint
            snapshot.Instances[joint] = true
        end
        joint.Name,joint.Enabled=record.Name,record.Enabled
        if record.Class=="AnimationConstraint" then
            -- The compatibility Part0/C0 aliases are read-only. Restore the
            -- original attachment references, never rewrite rig attachments.
            joint.Attachment0,joint.Attachment1=record.Attachment0,record.Attachment1
            joint.Transform,joint.IsKinematic=CFrame.identity,record.IsKinematic
        else
            joint.Part0,joint.Part1=record.Part0,record.Part1
            joint.C0,joint.C1=record.C0,record.C1
        end
        for name in pairs(joint:GetAttributes()) do joint:SetAttribute(name, nil) end
        for name, value in pairs(record.Attributes) do joint:SetAttribute(name, value) end
        if joint:IsA("Motor6D") then
            joint.Transform, joint.DesiredAngle, joint.MaxVelocity = CFrame.identity, 0, record.MaxVelocity
        end
        joint.Parent = record.Parent
    end
    if snapshot.Humanoid and snapshot.Humanoid.Parent then
        restoreProperties(snapshot.Humanoid, snapshot.HumanoidValues)
        snapshot.Humanoid.Sit = false
    end
    scaleController(rig, tonumber(scale) or snapshot.Scale, snapshot.Excluded)
    return rig
end
return Reset
]=],
	["BlaaBlaaReanim/System/runtime/steve110/main/controller_settings.lua"] = [=[
-- Shared character settings for the external Gelatek controller.
return function(context)
    local rig, Reanimate, RunService = context.Rig, context.Reanimate, context.RunService
    local humanoid = rig:FindFirstChildOfClass("Humanoid")
    local root = rig:FindFirstChild("HumanoidRootPart")
    if not humanoid or not root then return function() end end
    local force = Instance.new("BodyForce")
    force.Name, force.Force, force.Parent = "_UhhhhhhScaledGravity", Vector3.zero, root
    local connections, seatWeld, lastSeatExit, stopped = {}, nil, -math.huge, false
    local function releaseSeat()
        if seatWeld then seatWeld:Destroy() seatWeld = nil end
        rig:SetAttribute("_Uhhhhhh_SeatWeldActive", nil)
        lastSeatExit = os.clock()
    end
    local function preserveSeat()
        if not seatWeld or not seatWeld.Parent or not seatWeld.Part0 or not seatWeld.Part0.Parent then releaseSeat() return false end
        if not Reanimate.SeatSit or humanoid.Jump then humanoid.Sit = false releaseSeat() return false end
        if Reanimate.KeepSeatSitState then
            humanoid.Sit = true
            if humanoid:GetState() ~= Enum.HumanoidStateType.Seated then humanoid:ChangeState(Enum.HumanoidStateType.Seated) end
        end
        return true
    end
    table.insert(connections, humanoid.Touched:Connect(function(part)
        if stopped or not part or not part.Parent then return end
        if part:IsA("Seat") and Reanimate.SeatSit and not seatWeld and not humanoid.Sit and os.clock() - lastSeatExit > 2 then
            seatWeld = Instance.new("Weld")
            seatWeld.Name, seatWeld.Part0, seatWeld.Part1 = "_UhhhhhhSeat", part, root
            local scale = rig:GetScale()
            seatWeld.C0, seatWeld.C1 = CFrame.new(0, part.Size.Y / 2, 0), CFrame.new(0, -1.5 * scale, 0)
            seatWeld.Parent = root
            humanoid.Sit = true
            rig:SetAttribute("_Uhhhhhh_SeatWeldActive", true)
            preserveSeat()
        elseif part.Name == "Handle" and part.Parent:IsA("Tool") and Reanimate.ToolGrab then
            local tool, container = part.Parent, part.Parent.Parent
            if container and not container:FindFirstChildOfClass("Humanoid") then humanoid:EquipTool(tool) end
        end
    end))
    table.insert(connections, humanoid.Seated:Connect(function(active)
        if not active and seatWeld then
            if Reanimate.SeatSit and Reanimate.KeepSeatSitState and not humanoid.Jump then
                task.defer(function() if not stopped then preserveSeat() end end)
            else releaseSeat() end
        end
    end))
    table.insert(connections, RunService.PreSimulation:Connect(function(dt)
        if stopped or not rig.Parent or not root.Parent then return end
        local state = humanoid:GetState()
        local name = state.Name
        local scale = tonumber(Reanimate.CharacterScale) or 1
        local amount = 0
        if name == "Swimming" then amount = workspace.Gravity * .5 end
        if Reanimate.ScaleGravity and scale ~= 1 and not root:IsGrounded()
            and (name == "Freefall" or name == "Jumping" or name == "Physics" or name == "Ragdoll"
                or name == "PlatformStanding" or name == "FallingDown" or name == "Flying") then
            amount -= workspace.Gravity * (scale - 1)
        end
        force.Force = Vector3.new(0, amount * root.AssemblyMass, 0)
        if seatWeld then preserveSeat() end
        if not Reanimate.CameraFocusManaged and not (Reanimate.Camera and Reanimate.Camera.Scriptable) then
            local offset = Vector3.new(0, 1.5 * (scale - 1), 0)
            local head = rig:FindFirstChild("Head")
            if Reanimate.SmoothCam and head then
                offset = root.CFrame:PointToObjectSpace(head.Position) - Vector3.new(0, 1.5, 0)
            end
            humanoid.CameraOffset = offset:Lerp(humanoid.CameraOffset, math.exp(-9.8 * math.max(dt, 0)))
        end
    end))
    local function cleanup()
        if stopped then return end
        stopped = true
        for _, connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections)
        releaseSeat()
        if force.Parent then force:Destroy() end
        if humanoid.Parent then humanoid.CameraOffset = Vector3.zero end
    end
    rig.Destroying:Once(cleanup)
    return cleanup
end
]=],
