	["BlaaBlaaReanim/System/runtime/steve110/main/head_tracking.lua"] = [=[
-- Tracking is solved in body space, then converted through the actual Neck
-- frames. R6's rotated C0/C1 must never receive raw torso-space Euler angles.
local Tracking = {}
function Tracking.Finite(frame)
    if typeof(frame) ~= "CFrame" then return false end
    local x,y,z,a,b,c,d,e,f,g,h,i = frame:GetComponents()
    return x==x and y==y and z==z and a==a and b==b and c==c
        and d==d and e==e and f==f and g==g and h==h and i==i
        and math.abs(x)<math.huge and math.abs(y)<math.huge and math.abs(z)<math.huge
        and math.abs(a)<math.huge and math.abs(b)<math.huge and math.abs(c)<math.huge
        and math.abs(d)<math.huge and math.abs(e)<math.huge and math.abs(f)<math.huge
        and math.abs(g)<math.huge and math.abs(h)<math.huge and math.abs(i)<math.huge
end
function Tracking.Solve(torso, c0, c1, animation, camera, headset, scale, strength, blend)
    if not Tracking.Finite(torso) or not Tracking.Finite(c0) or not Tracking.Finite(c1)
        or not Tracking.Finite(animation) then return nil, "Invalid Neck pose" end
    strength = math.clamp(tonumber(strength) or 1, 0, 1)
    if strength~=strength then strength=1 end
    local delta, source = CFrame.identity, "Camera"
    if Tracking.Finite(headset) then
        scale = tonumber(scale) or 1
        if scale ~= scale or math.abs(scale) == math.huge then scale = 1 end
        delta = CFrame.new(headset.Position * math.max(scale, .05)) * headset.Rotation
        source = "VR headset"
    elseif Tracking.Finite(camera) then
        local look = torso:VectorToObjectSpace(camera.LookVector)
        -- Fold the rear camera hemisphere instead of clamping +/-pi to the
        -- neck limits. The old branch cut snapped from full left to full right
        -- when the camera crossed the avatar's front. Forward tracking keeps
        -- its original basis; a front-facing camera now mirrors it smoothly.
        local yaw = math.clamp(math.atan2(-look.X, math.abs(look.Z)), -math.rad(85), math.rad(85))
        if look.X * look.X + look.Z * look.Z < 1e-10 then yaw = 0 end
        local pitch = math.clamp(math.asin(math.clamp(look.Y, -1, 1)), -math.rad(75), math.rad(75))
        delta = CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)
    end
    delta = CFrame.identity:Lerp(delta, strength)
    local base = c0 * (blend and animation or CFrame.identity) * c1:Inverse()
    -- Rotate at the current head centre, preserving dance/neck translation.
    -- No hard-coded half-unit pivot and no accumulating previous tracking pose.
    local desired = CFrame.new(base.Position + delta.Position) * delta.Rotation * base.Rotation
    return c0:Inverse() * desired * c1, source
end
return Tracking
]=],
	["BlaaBlaaReanim/System/runtime/steve110/main/intro_artwork.lua"] = [=[
-- Artwork stays on its owning page. The opaque scene is the only overlay.
local Intro = {}

function Intro.Text(context)
    local Util = context.Util
    local canvas = Util.Instance("ScrollingFrame", context.Parent)
    canvas.Name, canvas.LayoutOrder = "AsciiArtCanvas", #context.Parent:GetChildren()
    canvas.BackgroundTransparency, canvas.BorderSizePixel = 1, 0
    canvas.ClipsDescendants = true
    canvas.ScrollingDirection = Enum.ScrollingDirection.X
    canvas.AutomaticCanvasSize = Enum.AutomaticSize.None
    local text = Util.Instance("TextLabel", canvas)
    text.Name, text.BackgroundTransparency, text.BorderSizePixel = "AsciiArt", 1, 0
    text.Font, text.TextSize = context.Font or Enum.Font.Code, context.Size or 12
    text.TextColor3 = Color3.new(1, 1, 1)
    text.RichText, text.TextWrapped, text.TextScaled = false, false, false
    text.TextXAlignment, text.TextYAlignment = Enum.TextXAlignment.Left, Enum.TextYAlignment.Top
    text.Active, text.Interactable, text.Text = true, true, ""
    if context.Theme then context.Theme.ApplyLabel(text) end
    local busy = false
    local function measure()
        if busy or not text.Parent then return end
        busy = true
        local bounds = Util.GetTextSize(text.Text, text.TextSize, text.Font, Vector2.new(math.huge, math.huge))
        local width, height = math.ceil(bounds.X) + 4, math.ceil(bounds.Y) + 6
        local overflow = width > canvas.AbsoluteSize.X
        -- Borderless artwork uses natural dimensions, outside control padding.
        -- Long lines can be panned horizontally; every line contributes height.
        canvas.Size = UDim2.new(1, 10, 0, height + (overflow and 4 or 0))
        canvas.CanvasSize = UDim2.fromOffset(width, height)
        canvas.ScrollBarThickness = overflow and 2 or 0
        text.Size = UDim2.fromOffset(width, height)
        text.Position = UDim2.fromOffset(math.max(0, (canvas.AbsoluteSize.X - width) / 2), 0)
        busy = false
    end
    for _, property in ipairs({"Text", "TextSize", "Font"}) do
        Util.LinkDestroyI2C(canvas, text:GetPropertyChangedSignal(property):Connect(measure))
    end
    Util.LinkDestroyI2C(canvas, canvas:GetPropertyChangedSignal("AbsoluteSize"):Connect(measure))
    measure()
    return text
end

function Intro.new(context)
    local intro, workspace, chrome = context.Intro, context.Workspace, context.Chrome
    local scene = {Busy = false, State = intro.Visible and "scene" or "workspace"}
    local serial, tween, completion, headerCompletion = 0, nil, nil, nil
    intro.Parent = context.Parent
    intro.BackgroundTransparency, intro.ZIndex = 0, 20
    intro.Size = UDim2.fromScale(1, 1)
    local function animate(entering)
        if scene.Busy or not intro.Parent then return false end
        if entering and scene.State == "scene" or not entering and scene.State == "workspace" then return false end
        serial += 1
        local ticket = serial
        scene.Busy, scene.State = true, entering and "entering" or "leaving"
        intro.Interactable = false
        local headerTween
        if entering then
            -- Keep the current page until the opaque scene covers it.
            if workspace.SaveCurrentScroll then workspace.SaveCurrentScroll() end
            if workspace.Bar then workspace.Bar.Interactable = false end
            if workspace.CurrentPage then workspace.CurrentPage.Interactable = false end
            intro.Position, intro.Visible = UDim2.new(-.5, -2, .5, 0), true
        else
            -- Restore the SAME retained page underneath the opaque scene
            -- before its first leaving frame or the header geometry changes.
            workspace.SetEnabled(true)
            headerTween = chrome.Wake()
        end
        local function play()
        if ticket ~= serial or not intro.Parent then return end
        if not entering and workspace.RestoreCurrentScroll then workspace.RestoreCurrentScroll() end
        tween = context.TweenService:Create(intro,
            TweenInfo.new(.5, Enum.EasingStyle.Cubic, entering and Enum.EasingDirection.In or Enum.EasingDirection.Out),
            {Position = entering and UDim2.new(.5, 0, .5, 0) or UDim2.new(-.5, -2, .5, 0)})
        completion = tween.Completed:Once(function(state)
            if ticket ~= serial or not intro.Parent then return end
            if state == Enum.PlaybackState.Cancelled then
                scene.Busy, scene.State = false, entering and "workspace" or "scene"
                intro.Position = UDim2.new(.5, 0, .5, 0)
                intro.Visible, intro.Interactable = not entering, not entering
                workspace.SetEnabled(entering, true)
                tween, completion = nil, nil
                return
            end
            scene.Busy, scene.State = false, entering and "scene" or "workspace"
            if entering then workspace.SetEnabled(false, true); intro.Interactable = true
            else intro.Visible, intro.Interactable = false, false end
            tween, completion = nil, nil
        end)
        tween:Play()
        end
        -- Expanding chrome changes the native scrolling viewport. Let it
        -- settle and restore scroll while the scene is still opaque, rather
        -- than exposing a clamped canvas and snapping it back mid-exit.
        if not entering and chrome.Amount and chrome.Amount.Value < .999
            and headerTween and headerTween.Completed then
            headerCompletion = headerTween.Completed:Once(function(state)
                headerCompletion = nil
                if ticket ~= serial or not intro.Parent then return end
                if state == Enum.PlaybackState.Cancelled then
                    scene.Busy, scene.State = false, "scene"
                    workspace.SetEnabled(false, true)
                    intro.Interactable = true
                else play() end
            end)
        else play() end
        return true
    end
    function scene.Enter() return animate(true) end
    function scene.Exit() return animate(false) end
    intro.Destroying:Once(function()
        serial += 1
        if headerCompletion then headerCompletion:Disconnect() end
        if completion then completion:Disconnect() end
        if tween then tween:Cancel() end
        scene.Busy = false
    end)
    return scene
end

return Intro
