	["BlaaBlaaReanim/System/runtime/steve110/main/playback_clock.lua"] = [=[
-- A music-driven pose must not freeze when its audio is missing or buffering.
return function(context)
    local now = context and context.Clock or os.clock
    local states = setmetatable({}, {__mode = "k"})
    local Clock = {}
    local function finite(value) return type(value) == "number" and value == value and math.abs(value) < math.huge end
    function Clock.Begin(sound)
        states[sound] = {Active = true, Time = 0, Updated = now(), Changed = now(), Raw = 0, Fallback = false}
    end
    function Clock.Stop(sound) states[sound] = {Active = false, Time = 0, Updated = now()} end
    function Clock.Active(sound) return states[sound] and states[sound].Active == true end
    function Clock.Seek(sound, time)
        if not finite(time) then return end
        local state = states[sound]
        if not state then Clock.Begin(sound) state = states[sound] end
        state.Time, state.Raw, state.Updated, state.Changed = math.max(time, 0), math.max(time, 0), now(), now()
    end
    function Clock.Read(sound)
        local state = states[sound]
        if not state then Clock.Begin(sound) state = states[sound] end
        if not state.Active then return 0 end
        local t = now()
        local dt = math.max(t - state.Updated, 0)
        state.Updated = t
        local raw, speed = tonumber(sound.TimePosition) or 0, tonumber(sound.PlaybackSpeed) or 1
        if not finite(raw) then raw = state.Time end
        if not finite(speed) then speed = 1 end
        speed = math.max(speed, 0)
        local paused = false
        pcall(function() paused = sound.IsPaused == true end)
        if paused then return state.Time end
        local available = sound.IsPlaying == true and sound.IsLoaded ~= false and sound.SoundId ~= ""
        if available and math.abs(raw - (state.Raw or 0)) > .00001 then
            if state.Fallback then
                -- Audio that becomes available later joins the ongoing pose,
                -- rather than restarting the animation at time zero.
                pcall(function() sound.TimePosition = state.Time end)
                raw = state.Time
            end
            state.Time, state.Raw, state.Changed, state.Fallback = raw, raw, t, false
        elseif not available or t - state.Changed > .25 then
            state.Time += dt * speed
            state.Fallback = true
            local length = tonumber(sound.TimeLength) or 0
            local startTime, endTime = 0, length
            if sound.PlaybackRegionsEnabled and sound.LoopRegion then startTime, endTime = sound.LoopRegion.Min, sound.LoopRegion.Max end
            if sound.Looped and finite(endTime) and endTime > startTime and state.Time >= endTime then
                state.Time = startTime + (state.Time - startTime) % (endTime - startTime)
            end
        end
        return state.Time
    end
    return Clock
end
