	["BlaaBlaaReanim/System/runtime/steve110/main/prefabs.lua"] = [=[
--!optimize 2
LU_NATIVE_COMPILE = true

local Util = require(script.Parent.util)
local Theme = require(script.Parent.theme)
local Data = require(script.Parent.data)

local BindToRenderStep = require(script.Parent.render)

local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")

local Prefabs = {}

function Prefabs.Triforce(tris, color)
local radius = 0.1
local width = 2 * radius * math.sin(math.pi / tris) * 2
local parent = Util.Instance("Frame")
parent.AnchorPoint = Vector2.new(0.5, 0.5)
parent.Position = UDim2.new(0.5, 0, 0.5, 0)
parent.BackgroundTransparency = 1
parent.BorderSizePixel = 0
parent:SetAttribute("Color", color)
for i=1, tris do
local height = (math.sqrt(3) / 2) * width
local pivot = Util.Instance("Frame", parent)
pivot.AnchorPoint = Vector2.new(0.5, 0.5)
pivot.Position = UDim2.new(0.5, 0, 0.5, 0)
pivot.Size = UDim2.new(1, 0, 1, 0)
pivot.BackgroundTransparency = 1
pivot.BorderSizePixel = 0
pivot.Rotation = (i / tris) * 360
local tri = Util.Instance("ImageLabel", pivot)
tri.AnchorPoint = Vector2.new(0.5, 1)
tri.Position = UDim2.new(0.5, 0, 0.5 - radius, 0)
tri.Size = UDim2.new(width, 0, height, 0)
tri.BackgroundTransparency = 1
tri.BorderSizePixel = 0
tri.Image = Util.GetCustomAsset("Assets/img_letriangul.png")
tri.ImageColor3 = color
parent:GetAttributeChangedSignal("Color"):Connect(function()
tri.ImageColor3 = parent:GetAttribute("Color")
end)
end
return parent
end
function Prefabs.Text(text, size)
text = text:upper()
size = size or 1
local ls = "BCDEIKOPQRSTUVYZ\\_`N^MJ"
local lt = ""

lt ..= "DDDDD@DFF@@@@@FSFSFSF@@@@@@@@@@@@@@EMMUKKTDD@@@@@DEEEEEDDBBBBBD@@@@@@@@@@@@@@@@@@@DE@@@G@@@@@@@@@DABBDEEI"

lt ..= "GJJJJJGDVDDDDSGJAGIISRAAGAARWJJSAAASIIRAARGIIRJJGSAABBDDGJJGJJGGJJHAAG"

lt ..= "@DD@DD@@DD@DE@@BDEDB@@@G@G@@@EDBDE@GJABD@D@@@@@@@"

lt ..= "DFJSJJJRJJRJJRGJIIIJGRJJJJJRSIIRIISSIIRIIIHIILJJHJJJSJJJGDDDDDGAAAAAJHJKMOMKJIIIIIISJQNJJJJJJPNLJJGJJJJJGRJJRIIIGJJJNGCRJJRMKJGJIGAJGSDDDDDDJJJJJJGJJJJJFDJJJNQJJJJFDFJJJJFDDDDSABDEIS"
local pixs = {}
local totalsize = 0
for i=0, 6 do
local row = {}
for j=1, text:len() do
local c = text:byte(j, j)
local w = 0
if c ~= 0x20 then
local k = (c - 33) * 7 + i
w = lt:byte(k + 1, k + 1)
if w ~= nil and w > 64 then
w = ls:byte(w - 64, w - 64) - 65
else
w = 0
end
end
for k=0, 5 do
local h = (j - 1) * 6 + (4 - k)
totalsize = math.max(totalsize, h + 1)
local p = (w // math.pow(2, k)) % 2
if p > 0 then
row[h] = true
end
end
end
pixs[i] = row
end
local pivot = Util.Instance("Frame")
pivot.AnchorPoint = Vector2.new(0.5, 0.5)
pivot.Position = UDim2.new(0.5, 0, 0.5, 0)
pivot.Size = UDim2.new(0, totalsize * size, 0, 7 * size)
pivot.BackgroundTransparency = 1
pivot.BorderSizePixel = 0
local frames = {}
for i=0, 6 do
local row = pixs[i]
local olde = nil
local olds = 0
for j=0, totalsize - 1 do
local pix = row[j]
if pix == true then
if olde ~= nil then
olds += 1
olde.Size = UDim2.new(olds / totalsize, 0, 1 / 7, 0)
else
olde = Util.Instance("Frame", pivot)
olde.AnchorPoint = Vector2.new(0, 0)
olde.Position = UDim2.new(j / totalsize, 0, i / 7, 0)
olde.Size = UDim2.new(1 / totalsize, 0, 1 / 7, 0)
olde.BackgroundColor3 = Color3.new(1, 1, 1)
olde.BackgroundTransparency = 0
olde.BorderSizePixel = 0
olds = 1
table.insert(frames, olde)
end
else
olde = nil
olds = 0
end
end
end
pivot:SetAttribute("Color", Color3.new(1, 1, 1))
pivot:SetAttribute("Transparency", 0)
pivot.AttributeChanged:Connect(function()
for _,v in frames do
v.BackgroundColor3 = pivot:GetAttribute("Color")
v.BackgroundTransparency = pivot:GetAttribute("Transparency")
end
end)
return pivot
end

function Prefabs.Window(options)
local Window = {}
local parent = options.Parent

local Main = Util.Instance("Frame", parent)
Main.Active = true
Main.AnchorPoint = options.AnchorPoint or Vector2.new(0.5, 0.5)
Main.Position = options.Position or UDim2.new(0.5, 0, 0.5, 0)
Main.Size = options.Size or UDim2.fromOffset(360, 240)
Main.BackgroundTransparency = 0
Theme.ApplyFrame(Main, {
Glow = true,
Window = true
})
Window.Main = Main

UserInputService.InputBegan:Connect(function(input, gpe)
if gpe then
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
local iX, iY = input.Position.X, input.Position.Y
local pos, size = Main.AbsolutePosition, Main.AbsoluteSize
local posX, posY = pos.X, pos.Y
local sizeX, sizeY = size.X, size.Y
if iX > posX and iX < posX + sizeX and iY > posY and iY < posY + sizeY then
Theme.PlaySound("CLICK")
end
end
end
end)

local TopBar = Util.Instance("Frame", Main)
TopBar.Position = UDim2.new(0, 0, 0, 0)
TopBar.Size = UDim2.new(1, 0, 0, 30)
TopBar.BackgroundTransparency = 0
TopBar.BackgroundColor3 = Color3.new(1, 1, 1)
TopBar.BorderSizePixel = 0
TopBar.ClipsDescendants = true
TopBar.ZIndex = 1
Theme.ApplyFrame(TopBar)
local TopBarText = Util.Instance("TextLabel", TopBar)
TopBarText.AnchorPoint = Vector2.new(0, 0.5)
TopBarText.Position = UDim2.new(0, 8, 0.5, 0)
TopBarText.Size = UDim2.new(1, -35, 1, 0)
TopBarText.BackgroundTransparency = 1
TopBarText.ClipsDescendants = true
TopBarText.Font = Data.TextFont
TopBarText.TextColor3 = Color3.new(1, 1, 1)
TopBarText.TextSize = 20
TopBarText.TextXAlignment = Enum.TextXAlignment.Left
TopBarText.Text = options.Title or "owo whats this :3c"
TopBarText.RichText = true
Theme.ApplyLabel(TopBarText)
local TopBarClose = Util.Instance("TextButton", TopBar)
TopBarClose.AnchorPoint = Vector2.new(1, 0)
TopBarClose.Position = UDim2.new(1, 0, 0, 0)
TopBarClose.Size = UDim2.new(0, 30, 1, 0)
TopBarClose.BackgroundTransparency = 1
