local tweeninfos = {
TweenInfo.new(0.5, Enum.EasingStyle.Cubic, Enum.EasingDirection.In),
TweenInfo.new(0.5, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out),
TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
TweenInfo.new(0.5, Enum.EasingStyle.Elastic, Enum.EasingDirection.Out),
TweenInfo.new(0.5, Enum.EasingStyle.Bounce, Enum.EasingDirection.Out),
TweenInfo.new(0.5, Enum.EasingStyle.Linear, Enum.EasingDirection.Out),
TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut),
}
function Window.SwitchPage(page)
if Window.CurrentPage == page then return end
if not Window.CurrentPage then
for _,v in Pages do
v.Interactable = false
v.ZIndex = v == page and 1 or 0
end
page.AnchorPoint = Vector2.new(0, 0)
page.Position = UDim2.new(0, 0, 0, 0)
page.Visible = true
page.Interactable = true
page.BorderSizePixel = 0
Window.CurrentPage = page
return
end
Window.CurrentPage = page
for _,v in Pages do
v.Interactable = false
v.ZIndex = v == page and 1 or 0
end
local dirX, dirZ = math.random(-1, 1), math.random(-1, 1)
if dirX == 0 and dirZ == 0 then dirZ = -1 end
page.AnchorPoint = Vector2.new(0.5 - dirX * 0.5, 0.5 - dirZ * 0.5)
page.Position = UDim2.new(0.5 + dirX * 0.5, 0, 0.5 + dirZ * 0.5, 0)
page.Visible = true
page.BorderSizePixel = 1
local tween = TweenService:Create(page, tweeninfos[math.random(#tweeninfos)], {
AnchorPoint = Vector2.new(0.5, 0.5),
Position = UDim2.new(0.5, 0, 0.5, 0),
})
Theme.PlaySound("SWOOSH")
tween.Completed:Once(function()
for _,v in Pages do
local a = v == page
v.Visible = a
v.Interactable = a
end
page.BorderSizePixel = 0
end)
tween:Play()
return tween.Completed
end

