local function update()
local x = Container.AbsoluteSize.X
local size = Util.GetTextSize(Text.ContentText, Text.TextSize, Text.Font, Vector2.new(x, math.huge))
Container.Size = UDim2.new(1, 0, 0, size.Y + 6)
end
