DropdownText.TextTransparency = 0
DropdownText.TextXAlignment = Enum.TextXAlignment.Center
DropdownText.TextYAlignment = Enum.TextYAlignment.Center
DropdownText.TextWrapped = true
DropdownText.TextSize = 15
Theme.ApplyLabel(DropdownText)
Theme.ApplyFrame(Dropdown)
local function update()
local x = parent.AbsoluteSize.X
local size1 = Util.GetTextSize(Text.ContentText, Text.TextSize, Text.Font, Vector2.new(x, math.huge))
local size2 = Util.GetTextSize(DropdownText.ContentText, DropdownText.TextSize, DropdownText.Font, Vector2.new(x * 0.8, math.huge))
Container.Size = UDim2.new(1, 0, 0, math.max(25, size1.Y, size2.Y + 4) + 6)
Dropdown.Size = UDim2.new(0, math.max(60, size2.X + 8), 0, size2.Y + 8)
end
Text.Text = text
DropdownText.Text = array[value]
update()
bindTextLayout(Text, update)
bindTextLayout(DropdownText, update)
local Select = Util.Instance("IntValue")
Select.Value = value
Select.Changed:Connect(function()
DropdownText.Text = array[Select.Value]
end)
local Droplist = Util.Instance("ScrollingFrame", dropdownParent)
Droplist.AnchorPoint = Vector2.new(0, 0)
Droplist.Position = UDim2.new(0, 0, 0, 0)
Droplist.Size = UDim2.new(0, 0, 0, 0)
Droplist.BackgroundTransparency = 0
Droplist.BackgroundColor3 = Color3.new(1, 1, 1)
Droplist.BorderSizePixel = 0
Droplist.Visible = false
Droplist.CanvasSize = UDim2.new(0, 0, 0, 0)
Droplist.AutomaticCanvasSize = Enum.AutomaticSize.Y
Droplist.ScrollBarThickness = 0
Droplist.ScrollingDirection = Enum.ScrollingDirection.Y
Droplist.ZIndex = 676767
Theme.ApplyFrame(Droplist, {
Glow = true
})
local padding = Util.AddPadding(Droplist)
local UIList = Util.Instance("UIListLayout", Droplist)
UIList.FillDirection = Enum.FillDirection.Vertical
UIList.HorizontalAlignment = Enum.HorizontalAlignment.Center
UIList.VerticalAlignment = Enum.VerticalAlignment.Top
UIList.Padding = UDim.new(0, 0)
UIList.SortOrder = Enum.SortOrder.LayoutOrder
local items = {}
local sizex = 60
local interact = false
local opened = false
Util.LinkDestroyI2I(Dropdown, Droplist)
for i,itemname in array do
local Item = Util.Instance("TextButton", Droplist)
Item.Size = UDim2.new(1, 0, 0, 20)
Item.BackgroundTransparency = 1
Item.BackgroundColor3 = Color3.new(1, 1, 1)
Item.BorderSizePixel = 0
Item.AutoButtonColor = true
Item.LayoutOrder = i
Item.Text = itemname
Item.TextSize = 15
Item.Font = Data.TextFont
Item.TextColor3 = Color3.new(1, 1, 1)
Item.TextXAlignment = Enum.TextXAlignment.Left
Item.TextYAlignment = Enum.TextYAlignment.Center
Item.TextWrapped = false
Theme.ApplyLabel(Item)
table.insert(items, Item)
local size = Util.GetTextSize(itemname, Item.TextSize, Item.Font, Vector2.new(math.huge, math.huge))
sizex = math.max(sizex, size.X)
Item.Activated:Connect(function()
Select.Value = i
opened = false
Theme.PlaySound("COLLAPSE")
interact = true
end)
Item.InputBegan:Connect(function(input)
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
interact = true
Theme.PlaySound("CLICK")
end
end)
end
Dropdown.Activated:Connect(function()
opened = not opened
interact = true
if opened then Theme.PlaySound("EXPAND") else Theme.PlaySound("COLLAPSE") end
end)
local conn = UserInputService.InputEnded:Connect(function(input)
if not opened then return end
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
task.wait()
if not interact then
opened = false
Theme.PlaySound("COLLAPSE")
end
interact = false
end
end)
Util.LinkDestroyI2C(Dropdown, conn)
local scrollframe = Container:FindFirstAncestorWhichIsA("ScrollingFrame")
if scrollframe then
local conn = scrollframe:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
opened = false
end)
end
local opentween = 0
BindToRenderStep(function(t, dt)
if opened then
opentween = 1 + (opentween - 1) * math.exp(-32 * dt)
else
opentween *= math.exp(-32 * dt)
end
local ysize = math.round(math.min(90, #items * 20) * opentween)
if ysize >= 1 then
local paddingx = math.max(5, Theme.Current:GetAttribute("CornerRadius"))
local p = UDim.new(0, paddingx)
padding.PaddingLeft, padding.PaddingRight = p, p
Droplist.Position = Util.Vector2ToUDim2Offset((Dropdown.AbsolutePosition + Vector2.new(0, Dropdown.AbsoluteSize.Y)) - dropdownParent.AbsolutePosition)
Droplist.Size = UDim2.new(0, math.max(Dropdown.Size.X.Offset, sizex + paddingx + paddingx), 0, ysize)
Droplist.Visible = true
if opened then
Droplist.ZIndex = 4
Droplist.Interactable = true
else
Droplist.ZIndex = 3
Droplist.Interactable = false
end
local c = Theme.Current:GetAttribute("TextColor")
for i,v in items do
v.BackgroundColor3 = c
if i == Select.Value then
v.BackgroundTransparency = 0.75
else
v.BackgroundTransparency = 1
end
end
else
Droplist.Visible = false
end
end, Droplist, true)
Util.LinkDestroyI2I(Dropdown, Select)
return Select, Text
end
