	["BlaaBlaaReanim/System/runtime/steve110/main/reanimation/limb_policy.lua"] = [=[
-- Root/replication policy ported from the actual native Steve 1.1.0 DEV Limb module.
-- The extension engine keeps its AJU, accessory, body-hide, writer and init hooks.
local Policy = {FlingPower = 32768, ReplicationInterval = 1 / 20}
function Policy.MakeXZFling(velocity)
    local x, z = velocity.X, velocity.Z
    if x < 0 then x = -Policy.FlingPower elseif x > 0 then x = Policy.FlingPower end
    if z < 0 then z = -Policy.FlingPower elseif z > 0 then z = Policy.FlingPower end
    return Vector3.new(x, 0, z)
end
function Policy.RootPose(mode, streaming, veryVoid, void, controllerRoot, torso)
    if streaming and mode < 2 then mode = 2 end
    if mode == 0 then return CFrame.new(veryVoid) end
    if mode == 1 then return CFrame.new(void) end
    if mode == 2 then return CFrame.new(controllerRoot.Position + Vector3.new(0, -12, 0)) end
    if mode == 3 then return controllerRoot.CFrame end
    return torso.CFrame
end
function Policy.RootVelocity(mode, controllerRoot, customMagnitude, customDirection)
    if mode == 0 then return Vector3.zero end
    if mode == 1 then return controllerRoot.Velocity end
    if mode == 2 then return controllerRoot.Velocity * 5 end
    if mode == 3 then return Policy.MakeXZFling(controllerRoot.Velocity) + Vector3.new(0, Policy.FlingPower, 0) end
    local direction = Vector3.yAxis
    if customDirection == 2 then direction = -Vector3.yAxis end
    if customDirection == 3 then direction = controllerRoot.CFrame.LookVector end
    if customDirection == 4 then direction = -controllerRoot.CFrame.LookVector end
    return direction * customMagnitude -- preserved modded mode, migrated to index 4
end
function Policy.RootJitter(time)
    return Vector3.new(0, 0, ((math.floor(time * 20) % 3) - 1) * 0.005)
end
function Policy.OwnedRoot(root)
    local ok, result = pcall(function() return not root:IsGrounded() and root.ReceiveAge == 0 end)
    return ok and result
end
function Policy.SkidFling(step, angle)
    local offsets = {{0,1.5,0}, {0,-1.5,0}, {2.25,1.5,-2.25}, {-2.25,-1.5,2.25}, {0,1.5,0}, {0,-1.5,0}}
    return CFrame.new(unpack(offsets[step])) * CFrame.Angles(math.rad(angle), 0, 0)
end
function Policy.Predict(time, target)
    local cf, velocity = target.CFrame, target.Velocity
    local duration = math.sin(time * 15) + 1
    local predicted = cf * CFrame.Angles(1.57, 0, 0) + Vector3.new(0, 1, 0)
    predicted += velocity * duration + Vector3.new(0, -workspace.Gravity * 0.5 * duration * duration + math.sin(time * 60), 0)
    if predicted.Position.Y < cf.Position.Y - 1 then
        predicted = predicted.Rotation + Vector3.new(predicted.Position.X, cf.Position.Y - 1, predicted.Position.Z)
    end
    return predicted, Policy.MakeXZFling(velocity)
end
return Policy
]=],
	["BlaaBlaaReanim/System/runtime/steve110/main/reanimation/reanim_limb.lua"] = [=[
--!optimize 2
-- Mod extensions preserved by mechanical extraction; 1.1.0 migration uses this factory.
return function(Context)
local LimbPolicy = require(script.Parent.limb_policy)
local Camera = Context.Camera
local Debris = Context.Debris
local Player = Context.Player
local Players = Context.Players
local RIGHTGRIP_C0 = Context.RIGHTGRIP_C0
local Reanimate = Context.Reanimate
local RunDamageMethod = Context.RunDamageMethod
local RunService = Context.RunService
local SaveData = Context.SaveData
local SaveSettingsNow = Context.SaveSettingsNow
local ToolTouchTarget = Context.ToolTouchTarget
local TweenService = Context.TweenService
local UI = Context.UI
local Util = Context.Util
local pcall = Context.pcall
workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function() Camera = workspace.CurrentCamera or Camera end)
SaveData.Reanimator = SaveData.Reanimator or {}
SaveData.Reanimator.LimbDeadRigBridge = nil

local LimbReanimator = {}
LimbReanimator.Name = "Limbs"
SaveData.Reanimator.LimbMode = SaveData.Reanimator.LimbMode or 0
SaveData.Reanimator.LimbVelocity = SaveData.Reanimator.LimbVelocity or 0
if SaveData.Reanimator.LimbArchitectureVersion ~= "1.1.0" then
    -- Index 2 used to be our custom direction/magnitude mode. Native 1.1.0
    -- uses that index for velocity * 5; migrate the old choice without changing it.
    if SaveData.Reanimator.LimbVelocity == 2 then SaveData.Reanimator.LimbVelocity = 4 end
    SaveData.Reanimator.LimbArchitectureVersion = "1.1.0"
end
SaveData.Reanimator.LimbVelocity = math.clamp(tonumber(SaveData.Reanimator.LimbVelocity) or 0, 0, 4)
SaveData.Reanimator.LimbFlingStyle = math.clamp(tonumber(SaveData.Reanimator.LimbFlingStyle) or 4, 0, 4)
SaveData.Reanimator.LimbInitMode = SaveData.Reanimator.LimbInitMode or 2
SaveData.Reanimator.LimbReplicateFPS10 = not not SaveData.Reanimator.LimbReplicateFPS10
SaveData.Reanimator.LimbShowMeHowILook = SaveData.Reanimator.LimbShowMeHowILook == true
-- Remove the retired toggle from existing saves. Older builds treat a missing
-- value as enabled, so rolling back still selects their compatible default.
SaveData.Reanimator.LimbLegacyMotorReplication = nil
SaveData.Reanimator.LimbRoleplay = not not SaveData.Reanimator.LimbRoleplay
SaveData.Reanimator.LimbUseNaNFling = not not SaveData.Reanimator.LimbUseNaNFling
if SaveData.Reanimator.LimbTargetMethod == nil then
	if SaveData.Reanimator.LimbUseCustomKill == true or SaveData.Reanimator.LimbUseCustomKill == 1 then
		SaveData.Reanimator.LimbTargetMethod = 3
	elseif SaveData.Reanimator.LimbUseToolKill == true or SaveData.Reanimator.LimbUseToolKill == 1 then
		SaveData.Reanimator.LimbTargetMethod = 2
	else
		SaveData.Reanimator.LimbTargetMethod = 1
	end
end
SaveData.Reanimator.LimbTargetMethod = math.clamp(
	math.floor(tonumber(SaveData.Reanimator.LimbTargetMethod) or 1),
	1,
	3
)
SaveData.Reanimator.LimbFlingVelocityMagnitude = math.clamp(
	math.floor(tonumber(SaveData.Reanimator.LimbFlingVelocityMagnitude) or 10000),
	1,
	1000000000
)
SaveData.Reanimator.LimbFlingVelocityDirection = math.clamp(
	math.floor(tonumber(SaveData.Reanimator.LimbFlingVelocityDirection) or 1),
	1,
	4
)
LimbReanimator.Mode = SaveData.Reanimator.LimbMode
-- 0 = hide rootpart (defaults to 2 when streaming is enabled)
-- 1 = put rootpart just under void (defaults to 2 when streaming is enabled)
-- 2 = keep rootpart streamed, puts rootpart below character
-- 3 = currentangle styled
-- 4 = rootpart is torso (most interpolated mode)
LimbReanimator.Velocity = SaveData.Reanimator.LimbVelocity
LimbReanimator.FlingStyle = SaveData.Reanimator.LimbFlingStyle
LimbReanimator.SaveDataConfig = {
    {"Mode", "LimbMode", false}, {"Velocity", "LimbVelocity", false},
    {"FlingStyle", "LimbFlingStyle", false}, {"ReplicateFPS10", "LimbReplicateFPS10", false},
    {"ShowMeHowILook", "LimbShowMeHowILook", false},
}
-- 0 = no velocity
-- 1 = copy from fake character
-- 2 = copy velocity * 5 (native 1.1.0)
-- 3 = native XZ fling signs and positive Y
-- 4 = preserved custom magnitude/direction
LimbReanimator.InitMode = SaveData.Reanimator.LimbInitMode
-- 0 = just reset
-- 1 = time permadeath, and reset
-- 2 = time permadeath, "without reset"
LimbReanimator.ReplicateFPS10 = SaveData.Reanimator.LimbReplicateFPS10
LimbReanimator.ShowMeHowILook = SaveData.Reanimator.LimbShowMeHowILook
LimbReanimator.FlingEnabled = not SaveData.Reanimator.LimbRoleplay
LimbReanimator.UseNaNFling = SaveData.Reanimator.LimbUseNaNFling
LimbReanimator.TargetMethod = SaveData.Reanimator.LimbTargetMethod
LimbReanimator.FlingVelocityMagnitude = SaveData.Reanimator.LimbFlingVelocityMagnitude
LimbReanimator.FlingVelocityDirection = SaveData.Reanimator.LimbFlingVelocityDirection
LimbReanimator.FlingTargets = {}
LimbReanimator._TempNotFling = {}
LimbReanimator.Status = "Real rig: waiting"
LimbReanimator.JointBackend = "waiting"
-- Public binding state is deliberately separate from Player.Character. Some
-- experiences rebuild a rig in-place or swap Player.Character while the
-- controller character is also being recreated. Consumers such as the
-- persistent hitbox display must follow the rig that this reanimator actually
-- bound, not whichever model happens to be exposed by Player.Character during
-- that frame.
LimbReanimator.ActiveRealCharacter = nil
LimbReanimator.RigGeneration = 0
LimbReanimator.RebindCurrentRig = function() end
LimbReanimator.ReplicationWriterControls = {}
function LimbReanimator.GetDebugDump()
	return Util.GetJointReplicationReport(LimbReanimator.ActiveRealCharacter, Reanimate.Character)
end
function LimbReanimator.ShowHitboxes()
	-- Bound rig centers are rendered by the shared persistent hitbox controller.
end
function LimbReanimator.Fling(target, duration)
	if not LimbReanimator.FlingEnabled then
		return
	end
	if not target then
		return false
	end
	for _, v in LimbReanimator.FlingTargets do
		if v.Target == target then
			return false
		end
	end
	if target == Reanimate.Character then
		return false
	end
	if target == Player.Character then
		return false
	end
	if typeof(target) == "Instance" then
		if LimbReanimator._TempNotFling[target] then
			return
		end
		LimbReanimator._TempNotFling[target] = true
		task.delay(1, function()
			LimbReanimator._TempNotFling[target] = nil
		end)
	end
	table.insert(LimbReanimator.FlingTargets, {
		Target = target,
		Duration = duration,
	})
	if typeof(target) == "Instance" then
		if target:IsA("Model") then
			local h = Util.Instance("Highlight")
			h.Adornee = target
			h.FillColor = Color3.new(1, 0, 0)
			h.OutlineColor = Color3.new(1, 0, 0)
			h.FillTransparency = 0.5
			h.OutlineTransparency = 0
			h.Parent = target
			TweenService:Create(h, TweenInfo.new(5), {
				FillTransparency = 1,
				OutlineTransparency = 1,
			}):Play()
			game.Debris:AddItem(h, 5)
		end
	end
	return true
end
function LimbReanimator.SetRootPartMode(mode)
	assert(typeof(mode) == "number")
	LimbReanimator.Mode = mode
end
function LimbReanimator.Config(parent)
	UI.CreateText(
		parent,
		"as mentioned in the README, this only works for SOME games,\nbecause 'modern' games create the Animator automatically which breaks limb reanimation",
		10,
		Enum.TextXAlignment.Center
