	["BlaaBlaaReanim/System/runtime/steve110/main/rig_adapter.lua"] = [=[
-- Avatar controller / legacy animation driver bridge. Physical writers stay external.
return function(ctx)
    local api = {States=setmetatable({}, {__mode="k"}), Drivers=setmetatable({}, {__mode="k"}), Modules=setmetatable({}, {__mode="k"})}
    local groups = {
        Torso="LowerTorso", Head="Head", ["Left Arm"]="LeftUpperArm", ["Right Arm"]="RightUpperArm",
        ["Left Leg"]="LeftUpperLeg", ["Right Leg"]="RightUpperLeg",
    }
    function api.RigType(rig)
        local h=rig and rig:FindFirstChildOfClass("Humanoid")
        return h and h.RigType.Name or (rig and rig:FindFirstChild("UpperTorso") and "R15" or "R6")
    end
    function api.Owner(rig) return api.Drivers[rig] or rig end
	function api.JointParts(joint)
        if not joint or not (joint:IsA("Motor6D") or joint.ClassName=="AnimationConstraint") then return nil,nil end
        if joint:IsA("Motor6D") then return joint.Part0,joint.Part1 end
        if ctx.JointParts then return ctx.JointParts(joint) end
        return joint.Part0,joint.Part1
    end
    function api.JointFrames(joint)
        if joint:IsA("Motor6D") then return joint.C0,joint.C1 end
        if ctx.JointFrames then return ctx.JointFrames(joint) end
        return joint.C0,joint.C1
    end
    function api.IsBodyMotor(rig,motor)
        local p0,p1=api.JointParts(motor)
        return p0 and p1 and p0.Parent==rig and p1.Parent==rig
    end
    function api.IsRigMotor(rig,motor)
	if motor.ClassName=="AnimationConstraint" then return api.IsBodyMotor(rig,motor) end
        if not motor:IsA("Motor6D") or not motor.Part0 or not motor.Part1 then return false end
        for _,part in ipairs({motor.Part0,motor.Part1}) do
            local accessory=part:FindFirstAncestorOfClass("Accessory")
            if part.Parent~=rig and (not accessory or accessory.Parent~=rig) then return false end
        end
        return true
    end
    local function index(rig)
        local result={}
        for _,m in ipairs(rig:GetDescendants()) do if api.IsBodyMotor(rig,m) then local _,p1=api.JointParts(m) result[p1.Name]=m end end
        return result
    end
    local function rest(m) local c0,c1=api.JointFrames(m) return c0*c1:Inverse() end
    local function dirty(state)
        state.Dirty=true
    end
    function api.Ensure(native)
        if not native or api.RigType(native)~="R15" then return nil end
        local state=api.States[native]
        if state and state.Driver.Parent then return state end
        local driver, accessories, motors=ctx.CreateDriver(native)
        driver.Name="_UhhhhhhLegacyR6Driver"
        driver:SetAttribute("_UhhhhhhLegacyR6Driver",true)
        local root=driver:FindFirstChild("HumanoidRootPart")
        if root then root.Anchored=true end
        driver.Parent=native
        state={Native=native,Driver=driver,Accessories=accessories or {},AccessoryMotors=motors or {},CreatedMotors={},Dirty=true,Connections={},NativeAuthored=false}
        api.States[native],api.Drivers[driver]=state,native
        state.Source,state.Target=index(driver),index(native)
        state.SourceRest,state.TargetRest={},{}
        state.AccessorySync={}
        for original,copy in pairs(state.AccessoryMotors) do
            state.AccessorySync[original]={C0=original.C0,C1=original.C1,Transform=original.Transform,Enabled=original.Enabled,Part0=original.Part0,Part1=original.Part1}
        end
        for _,m in pairs(state.Source) do state.SourceRest[m]=rest(m) end
        for _,m in pairs(state.Target) do state.TargetRest[m]=rest(m) end
        for _,rig in ipairs({native,driver}) do
            for _,event in ipairs({"DescendantAdded","DescendantRemoving"}) do
                table.insert(state.Connections,rig[event]:Connect(function() dirty(state) end))
            end
        end
        table.insert(state.Connections,native.Destroying:Connect(function() api.Release(native) end))
        return state
    end
    local function refresh(state)
        if not state.Dirty then return end
        state.Source,state.Target=index(state.Driver),index(state.Native)
        state.SourceRest,state.TargetRest=state.SourceRest or {},state.TargetRest or {}
        for name,m in pairs(state.Source) do if not state.SourceRest[m] then state.SourceRest[m]=rest(m) end end
        for name,m in pairs(state.Target) do if not state.TargetRest[m] then state.TargetRest[m]=rest(m) end end
        api.SyncAccessories(state)
        api.SyncAccessoryMotors(state)
        state.Dirty=false
    end
    function api.ModuleRig(native,module,create)
        if not native or api.RigType(native)~="R15" or module.RigType=="R15" or module.ControllerRig=="Native" then return native end
        local found=api.Modules[module]
        if found and api.Owner(found)==native and found.Parent then return found end
        if create==false then return native end
        local state=api.Ensure(native)
        api.Modules[module]=state.Driver
        return state.Driver
    end
    function api.Prepare(rig)
        local native=api.Owner(rig)
        local state=api.States[native]
        if not state then return end
        state.NativeAuthored=rig==native
        local root=state.Native:FindFirstChild("HumanoidRootPart")
        local fake=state.Driver:FindFirstChild("HumanoidRootPart")
        if root and fake then
            fake.CFrame=root.CFrame
            fake.AssemblyLinearVelocity=root.AssemblyLinearVelocity
        end
        local a,b=state.Native:FindFirstChildOfClass("Humanoid"),state.Driver:FindFirstChildOfClass("Humanoid")
        if a and b then
            b.WalkSpeed,b.JumpPower,b.HipHeight=a.WalkSpeed,a.JumpPower,a.HipHeight
            b.Sit,b.PlatformStand=a.Sit,a.PlatformStand
            b:Move(a.MoveDirection,false)
            if a:GetState()~=b:GetState() then b:ChangeState(a:GetState()) end
        end
        for _,name in ipairs({"MovementInit","IsDancing","MovesetInternalName","DanceInternalName","Stunned","IsStunned","Stun","Ragdolled","KnockedDown"}) do
            state.Driver:SetAttribute(name,state.Native:GetAttribute(name))
        end
    end
    function api.NativePoseWritten(rig)
        local state=api.States[rig]
        if state then state.NativeAuthored=true end
    end
    function api.RigForTrack(rig,track)
        local native=api.Owner(rig)
        if not native or api.RigType(native)~="R15" then return rig end
        local legacy=false
        for _,frame in ipairs(track and track.Keyframes or {}) do
            for _,pose in ipairs(frame.Poses) do
                if pose.Name=="UpperTorso" or pose.Name=="LowerTorso" or pose.Name:find("UpperArm",1,true)
                    or pose.Name:find("LowerArm",1,true) or pose.Name:find("UpperLeg",1,true) or pose.Name:find("LowerLeg",1,true)
                    or pose.Name=="LeftHand" or pose.Name=="RightHand" or pose.Name=="LeftFoot" or pose.Name=="RightFoot" then return native end
                if pose.Name=="Torso" or pose.Name=="Left Arm" or pose.Name=="Right Arm"
                    or pose.Name=="Left Leg" or pose.Name=="Right Leg" then legacy=true end
            end
        end
        return legacy and api.Ensure(native).Driver or rig
    end
    local aliases={UpperTorso="Torso",LowerTorso="Torso"}
    for _,side in ipairs({"Left","Right"}) do
        for _,suffix in ipairs({"UpperArm","LowerArm","Hand"}) do aliases[side..suffix]=side.." Arm" end
        for _,suffix in ipairs({"UpperLeg","LowerLeg","Foot"}) do aliases[side..suffix]=side.." Leg" end
    end
    local function animated(name)
        return not ctx.ShouldAnimate or ctx.ShouldAnimate(name) and (not aliases[name] or ctx.ShouldAnimate(aliases[name]))
    end
    local function driverPart(state,part)
        if not part then return nil end
        if part.Parent==state.Native then
            return state.Driver:FindFirstChild(aliases[part.Name] or part.Name)
        end
        local accessory=part:FindFirstAncestorOfClass("Accessory")
        local copy=accessory and state.Accessories[accessory]
        if not copy then return nil end
        local path={} local node=part
        while node~=accessory do table.insert(path,1,node.Name) node=node.Parent end
        for _,name in ipairs(path) do copy=copy and copy:FindFirstChild(name) end
        return copy
    end
    local function nativePart(state,part)
        if not part then return nil end
        if part.Parent==state.Driver then return state.Native:FindFirstChild(groups[part.Name] or part.Name) end
        local accessory=part:FindFirstAncestorOfClass("Accessory")
        for original,copy in pairs(state.Accessories) do
            if accessory==copy then
                local path={} local node=part
                while node~=accessory do table.insert(path,1,node.Name) node=node.Parent end
                for _,name in ipairs(path) do original=original and original:FindFirstChild(name) end
                return original
            end
        end
    end
    function api.SyncAccessories(state)
        for original,copy in pairs(state.Accessories) do
            if original.Parent~=state.Native then state.Accessories[original]=nil copy:Destroy() end
        end
        local missing={}
        for _,original in ipairs(state.Native:GetChildren()) do
            if original:IsA("Accessory") and not state.Accessories[original] then missing[original]=true end
        end
        if next(missing) then
            local temporary,accessories,motors=ctx.CreateDriver(state.Native)
            local added={}
            for original,copy in pairs(accessories) do
                if missing[original] then state.Accessories[original]=copy added[copy]=true copy.Parent=state.Driver end
            end
            for original,copy in pairs(motors) do
                if copy.Parent and copy.Part0 and copy.Part1 and (added[copy.Part0:FindFirstAncestorOfClass("Accessory")] or added[copy.Part1:FindFirstAncestorOfClass("Accessory")]) then
                    for _,key in ipairs({"Part0","Part1"}) do copy[key]=driverPart(state,original[key]) end
                    copy.Parent=driverPart(state,original.Parent) or copy.Part0
                    state.AccessoryMotors[original]=copy
                    state.AccessorySync[original]={C0=original.C0,C1=original.C1,Transform=original.Transform,Enabled=original.Enabled,Part0=original.Part0,Part1=original.Part1}
                end
            end
            for copy in pairs(added) do
                for _,joint in ipairs(copy:GetDescendants()) do
                    if joint:IsA("JointInstance") then
                        for _,key in ipairs({"Part0","Part1"}) do
                            local part=joint[key]
                            if part and part.Parent==temporary then joint[key]=state.Driver:FindFirstChild(part.Name)
                            elseif part then
                                local accessory=part:FindFirstAncestorOfClass("Accessory")
                                if accessory and not added[accessory] then
                                    for original,tempCopy in pairs(accessories) do
                                        if tempCopy==accessory then
                                            local path={} local node=part
                                            while node~=accessory do table.insert(path,1,node.Name) node=node.Parent end
                                            for _,name in ipairs(path) do original=original and original:FindFirstChild(name) end
                                            joint[key]=driverPart(state,original)
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            temporary:Destroy()
        end
        for original,copy in pairs(state.AccessoryMotors) do
            if not state.CreatedMotors[original] and (not original.Parent or not copy.Parent) then state.AccessoryMotors[original],state.AccessorySync[original]=nil,nil end
        end
    end
    local function retireCreated(state,original,record)
        state.CreatedMotors[original],state.AccessoryMotors[original],state.AccessorySync[original]=nil,nil,nil
        for joint,enabled in pairs(record.Replaced) do if joint.Parent and joint.Enabled==false then joint.Enabled=enabled end end
        original:Destroy()
    end
    function api.SyncAccessoryMotors(state)
        for original,record in pairs(state.CreatedMotors) do
            local copy=state.AccessoryMotors[original]
            if not copy or not copy.Parent or not original.Parent then retireCreated(state,original,record) end
        end
        local known={} for _,copy in pairs(state.AccessoryMotors) do known[copy]=true end
        local nativeJoints=state.Native:GetDescendants()
        for _,copy in ipairs(state.Driver:GetDescendants()) do
            if not known[copy] and api.IsRigMotor(state.Driver,copy) and not api.IsBodyMotor(state.Driver,copy) then
                local p0,p1=nativePart(state,copy.Part0),nativePart(state,copy.Part1)
                if p0 and p1 then
                    local original=copy:Clone()
                    original.Part0,original.Part1=p0,p1
                    for _,endpoint in ipairs({{"Part0","C0"},{"Part1","C1"}}) do
                        local p=original[endpoint[1]]
                        if p.Parent==state.Native then original[endpoint[2]]=ctx.BodyAnchorOffset(p.Name):Inverse()*copy[endpoint[2]] end
                    end
                    local replaced={}
                    local driven=p1:FindFirstAncestorOfClass("Accessory") and p1 or p0
                    for _,joint in ipairs(nativeJoints) do
                        if joint:IsA("JointInstance") and joint.Parent and joint.Enabled and (joint.Part1==driven
                            or joint.Part0==driven and joint.Part1 and (not joint:IsA("Motor6D") or not joint.Part1:FindFirstAncestorOfClass("Accessory"))) then
                            replaced[joint]=joint.Enabled joint.Enabled=false
                        end
                    end
                    original:SetAttribute("_UhhhhhhLegacyDriverJoint",true)
                    original.Parent=p0
                    state.AccessoryMotors[original]=copy state.CreatedMotors[original]={Replaced=replaced}
                    state.AccessorySync[original]={C0=original.C0,C1=original.C1,Transform=original.Transform,Enabled=original.Enabled,Part0=p0,Part1=p1}
                end
            end
        end
    end
    function api.Apply(rig)
        local native=api.Owner(rig)
        local state=api.States[native]
        if not state or not state.Driver.Parent then return native end
        if rig==state.Driver then state.NativeAuthored=false end
        if state.NativeAuthored then return native end
        refresh(state)
        for sourceName,targetName in pairs(groups) do
            local source,target=state.Source[sourceName],state.Target[targetName]
            if source and target and source.Parent and target.Parent and animated(sourceName) and animated(targetName) then
                local reference=state.SourceRest[source]
                local sourceC0,sourceC1=api.JointFrames(source)
                local pose=sourceC0*source.Transform*sourceC1:Inverse()
                local scale=1
                if sourceName~="Torso" and sourceName~="Head" then
                    local side=sourceName:sub(1,sourceName:find(" ")-1)
                    local suffix=sourceName:find("Arm",1,true) and "Arm" or "Leg"
                    local length=0
                    for _,segment in ipairs({"Upper"..suffix,"Lower"..suffix,suffix=="Arm" and "Hand" or "Foot"}) do
                        local part=native:FindFirstChild(side..segment)
                        if part then length+=part.Size.Y end
                    end
                    scale=source.Part1.Size.Y>0 and length/source.Part1.Size.Y or 1
                end
                local nativeRest=state.TargetRest[target]
                local relative=CFrame.new(nativeRest.Position+(pose.Position-reference.Position)*scale)
                    *(pose.Rotation*reference.Rotation:Inverse())*nativeRest.Rotation
                local targetC0,targetC1=api.JointFrames(target)
                target.Transform=targetC0:Inverse()*relative*targetC1
            end
        end
        -- R6 has no authored elbow/knee/waist articulation. Keep their native
        -- bases; the subsequent R15 IK layer owns knee/ankle corrections.
        for name,m in pairs(state.Target) do
            if name=="UpperTorso" or name:find("LowerArm",1,true) or name:find("Hand",1,true)
                or name:find("LowerLeg",1,true) or name:find("Foot",1,true) then if animated(name) then m.Transform=CFrame.identity end end
        end
        for original,copy in pairs(state.AccessoryMotors) do
            if original.Parent and copy.Parent and original.Part0 and original.Part1 then
                local inAccessory=original.Part0:FindFirstAncestorOfClass("Accessory") or original.Part1:FindFirstAncestorOfClass("Accessory")
                if inAccessory then
                    local previous=state.AccessorySync[original]
                    -- Direct edits to the native controller win over a stale
                    -- legacy accessory copy; mirror them into the driver.
                    local external=previous and (original.Transform~=previous.Transform or original.C0~=previous.C0
                        or original.C1~=previous.C1 or original.Enabled~=previous.Enabled
                        or original.Part0~=previous.Part0 or original.Part1~=previous.Part1)
                    if external then copy.Transform=original.Transform copy.Enabled=original.Enabled end
                    for _,endpoint in ipairs({{"Part0","C0"},{"Part1","C1"}}) do
                        local part=original[endpoint[1]]
                        if not external and copy[endpoint[1]]~=driverPart(state,part) then
                            part=nativePart(state,copy[endpoint[1]]) original[endpoint[1]]=part
                        end
                        local basis=part and part.Parent==native and ctx.BodyAnchorOffset(part.Name) or CFrame.identity
                        if external then copy[endpoint[1]]=driverPart(state,part) copy[endpoint[2]]=basis*original[endpoint[2]]
                        else original[endpoint[2]]=basis:Inverse()*copy[endpoint[2]] end
                    end
                    if not external then original.Transform=copy.Transform original.Enabled=copy.Enabled end
                    state.AccessorySync[original]={C0=original.C0,C1=original.C1,Transform=original.Transform,Enabled=original.Enabled,Part0=original.Part0,Part1=original.Part1}
                end
            end
        end
        return native
    end
    function api.Release(native)
        local state=api.States[native]
        if not state then return end
        api.States[native],api.Drivers[state.Driver]=nil,nil
        for _,c in ipairs(state.Connections) do c:Disconnect() end
        for module,rig in pairs(api.Modules) do if rig==state.Driver then api.Modules[module]=nil end end
        for original,record in pairs(state.CreatedMotors) do retireCreated(state,original,record) end
        if state.Driver.Parent then state.Driver:Destroy() end
    end
    function api.Destroy()
        local rigs={} for rig in pairs(api.States) do table.insert(rigs,rig) end
        for _,rig in ipairs(rigs) do api.Release(rig) end
    end
    return api
end
