	["BlaaBlaaReanim/System/runtime/steve110/main/roserika_music.lua"] = [=[
-- Roserika's catalog plus verified Steve music mirrors. Existing songs retain
-- their order; legacy ROSRAssets are reused, without another username endpoint.
