local function cached(path)
    if not path then return false end
    local ok, value = pcall(isfile, path)
    return ok and value == true
end
function Catalog.Extend(database)
    local names = {}
    for _, entry in ipairs(database) do names[entry[2]] = true end
    for _, track in ipairs(Catalog.Tracks) do
        if not names[track.Name] then
            local file = cached(track.Legacy) and track.Legacy or track.File
            -- The five songs without a verified mirror remain available when
            -- Steve's supplied Roserika script has already cached them.
            if track.URL or cached(file) then
                table.insert(database, {file, track.Name})
                names[track.Name], track.Added = true, true
            end
        end
    end
    return database
end
local function audio(bytes)
    if type(bytes) ~= "string" or #bytes < 128 then return false end
    return bytes:sub(1, 3) == "ID3" or (bytes:byte(1) == 255 and bit32.band(bytes:byte(2), 224) == 224)
end
function Catalog.Cache(context)
    if cached("BlaaBlaaReanim/Muzik/nobuiltin") then return 0 end
    local failed = 0
    for _, track in ipairs(Catalog.Tracks) do
        if track.Added and track.URL and not cached(track.Legacy) then
            local readable, existing = pcall(readfile, track.File)
            if not readable or not audio(existing) then
                local fetched, bytes, reason = pcall(context.Fetch, track.URL, nil, 1, true)
                if not fetched then reason, bytes = tostring(bytes), nil end
                if audio(bytes) then
                    local ok = pcall(function()
                        writefile(track.File, bytes)
                        assert(audio(readfile(track.File)), "music cache write failed")
                    end)
                    if not ok then failed += 1 end
                else
                    failed += 1
                    warn("Roserika music " .. track.Name .. ": " .. tostring(reason or "invalid audio"))
                end
                task.wait()
            end
        end
    end
    return failed
end
return Catalog
