	["BlaaBlaaReanim/System/runtime/steve110/main/signal.lua"] = [=[
--!optimize 2
LU_NATIVE_COMPILE = true

local Signal = {}

Signal.__index = Signal
Signal.__call = function()
return setmetatable({}, Signal)
end

Signal.Connect = function(signal, callback)
if not signal.Connections then
signal.Connections = {}
end
local obj = {
Signal = signal,
Callback = callback,
Connected = true,
Disconnect = function(self)
self.Connected = false
local t = self.Signal.Connections
local idx = table.find(t, self)
if idx then table.remove(t, idx) end
end
}
table.insert(signal.Connections, obj)
return obj
end

Signal.Fire = function(signal, ...)
if not signal.Connections then return end
for _,obj in signal.Connections do
task.spawn(obj.Callback, ...)
end
end

Signal.DisconnectAll = function(signal, ...)
if not signal.Connections then return end
for _,obj in signal.Connections do
obj:Disconnect()
end
signal.Connections = nil
end

return setmetatable({}, Signal)
]=],
	["BlaaBlaaReanim/System/runtime/steve110/main/stream_cache.lua"] = [=[
-- Only streamed assets use this cache. Installed content keeps its normal path.
return function(deps)
    local root = "BlaaBlaaReanim/StreamCache/"
    local scopes, serial, bytes, files = {}, 0, 0, 0
    local cache = {Root = root}
    local function scopeFor(path)
        local id = path:sub(1, #root) == root and path:sub(#root + 1):match("^([^/]+)/")
        return id and scopes[id] or nil
    end
    function cache.IsTemporary(path) return path:sub(1, #root) == root end
    function cache.Ticket(path) return scopeFor(path) end
    function cache.Current(path, ticket)
        return not cache.IsTemporary(path) or (ticket ~= nil and ticket.Alive and scopeFor(path) == ticket)
    end
    function cache.NewScope()
        assert(type(deps.Delete) == "function" and type(deps.List) == "function", "Temporary streaming needs delfile and listfiles")
        serial += 1
        local id = deps.Session .. tostring(serial)
        local scope = {Id = id, Alive = true, Files = {}}
        scopes[id] = scope
        return scope
    end
    function cache.Reference(scope, filename)
        assert(scope and scope.Alive, "Stream has ended")
        return "STREAM/" .. scope.Id .. "/" .. filename
    end
    function cache.Path(filename, normalPath)
        local id, name = filename:match("^STREAM/([^/]+)/(.*)$")
        if not id then return normalPath end
        assert(scopes[id] and scopes[id].Alive, "Stream has ended")
        -- The caller validates the complete asset name before it reaches here.
        return root .. id .. "/" .. normalPath:match("^BlaaBlaaReanim/Content/(.*)$"):gsub("/STREAM/" .. id .. "/", "/", 1)
    end
    function cache.Reserve(path, size, ticket)
        if not cache.IsTemporary(path) then return end
        assert(cache.Current(path, ticket), "Stream has ended")
        local old = ticket.Files[path]
        local nextBytes, nextFiles = bytes - (old or 0) + size, files + (old and 0 or 1)
        assert(nextBytes <= (deps.MaximumBytes or 128 * 1024 * 1024), "Temporary stream exceeds 128 MB; choose a smaller entry")
        assert(nextFiles <= (deps.MaximumFiles or 64), "Temporary stream needs too many simultaneous assets")
        bytes, files, ticket.Files[path] = nextBytes, nextFiles, size
    end
    function cache.Release(scope)
        if not scope or not scope.Alive then return end
        scope.Alive, scopes[scope.Id] = false, nil -- invalidate pending downloads before deleting
        for path, size in pairs(scope.Files) do
            bytes, files = bytes - size, files - 1
            pcall(deps.Forget, path)
            local ok, reason = pcall(deps.Delete, path)
            if not ok then (deps.Warn or warn)("Stream cleanup: " .. tostring(reason)) end
        end
        table.clear(scope.Files)
        if type(deps.DeleteFolder) == "function" then pcall(deps.DeleteFolder, root .. scope.Id) end
    end
    function cache.Clear()
        local retiring = {}
        for _, scope in pairs(scopes) do table.insert(retiring, scope) end
        for _, scope in ipairs(retiring) do cache.Release(scope) end
    end
    function cache.Discard(path)
        if cache.IsTemporary(path) then deps.Forget(path); pcall(deps.Delete, path) end
    end
    function cache.Stats() return {Bytes = bytes, Files = files} end
    function cache.PurgePrevious()
        if type(deps.List) ~= "function" or type(deps.Delete) ~= "function" then return end
        local function purge(folder, depth)
            if depth > 16 then return end
            local ok, entries = pcall(deps.List, folder)
            if not ok or type(entries) ~= "table" then return end
            for _, path in ipairs(entries) do
                path = tostring(path):gsub("\\", "/")
                local offset = path:find(root, 1, true)
                path = offset and path:sub(offset) or path
                if path:sub(1, #root) ~= root or path:find("/../", 1, true) then continue end
                local listed, directory = pcall(deps.IsFolder, path)
                if listed and directory then purge(path, depth + 1)
                else deps.Forget(path); pcall(deps.Delete, path) end
            end
            if type(deps.DeleteFolder) == "function" then pcall(deps.DeleteFolder, folder) end
        end
        purge(root:sub(1, -2), 0)
    end
    return cache
end
