CurrentStyle:SetAttribute("BackgroundGradient", "")
CurrentStyle:SetAttribute("OutlineGradientRotation", 0)
CurrentStyle:SetAttribute("BackgroundGradientRotation", 0)
Theme.Current = CurrentStyle
local _EventHandlers = {}
function Theme.OnChanged(attrname, callback)
local last = CurrentStyle:GetAttribute(attrname)
callback(last)
local sig = _EventHandlers[attrname]
if not sig then
sig = Signal()
_EventHandlers[attrname] = sig
CurrentStyle:GetAttributeChangedSignal(attrname):Connect(function()
local now = CurrentStyle:GetAttribute(attrname)
if last ~= now then last = now sig:Fire(last) end
end)
end
return sig:Connect(callback)
end
local _colorStuffSignals = {}
local function _registerColorStuff(obj, colprop, col, gradcol, gradrot, depthed)
local gradient = Util.Instance("UIGradient", obj)
gradient.Enabled = false
gradient.Transparency = NumberSequence.new(0)
local oldgc
local function getc(c, gc, gr)
if gc and #gc > 0 then
if oldgc ~= gc then
local split = string.split(gc, ",")
if #split >= 8 and #split % 4 == 0 then
local first = true
local time = -1
local kfs = {}
local fin = false
for i=1, #split, 4 do
local t, r, g, b = tonumber(split[i]), tonumber(split[i + 1]), tonumber(split[i + 2]), tonumber(split[i + 3])
if not t and r and g and b then warn("invalid number property") break end
if t < 0 or t > 1 then warn("t isnt between 0 and 1") break end
if first then
if t ~= 0 then warn("keyframes start at t=0") break end
first = false
end
if time >= t then warn("keyframe ts should be in ascending order") break end
if time == 1 then warn("keyframe after t=1") fin = false break end
if t == 1 then fin = true end
time = t
kfs[#kfs + 1] = ColorSequenceKeypoint.new(t, Color3.fromRGB(r, g, b))
end
if fin then
gradient.Color = ColorSequence.new(kfs)
gradient.Enabled = true
end
else
warn("wrong number of properties: " .. #split)
end
end
oldgc = gc
gradient.Rotation = gr
c = Color3.new(1, 1, 1)
else
if oldgc then
gradient.Enabled = false
oldgc = nil
end
end
return c
end
local update
if depthed then
function update(c, gc, gr)
c = getc(c, gc, gr)
obj[colprop] = Color3.new(c.R * 0.9, c.G * 0.9, c.B * 0.9)
end
else
function update(c, gc, gr)
c = getc(c, gc, gr)
obj[colprop] = c
end
end
local _key = col .. "-" .. gradcol .. "-" .. gradrot
local sig = _colorStuffSignals[_key]
if not sig then
sig = Signal()
_colorStuffSignals[_key] = sig
local alreadyDeferred = false
local function fire()
local c, gc, gr = CurrentStyle:GetAttribute(col), CurrentStyle:GetAttribute(gradcol), CurrentStyle:GetAttribute(gradrot)
sig:Fire(c, gc, gr)
alreadyDeferred = false
end
local function deferFire()
if alreadyDeferred then return end
alreadyDeferred = true
task.defer(fire)
end
Theme.OnChanged(col, deferFire)
Theme.OnChanged(gradcol, deferFire)
Theme.OnChanged(gradrot, deferFire)
end
update(CurrentStyle:GetAttribute(col), CurrentStyle:GetAttribute(gradcol), CurrentStyle:GetAttribute(gradrot))
Util.LinkDestroyI2C(obj, sig:Connect(update))
end
function Theme.ApplyFrame(obj, options)
local screengui = obj:FindFirstAncestorOfClass("ScreenGui")
assert(not not screengui, "Parent it first, idiot!")
options = options or {}
if options.Border then
if options.Outline then
obj.BorderColor3 = options.Outline
else
local outline = Util.Instance("UIStroke", obj)
outline.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
outline.LineJoinMode = Enum.LineJoinMode.Miter
outline.Thickness = obj.BorderSizePixel
outline.Transparency = 0
outline.Enabled = true
obj:GetPropertyChangedSignal("BorderSizePixel"):Connect(function()
outline.Thickness = obj.BorderSizePixel
end)
_registerColorStuff(outline, "Color", "OutlineColor", "OutlineGradient", "OutlineGradientRotation", false)
end
_registerColorStuff(obj, "BackgroundColor3", "BackgroundColor", "BackgroundGradient", "BackgroundGradientRotation", false)
return
end
obj.BorderSizePixel = 0
if options.Fill then
if options.Outline then
obj.BackgroundColor3 = options.Outline
else
Util.LinkDestroyI2C(obj, Theme.OnChanged("OutlineColor", function(val)
obj.BackgroundColor3 = val
end))
end
return
end
if options.FillText then
Util.LinkDestroyI2C(obj, Theme.OnChanged("TextColor", function(val)
obj.BackgroundColor3 = val
end))
return
end
if obj:IsA("ScrollingFrame") then
obj.TopImage = "rbxasset://textures/ui/Scroll/scroll-middle.png"
obj.MidImage = "rbxasset://textures/ui/Scroll/scroll-middle.png"
obj.BottomImage = "rbxasset://textures/ui/Scroll/scroll-middle.png"
obj.ScrollBarImageTransparency = 0.5
obj.ScrollBarThickness = 3
Util.LinkDestroyI2C(obj, Theme.OnChanged("TextColor", function(val)
obj.ScrollBarImageColor3 = val
end))
end
local corner = Util.Instance("UICorner", obj)
Util.LinkDestroyI2C(obj, Theme.OnChanged("CornerRadius", function(val)
corner.CornerRadius = UDim.new(0, val)
end))
if options.PaddingH or options.PaddingV then
local padding = Util.Instance("UIPadding", obj)
Util.LinkDestroyI2C(obj, Theme.OnChanged("CornerRadius", function(val)
if padding then
if options.PaddingH and options.PaddingV then
padding.PaddingLeft = UDim.new(0, val / 2)
padding.PaddingRight = UDim.new(0, val / 2)
padding.PaddingTop = UDim.new(0, val / 2)
padding.PaddingBottom = UDim.new(0, val / 2)
elseif options.PaddingV then
padding.PaddingLeft = UDim.new(0, 0)
padding.PaddingRight = UDim.new(0, 0)
padding.PaddingTop = UDim.new(0, val)
padding.PaddingBottom = UDim.new(0, val)
else
padding.PaddingLeft = UDim.new(0, val)
padding.PaddingRight = UDim.new(0, val)
padding.PaddingTop = UDim.new(0, 0)
padding.PaddingBottom = UDim.new(0, 0)
end
end
end))
end
local outline = Util.Instance("UIStroke", obj)
outline.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
outline.LineJoinMode = Enum.LineJoinMode.Round
outline.Thickness = 1
outline.Transparency = 0
outline.Enabled = true
if options.Outline then
outline.Color = options.Outline
else
_registerColorStuff(outline, "Color", "OutlineColor", "OutlineGradient", "OutlineGradientRotation", false)
end
if options.Window then
Util.LinkDestroyI2C(obj, Theme.OnChanged("WindowOutlineSize", function(val)
outline.Thickness = val
end))
end
_registerColorStuff(obj, "BackgroundColor3", "BackgroundColor", "BackgroundGradient", "BackgroundGradientRotation", false)
if options.Glow then
assert(screengui == obj.Parent, "Only objects parented to ScreenGui can glow. Sorry!")
local glowcontainer = Util.Instance("Frame", screengui)
Util.LinkDestroyI2I(obj, glowcontainer)
glowcontainer.Active = false
glowcontainer.Interactable = false
glowcontainer.BackgroundTransparency = 1
local alreadyDeferred = true
BindToRenderStep(function()
if alreadyDeferred then
alreadyDeferred = false
local cornerrad = CurrentStyle:GetAttribute("CornerRadius")
local cornerdiam = cornerrad * 2
glowcontainer.AnchorPoint = obj.AnchorPoint
glowcontainer.Position = obj.Position - Util.Vector2ToUDim2Offset((obj.AnchorPoint * 2 - Vector2.one) * cornerrad)
glowcontainer.Size = obj.Size - UDim2.fromOffset(cornerdiam, cornerdiam)
glowcontainer.Visible = obj.Visible
glowcontainer.ZIndex = obj.ZIndex - 2
end
end, glowcontainer, true)
local function deferUpdate()
if alreadyDeferred then return end
alreadyDeferred = true
end
obj:GetPropertyChangedSignal("AnchorPoint"):Connect(deferUpdate)
obj:GetPropertyChangedSignal("Position"):Connect(deferUpdate)
obj:GetPropertyChangedSignal("Size"):Connect(deferUpdate)
obj:GetPropertyChangedSignal("Visible"):Connect(deferUpdate)
obj:GetPropertyChangedSignal("ZIndex"):Connect(deferUpdate)
local glows = {}
for x=0, 2 do
for y=0, 2 do
local glow = Util.Instance("ImageLabel", glowcontainer)
glow.AnchorPoint = Vector2.new(1 - math.min(x, 1), 1 - math.min(y, 1))
glow.Position = UDim2.fromScale(math.max(x - 1, 0), math.max(y - 1, 0))
glow.BackgroundTransparency = 1
glow.Image = GLOW_TEXTURE
glow.ImageRectOffset = Vector2.new(math.min(x, 1) * 256, math.min(y, 1) * 256)
glow.ImageRectSize = Vector2.new(x == 1 and 0 or 256, y == 1 and 0 or 256)
Util.LinkDestroyI2C(obj, Theme.OnChanged("GlowSize", function(glowsize)
glow.Size = UDim2.new(1 - math.abs(x - 1), x == 1 and 0 or glowsize, 1 - math.abs(y - 1), y == 1 and 0 or glowsize)
end))
table.insert(glows, glow)
end
end
local alreadyDeferred = false
local function update()
local glowt = CurrentStyle:GetAttribute("GlowTransparency")
local c = options.Outline or CurrentStyle:GetAttribute("OutlineColor")
local bgc = CurrentStyle:GetAttribute("BackgroundColor")
local h, s, v = bgc:ToHSV()
local h2, s2, v2 = c:ToHSV()
local glc = c
if v > v2 then
glc = bgc
end
local b = math.max(glc.R, glc.G, glc.B)
for _,glow in glows do
glow.ImageColor3 = Color3.new(glc.R / b, glc.G / b, glc.B / b)
glow.ImageTransparency = 1 - (1 - glowt) * b
end
alreadyDeferred = false
end
local function deferUpdate()
if alreadyDeferred then return end
alreadyDeferred = true
task.defer(update)
end
update()
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("OutlineColor"):Connect(deferUpdate))
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("BackgroundColor"):Connect(deferUpdate))
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("GlowTransparency"):Connect(deferUpdate))
end
end
local function _getTextColor(options)
local col = CurrentStyle:GetAttribute("TextColor")
if options.Tint then
local alpha = options.TintAlpha or 0.5
col = col:Lerp(options.Tint, alpha)
end
return col
end
local function _applyTextBoxColors(obj, options)
local col = _getTextColor(options)
obj.TextColor3 = col
local h, s, v = col:ToHSV()
obj.PlaceholderColor3 = Color3.fromHSV(h, s, 0.5 + (v - 0.5) * 0.4)
end
function Theme.ApplyLabel(obj, options)
options = options or {}
if obj:IsA("TextLabel") or obj:IsA("TextButton") then
obj.TextColor3 = _getTextColor(options)
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("TextColor"):Connect(function()
obj.TextColor3 = _getTextColor(options)
end))
end
if obj:IsA("TextBox") then
_applyTextBoxColors(obj, options)
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("TextColor"):Connect(function()
_applyTextBoxColors(obj, options)
end))
end
Util.ForceTextSize(obj)
end

