function Theme.Set(index)
local theme = {
ThemeName = "untitled.theme",

OutlineColor = nil,
BackgroundColor = nil,
TextColor = nil,

GlowTransparency = 0.1,
GlowRadius = 32,
CornerRadius = 5,
WindowOutlineSize = 1,

OutlineGradient = nil,
BackgroundGradient = nil,
OutlineGradientRotation = 0,
BackgroundGradientRotation = 0,

ClickSoundId = "rbxassetid://118806752369227",
ExpandSoundId = "rbxassetid://124993589864467",
CollapseSoundId = "rbxassetid://116080744084010",
MinimizeSoundId = "rbxassetid://7244593699",
RestoreSoundId = "rbxassetid://18148598503",
SwooshSoundId = "rbxassetid://84368229658676",
}
local function processtable(t)
if getmetatable(t) ~= nil then return end
if typeof(t.Name) == "string" then
theme.ThemeName = t.Name
end
if typeof(t.Fore) == "Color3" then
theme.OutlineColor = t.Fore
end
if typeof(t.Back) == "Color3" then
theme.BackgroundColor = t.Back
end
if typeof(t.Text) == "Color3" then
theme.TextColor = t.Text
end
if typeof(t.Fore) == "string" then
theme.OutlineColor = Color3.fromHex(t.Fore)
end
if typeof(t.Back) == "string" then
theme.BackgroundColor = Color3.fromHex(t.Back)
end
if typeof(t.Text) == "string" then
theme.TextColor = Color3.fromHex(t.Text)
end
if typeof(t.Glow) == "number" then
theme.GlowTransparency = 1 - math.clamp(t.Glow, 0, 1)
end
if typeof(t.GlowRadius) == "number" then
theme.GlowRadius = math.max(math.floor(t.GlowRadius), 1)
end
if typeof(t.Corner) == "number" then
theme.CornerRadius = math.max(math.floor(t.Corner), 0)
end
if typeof(t.WindowOutline) == "number" then
theme.WindowOutlineSize = math.max(math.floor(t.WindowOutline), 0)
end
if typeof(t.ForeGrad) == "string" then
theme.OutlineGradient = t.ForeGrad
end
if typeof(t.BackGrad) == "string" then
theme.BackgroundGradient = t.BackGrad
end
if typeof(t.ForeGradRot) == "number" then
theme.OutlineGradientRotation = t.ForeGradRot
end
if typeof(t.BackGradRot) == "number" then
theme.BackgroundGradientRotation = t.BackGradRot
end
if typeof(t.SndClick) == "string" then
theme.ClickSoundId = t.SndClick
end
if typeof(t.SndExpand) == "string" then
theme.ExpandSoundId = t.SndExpand
end
if typeof(t.SndCollapse) == "string" then
theme.CollapseSoundId = t.SndCollapse
end
if typeof(t.SndRestore) == "string" then
theme.RestoreSoundId = t.SndRestore
end
if typeof(t.SndMinimize) == "string" then
theme.MinimizeSoundId = t.SndMinimize
end
if typeof(t.SndSwoosh) == "string" then
theme.SwooshSoundId = t.SndSwoosh
end
end
if typeof(index) == "table" then
processtable(index)
elseif typeof(index) == "string" then
local s, index = pcall(HttpService.JSONDecode, HttpService, index)
if s and index then
processtable(index)
end
elseif BuiltinThemes[index] then
processtable(BuiltinThemes[index])
end
for _,k in ThemeProperties do Theme[k] = theme[k] end
Theme.Update(0)
end
function Theme.Serialize()
local ouwh = {}
for _,k in ThemeProperties do
local k2 = ThemePropertiesMap[k]
local v = Theme[k]
if typeof(v) == "Color3" then
v = v:ToHex()
elseif type(v) == "string" then

elseif type(v) == "number" then
if k2 == "Glow" then
v = 1 - v
end
elseif type(v) == "nil" then

else
warn("cannot serialize theme: unexpected type " .. typeof(v))
return
end
ouwh[k2] = v
end
return HttpService:JSONEncode(ouwh)
end

local SoundsParent = Util.CreateScreenGui()
local soundCard = {}
function Theme.PlaySound(name)
if Theme.SoundMuted then return end
local snd = soundCard[name]
if not snd then
snd = Util.Instance("Sound", SoundsParent)
snd.Name = name
snd.PlaybackSpeed = 1
snd.Volume = 1
soundCard[name] = snd
end
if name == "CLICK" then
snd.SoundId = Theme.ClickSoundId
end
if name == "EXPAND" then
snd.SoundId = Theme.ExpandSoundId
end
if name == "RESTORE" then
snd.SoundId = Theme.RestoreSoundId
end
if name == "COLLAPSE" then
snd.SoundId = Theme.CollapseSoundId
end
if name == "SWOOSH" then
snd.SoundId = Theme.SwooshSoundId
end
if name == "MINIMIZE" then
snd.SoundId = Theme.MinimizeSoundId
end
snd:Play()
end

BindToRenderStep(Theme.Update)

return Theme
