local minutes = math.floor(seconds / 60) % 60
local seconds = seconds % 60
return string.format("%02d:%02d:%02d.%02d", hours, minutes, seconds, (seconds % 1) * 100)
end

local service_cache = {}
function Util.Service(name)
if service_cache[name] then
