service_cache[name] = service
return service
end

function Util.RandomString(length)
length = length or math.random(32, 256)
local str = ""
for _=1, length do
str ..= string.char(math.random(32, 126))
end
return str
end

function Util.DeepcopyTable(t)
local c = {}
for k, v in t do
if type(v) == "table" then
v = Util.DeepcopyTable(v)
end
c[k] = v
end
return c
end

function Util.ShuffleArray(t)
local c = table.clone(t)
for i=1, #c do
local j = math.random(#c)
c[i], c[j] = c[j], c[i]
end
return c
end

local function IsSerializable(t)
local tt = type(t)
if tt == "userdata" then return false end
if tt == "table" then
if getmetatable(t) ~= nil then return false end
local types = nil
for k,v in t do
if not IsSerializable(k) then return false end
if not IsSerializable(v) then return false end
local kt = type(k)
if types ~= nil then
if kt ~= types then return false end
else
types = kt
end
end
return true
end
if tt == "nil" or tt == "string" or tt == "number" or tt == "boolean" then return true end
return false
end
Util.IsSerializable = IsSerializable

function Util.Traceback(label, message, topfunc, level)
local err = label .. " - " .. tostring(message) .. "\n\tStack Begin"
level += 1
while true do
local s, l, n, f = debug.info(level, "slnf")
if not l then break end
if l > 0 then
s = (#s > 0 and s) or "LocalScript"
n = (#n > 0 and n) or "(anonymous)"
err ..= "\n\tScript '" .. s .. "', Line " .. l .. ", Function " .. n
end
if f == topfunc then break end
level += 1
end
err ..= "\n\tStack End"
return err
end

function Util.IsMissing(func)
