	["BlaaBlaaReanim/System/runtime/steve110/main/workspace_tabs.lua"] = [=[
-- Retained pages: closing a tab removes its button, never its page or controls.
local Tabs = {}

function Tabs.new(context)
    local Util, Window, Theme = context.Util, context.Window, context.Theme
    local textFont = context.Font or Enum.Font.Code
    local Workspace = {Roots = {}, Owners = setmetatable({}, {__mode = "k"}), Pages = {}, Enabled = false}
    local bar = Util.Instance("ScrollingFrame", Window.Content)
    bar.Name = "RoserikaTabs"
    bar.Position = UDim2.fromOffset(5.5, 4)
    bar.Size = UDim2.new(1, -13, 0, 32)
    bar.BackgroundTransparency = 1
    bar.BorderSizePixel = 0
    bar.AutomaticCanvasSize = Enum.AutomaticSize.X
    bar.CanvasSize = UDim2.new()
    bar.ScrollingDirection = Enum.ScrollingDirection.X
    bar.ScrollBarThickness = 2
    bar.ZIndex = 5
    bar.Interactable = false
    bar.Visible = false
    local padding = Util.Instance("UIPadding", bar)
    padding.PaddingLeft, padding.PaddingRight = UDim.new(0, 1.5), UDim.new(0, 1.5)
    padding.PaddingTop, padding.PaddingBottom = UDim.new(0, 1), UDim.new(0, 2)
    local layout = Util.Instance("UIListLayout", bar)
    layout.FillDirection = Enum.FillDirection.Horizontal
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 5)
    local slot = Util.Instance("Frame", Window.Content)
    slot.Name = "RetainedPages"
    slot.Position = UDim2.fromOffset(0, 40)
    slot.Size = UDim2.new(1, 0, 1, -40)
    slot.BackgroundTransparency = 1
    slot.ClipsDescendants = true
    if context.Intro then context.Intro.Parent = slot end
    Workspace.Bar, Workspace.Slot = bar, slot

    local function snapshot(page)
        if not page or not page.Parent then return end
        local state = Workspace.Pages[page]
        if not state then return end
        -- Hidden/rebuilt lists can temporarily clamp their live canvas to zero.
        -- Keep the last visible position until that page is opened again.
        if state.Scroll and page.Visible == false then return end
        state.Scroll = state.Scroll or setmetatable({}, {__mode = "k"})
        if page:IsA("ScrollingFrame") then state.Scroll[page] = page.CanvasPosition end
        for _, child in ipairs(page:GetDescendants()) do
            if child:IsA("ScrollingFrame") then state.Scroll[child] = child.CanvasPosition end
        end
    end
    local function restore(page)
        local state = Workspace.Pages[page]
        if not state or not state.Scroll then return end
        for frame, position in pairs(state.Scroll) do
            if frame.Parent then frame.CanvasPosition = position end
        end
        -- AutomaticCanvasSize can settle after a collection was rebuilt.
        task.defer(function()
            if Workspace.CurrentPage ~= page then return end
            for frame, position in pairs(state.Scroll) do
                if frame.Parent then frame.CanvasPosition = position end
            end
        end)
    end
    function Workspace.Track(page)
        if Workspace.Pages[page] then return page end
        Workspace.Pages[page] = {}
        page.Parent = slot
        page.Visible, page.Interactable = false, false
        page.AnchorPoint = Vector2.new(0.5, 0.5)
        page.Position = UDim2.new(0.5, 0, 0.5, 0)
        page.Size = UDim2.new(1, 0, 1, 0)
        page.ZIndex = 1
        page.Destroying:Once(function()
            local state, owner = Workspace.Pages[page], Workspace.Owners[page]
            local fallback = state and state.Parent or (owner and owner.Page)
            if not fallback or fallback == page or not fallback.Parent then
                fallback = Workspace.Main and Workspace.Main.Page
            end
            if owner and owner.Current == page then owner.Current = fallback end
            Workspace.Pages[page], Workspace.Owners[page] = nil, nil
            if Workspace.CurrentPage == page then
                Workspace.CurrentPage = nil
                task.defer(function()
                    if not Workspace.Disposed and not Workspace.CurrentPage and fallback
                        and fallback ~= page and fallback.Parent then Workspace.Open(fallback) end
                end)
            end
        end)
        return page
    end
    function Workspace.ResolvePage(instance)
        -- Settings canvases are embedded controls, not independent pages.
        -- Never reparent/Track one just to navigate to its Advanced page.
        while instance do
            if Workspace.Pages[instance] then return instance end
            instance = instance.Parent
        end
        return nil
    end
    function Workspace.SnapshotAll()
        for page in pairs(Workspace.Pages) do snapshot(page) end
    end
    function Workspace.RestoreAll()
        for page in pairs(Workspace.Pages) do restore(page) end
    end
    function Workspace.RestoreCurrentScroll()
        restore(Workspace.CurrentPage)
    end
    function Workspace.SaveCurrentScroll()
        snapshot(Workspace.CurrentPage)
    end
    local transitionSerial, transitionTweens, transitionConnections = 0, {}, {}
    local pendingDisposal
    local function cancelTransition(keepPage)
        transitionSerial += 1
        for _, connection in ipairs(transitionConnections) do connection:Disconnect() end
        table.clear(transitionConnections)
        for _, tween in ipairs(transitionTweens) do tween:Cancel() end
        table.clear(transitionTweens)
        local disposable = pendingDisposal
        pendingDisposal = nil
        if disposable and disposable ~= keepPage and disposable.Parent then disposable:Destroy() end
    end
    local function display(root, page, direction, disposePage)
        local outgoing = Workspace.CurrentPage
        direction = direction or (Workspace.Main and page == Workspace.Main.Page and outgoing ~= page and -1 or 1)
        snapshot(Workspace.CurrentPage)
        cancelTransition(page)
        Workspace.Current, Workspace.CurrentPage = root, page
        root.Current = page
        page.AnchorPoint = Vector2.new(0.5, 0.5)
        page.Position = UDim2.new(0.5, 0, 0.5, 0)
        for candidate in pairs(Workspace.Pages) do
            if candidate.Parent then
                candidate.Visible = candidate == page and Workspace.Enabled
                candidate.Interactable = candidate == page and Workspace.Enabled
            end
        end
        for _, entry in pairs(Workspace.Roots) do
            if entry.Button then
                entry.Button.BackgroundTransparency = entry == root and 0.05 or 0.48
                entry.Label.TextTransparency = entry == root and 0 or 0.18
                entry.Stroke.Transparency = entry == root and 0.1 or 0.68
            end
        end
        restore(page)
        local function retireOutgoing()
            if outgoing and outgoing.Parent and outgoing ~= Workspace.CurrentPage then
                outgoing.Visible, outgoing.Interactable = false, false
                outgoing.Position = UDim2.new(.5, 0, .5, 0)
            end
            if disposePage and disposePage.Parent and disposePage ~= Workspace.CurrentPage then disposePage:Destroy() end
            if pendingDisposal == disposePage then pendingDisposal = nil end
        end
        if context.TweenService and Workspace.Enabled and outgoing ~= page and outgoing and outgoing.Parent then
            local serial = transitionSerial
            local completed = 0
            pendingDisposal = disposePage
            local function finish()
                completed += 1
                if completed == 2 then
                    table.clear(transitionTweens)
                    table.clear(transitionConnections)
                end
            end
            outgoing.Visible, outgoing.Interactable = true, false
            outgoing.Position = UDim2.new(.5, 0, .5, 0)
            page.Position = UDim2.new(.5 + direction, 4 * direction, .5, 0)
            page.Interactable = false
            local leave = context.TweenService:Create(outgoing, TweenInfo.new(.24, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Position = UDim2.new(.5 - direction, -4 * direction, .5, 0)})
            local enter = context.TweenService:Create(page, TweenInfo.new(.24, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Position = UDim2.new(.5, 0, .5, 0)})
            table.insert(transitionTweens, leave)
            table.insert(transitionTweens, enter)
            table.insert(transitionConnections, leave.Completed:Once(function(state)
                if serial ~= transitionSerial or state == Enum.PlaybackState.Cancelled then return end
                retireOutgoing()
                finish()
            end))
            table.insert(transitionConnections, enter.Completed:Once(function(state)
                if serial ~= transitionSerial or state == Enum.PlaybackState.Cancelled then return end
                if page.Parent and Workspace.CurrentPage == page then page.Interactable = Workspace.Enabled end
                finish()
            end))
            leave:Play()
            enter:Play()
        else
            retireOutgoing()
        end
    end
    local function makeButton(root)
        if root.Button then return end
        local button = Util.Instance("Frame", bar)
        button.Name = root.Key
        button.LayoutOrder = root.Order
        button.Size = UDim2.fromOffset(math.max(88, #root.Name * 8 + (root.Permanent and 14 or 39)), 27)
        button.BackgroundColor3 = Theme and Theme.Current:GetAttribute("BackgroundColor") or Color3.new(0, 0, 0)
        button.BackgroundTransparency = 0.48
        button.BorderSizePixel = 0
        button.ZIndex = 6
        local stroke
        if Theme then
            Theme.ApplyFrame(button)
            stroke = button:FindFirstChildOfClass("UIStroke")
        end
        if not stroke then
            Util.Instance("UICorner", button).CornerRadius = UDim.new(0, 5)
            stroke = Util.Instance("UIStroke", button)
            stroke.Color, stroke.Thickness = Color3.new(1, 1, 1), 1
        end
        local label = Util.Instance("TextButton", button)
        label.Size = UDim2.new(1, root.Permanent and 0 or -24, 1, 0)
        label.BackgroundTransparency = 1
        label.BorderSizePixel, label.AutoButtonColor = 0, false
        label.Font, label.TextSize = textFont, 14
        label.TextColor3, label.Text = Color3.new(1, 1, 1), root.Name
        label.ZIndex = 7
        if Theme then Theme.ApplyLabel(label) end
        root.Button, root.Label, root.Stroke = button, label, stroke
        label.Activated:Connect(function() Workspace.Select(root.Key) end)
        if not root.Permanent then
            local close = Util.Instance("TextButton", button)
            close.Name = "CloseTab"
            close.AnchorPoint = Vector2.new(1, 0)
            close.Position = UDim2.new(1, 0, 0, 0)
            close.Size = UDim2.new(0, 24, 1, 0)
            close.BackgroundTransparency = 1
            close.BorderSizePixel = 0
            close.Text, close.TextSize, close.Font = "×", 18, textFont
            close.TextColor3, close.ZIndex = Color3.new(1, 1, 1), 8
            if Theme then Theme.ApplyLabel(close) end
            close.Activated:Connect(function() Workspace.Close(root.Key) end)
        end
        root.Open = true
    end
    function Workspace.RegisterRoot(key, name, page, color, permanent)
        Workspace.Track(page)
        local root = {Key = key, Name = name, Page = page, Current = page, Color = color,
            Permanent = permanent == true, Order = #Workspace.Order + 1}
        Workspace.Roots[key], Workspace.Owners[page] = root, root
        table.insert(Workspace.Order, root)
        if root.Permanent then
            Workspace.Main = root
            makeButton(root)
            display(root, page)
        end
        return root
    end
    function Workspace.Select(key)
        local root = Workspace.Roots[key]
        if not root then return false end
        makeButton(root)
        -- Mainframe is the workspace root, not a retained closable section.
        local page = root.Permanent and root.Page or root.Current
        if not page or not page.Parent then page = root.Page end
        display(root, page)
        return true
    end
    function Workspace.Open(page, parentPage)
        Workspace.Track(page)
        local root = Workspace.Owners[page]
        if root and page == root.Page then
            -- A main-menu entry reopens the last subpage, including a closed tab.
            return Workspace.Select(root.Key)
        end
        parentPage = Workspace.ResolvePage(parentPage) or parentPage
        root = root or Workspace.Owners[parentPage] or Workspace.Main
        assert(root, "page opened before Mainframe registration")
        Workspace.Owners[page] = root
        Workspace.Pages[page].Parent = parentPage
        makeButton(root)
        display(root, page)
        return true
    end
    function Workspace.Back(page, parentPage, destroyPage)
        parentPage = Workspace.ResolvePage(parentPage) or parentPage
        local owner = Workspace.Owners[page]
        local parentOwner = Workspace.Owners[parentPage] or Workspace.Main
        if owner == parentOwner then owner.Current = parentPage end
        makeButton(parentOwner)
        display(parentOwner, parentPage, -1, destroyPage and page ~= parentPage and page or nil)
    end
    function Workspace.Close(key)
        local root = Workspace.Roots[key]
        if not root or root.Permanent then return false end
        snapshot(root.Current)
        root.Open = false
        if root.Button then root.Button:Destroy() end
        root.Button, root.Label, root.Stroke = nil, nil, nil
        if Workspace.Current == root then
            local nextRoot = Workspace.Main
            for _, candidate in ipairs(Workspace.Order) do
                if candidate.Open then nextRoot = candidate end
            end
            Workspace.Select(nextRoot.Key)
        end
        return true
    end
    function Workspace.SetEnabled(enabled, keepSavedScroll)
        if enabled ~= true and not keepSavedScroll then snapshot(Workspace.CurrentPage) end
        cancelTransition(Workspace.CurrentPage)
        if Workspace.CurrentPage and Workspace.CurrentPage.Parent then Workspace.CurrentPage.Position = UDim2.new(.5, 0, .5, 0) end
        Workspace.Enabled = enabled == true
        bar.Interactable = Workspace.Enabled
        bar.Visible = Workspace.Enabled
        if Workspace.Enabled then restore(Workspace.CurrentPage) end
        for page in pairs(Workspace.Pages) do
            page.Visible = page == Workspace.CurrentPage and Workspace.Enabled
            page.Interactable = page.Visible
        end
        if Workspace.OnEnabledChanged then Workspace.OnEnabledChanged(Workspace.Enabled) end
    end
    Workspace.Order = {}
    (Window.Main or Window.Content).Destroying:Once(function()
        Workspace.Disposed = true
        cancelTransition()
    end)
    return Workspace
end

return Tabs
