-- Keep all distinct setters. A compatibility alias can exist but be stubbed
-- by an executor, so a failed long-form call falls through to the short or
-- underscored implementation before the joint is declared unsupported.
Util.HiddenPropertySetters = {}
do
	local seen = {}
	local function register(name, setter)
		if not ismissing(setter) and not seen[setter] then
			seen[setter] = true
			table.insert(Util.HiddenPropertySetters, { Name = name, Set = setter })
		end
	end
	register(Util.HiddenPropertySetterSource, sethiddenproperty)
	register("sethiddenprop", sethiddenprop)
	register("set_hidden_property", set_hidden_property)
end
Util.HiddenPropertyGetter = gethiddenproperty
Util.TrySetHiddenProperty = function(instance, property, value)
	local lastError = "no hidden-property setter is available"
	local submitted
	local jointChannel = typeof(instance) == "Instance" and instance:IsA("Motor6D")
		and (property == "ReplicateCurrentOffset6D" or property == "ReplicateCurrentAngle6D")
	for _, candidate in Util.HiddenPropertySetters do
		local success, result = pcall(candidate.Set, instance, property, value)
		if success then
			-- sUNC's boolean says whether the property is hidden, not whether
			-- assigning it succeeded. A false return can be a successful write.
			local matches, verified = true, false
			if type(Util.HiddenPropertyGetter) == "function" then
				local readOk, actual = pcall(Util.HiddenPropertyGetter, instance, property)
				if readOk then
					verified = true
					matches = actual == value
					if typeof(actual) == "Vector3" and typeof(value) == "Vector3" then
						matches = (actual - value).Magnitude < 0.00001
					end
				end
			end
			if matches then return true, candidate.Name, verified end
			lastError = candidate.Name .. " did not retain the requested value"
			-- STEVE submits these two channels through the setter. Immediate
			-- readback is useful diagnostics, but cannot veto a non-throwing
			-- replication submission. Prefer an alias with matching readback.
			if jointChannel then submitted = submitted or candidate.Name end
		else
			lastError = tostring(result)
		end
	end
	if submitted then return true, submitted, false, lastError end
	return false, lastError
end

