local function ToolTouchTarget(rootPart, targetRecord)
	local tool = rootPart and rootPart.Parent and rootPart.Parent:FindFirstChildOfClass("Tool")
	local targetPart = ResolveDamageTarget(targetRecord and targetRecord.Target)
	local handle = tool and tool:FindFirstChild("Handle")
	if not targetPart or not handle or type(firetouchinterest) ~= "function" then
		return false
	end
	tool:Activate()
	firetouchinterest(targetPart, handle, 1)
	firetouchinterest(targetPart, handle, 0)
	firetouchinterest(handle, targetPart, 1)
	firetouchinterest(handle, targetPart, 0)
	return true
end

local HTTP_TOUCH_ONLY = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
-- One global mobile request slot made every community asset serialize. Two jobs
-- is still conservative enough for Delta-class mobile executors while allowing
-- the next module/image to make progress during filesystem/customasset work.
local HTTP_MAX_ACTIVE = HTTP_TOUCH_ONLY and 2 or 4
local HTTP_CALL_TIMEOUT = HTTP_TOUCH_ONLY and 8 or 12
local HTTP_ACTIVE = 0
local CONTENT_DOWNLOAD_ACTIVE = 0

local function HttpBodyIsUsable(body)
	if type(body) ~= "string" or #body == 0 then
		return false
	end
	local prefix = body:sub(1, 1024):gsub("^\239\187\191", ""):lower():match("^%s*(.*)")
	return prefix ~= "" and not prefix:match("^<!doctype html") and not prefix:match("^<html")
		and not prefix:match("^<head") and not prefix:match("^<body")
		and not prefix:match("^404[:%s]+not found")
end

local function RunHttpCall(label, callback)
	local result = {
		Done = false,
	}
	local worker = task.spawn(function()
		result.Ok, result.Value = pcall(callback)
		result.Done = true
	end)
	local deadline = os.clock() + HTTP_CALL_TIMEOUT
	repeat
		task.wait()
	until result.Done or os.clock() >= deadline

	if not result.Done then
		pcall(task.cancel, worker)
		return false, label .. " timed out after " .. HTTP_CALL_TIMEOUT .. "s", true
	end
	if not result.Ok then
		return false, label .. " failed: " .. tostring(result.Value), false
	end
	return true, result.Value, false
end

local function AcquireHttpSlot(background)
    -- One mobile background slot at most; keep a slot available to selected dances.
    while HTTP_ACTIVE >= (background and math.max(1, HTTP_MAX_ACTIVE - 1) or HTTP_MAX_ACTIVE)
        or (background and CONTENT_DOWNLOAD_ACTIVE > 0) do
		task.wait()
	end
	HTTP_ACTIVE += 1
end

local function ReleaseHttpSlot()
	HTTP_ACTIVE = math.max(HTTP_ACTIVE - 1, 0)
end

local function HttpFetchBody(url, headers, attempts, background)
	url = tostring(url)
	attempts = math.clamp(tonumber(attempts) or 2, 1, 2)
	local needsHeaders = type(headers) == "table" and next(headers) ~= nil
    if not needsHeaders then attempts = 1 end -- each public transport is tried once per source
    if needsHeaders and type(request) ~= "function" then return nil, "request transport unavailable for headers" end

	local function ParseRequestResponse(response)
		local status = type(response) == "table" and (
			tonumber(response.StatusCode)
			or tonumber(response.Status)
			or tonumber(response.status_code)
			or tonumber(response.status)
		) or nil
		local responseBody = type(response) == "table" and (
			response.Body
			or response.body
			or response.ResponseBody
			or response.responseBody
		) or (type(response) == "string" and response or nil)
		local success
		if type(response) == "table" then success = response.Success end
		if success == nil and type(response) == "table" then
			success = response.success
		end
		if success ~= false and HttpBodyIsUsable(responseBody)
			and ((status and status >= 200 and status < 300) or (status == nil and success ~= false))
		then
			return responseBody
		end
        if status then
            local detail=status==404 and "upstream file not found"
                or (status==401 or status==403) and "access denied or rate limited"
                or status==429 and "rate limited"
                or status>=500 and "upstream service error"
                or status>=200 and status<300 and "empty or invalid response body"
                or "request rejected"
            return nil,"HTTP "..status..": "..detail
        end
        return nil,"request returned no HTTP status; "..(responseBody=="" and "empty body" or "invalid response")
	end

    local function FetchPublicSequentially()
        local errors = {}
        -- HttpGet bytes -> writefile path, not two downloads of the same asset.
        local ok, body = RunHttpCall("HttpGet", function() return game:HttpGet(url) end)
        if ok and HttpBodyIsUsable(body) then return body end
        -- Never dump the entire HTML/error document into the mobile console.
        table.insert(errors, ok and "HttpGet returned an empty/HTML/error body" or tostring(body):sub(1, 240))
        if type(request) == "function" then
            local requestOk, response = RunHttpCall("request", function()
                return request({Method = "GET", Url = url})
            end)
            if requestOk then
                local parsed, reason = ParseRequestResponse(response)
                if parsed then return parsed end
                table.insert(errors, tostring(reason))
            else table.insert(errors, tostring(response)) end
        end
        return nil, table.concat(errors, " / ")
    end

	AcquireHttpSlot(background)
	local ran, body, failure = pcall(function()
		for attempt = 1, attempts do
			local result, reason
			if needsHeaders then
				-- Header-sensitive calls cannot use HttpGet. Keep one bounded request.
				local okRequest, response, didTimeout = RunHttpCall("request", function()
					return request({ Method = "GET", Url = url, Headers = headers })
				end)
				if okRequest then
					result, reason = ParseRequestResponse(response)
				else
					reason = tostring(response)
					if didTimeout then reason = "request timed out" end
				end
			else
				-- Public assets use one preferred transport, then one fallback.
				-- No duplicate binary transfer; failed sources remain retryable.
				result, reason = FetchPublicSequentially()
			end
			if result then return result, nil end
			failure = reason
			if attempt < attempts then task.wait(0.2 * attempt) end
		end
		return nil, failure or "no HTTP transport"
	end)
	ReleaseHttpSlot()
	if not ran then return nil, "fetcher crashed: " .. tostring(body) end
	return body, failure
end

