		"letriangul.graphic.png",
	}
	local function isUsable(name)
		local readable, bytes = pcall(readfile, "BlaaBlaaReanim/Assets/" .. name)
		return readable and type(bytes) == "string" and #bytes > 0
	end
	local function download(name)
		if isUsable(name) then
			return true
		end
		-- BlaaBlaa hosts its extra music/graphics in its own uiassets folder;
		-- the audited Uhhhhhh revision remains the fallback for stock assets.
		local body, reason
		for _, url in {
			"https://raw.githubusercontent.com/JustAMaleScripts/BlaaBlaa/main/uiassets/" .. name,
			"https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/"
				.. STEVE_AUDITED_REVISION .. "/uiassets/" .. name,
		} do
			body, reason = HttpFetchBody(url, nil, 1, true)
			if body then break end
		end
		if not body then
			warn("UI asset " .. name .. ": " .. tostring(reason))
			return false
		end
		local wrote, failure = pcall(function()
			writefile("BlaaBlaaReanim/Assets/" .. name, body)
			assert(isUsable(name), "asset write verification failed")
		end)
		if not wrote then
			warn("UI asset " .. name .. ": " .. tostring(failure))
		end
		return wrote
	end

	-- A fresh phone used to block here while it pulled every optional UI song.
	-- UI music and intro art are cosmetic, so none of them may hold up module
	-- loading. They fill the cache only after the usable dances are available.
	task.spawn(function()
		repeat
			task.wait(0.1)
		until IsUhhhhhhFullyLoaded or not _G.UhhhhhhLoaded
		if not _G.UhhhhhhLoaded then
			return
		end

		local remaining = 0
		for _, name in AllFileNames do
			if not isUsable(name) then
				remaining += 1
			end
		end
		local total = remaining
		local failed = 0
		local completed = 0
		local queue = {}
		for _, name in AllFileNames do
			if not isUsable(name) then table.insert(queue, name) end
		end
		local cursor = 1
		local workers = HTTP_TOUCH_ONLY and 1 or 2
		local running = math.min(workers, #queue)
		for _ = 1, running do
			task.spawn(function()
				while true do
					local index = cursor
					cursor += 1
					local name = queue[index]
					if not name then break end
					if not download(name) then failed += 1 end
					completed += 1
					Util.UINotify(("Caching UI assets %d/%d..."):format(completed, total), 0.15)
				end
				running -= 1
			end)
		end
		repeat task.wait(0.1) until running <= 0
		if failed == 0 then
			SaveData.CDNVersion = CDNVersion
		end
		UIAssetsReady:Fire(failed == 0, failed)
		-- Additional music is optional and never delays the usable interface or
		-- the first cached track. Errors remain local to these cosmetic downloads.
		local rosOk, rosFailed = pcall(function()
			return Steve110.Require("main/roserika_music").Cache({Fetch = HttpFetchBody})
		end)
		UIAssetsReady:Fire(rosOk and rosFailed == 0, rosOk and rosFailed or 1)
	end)
end

local LocalAssetIds = {}
local function GetLocalAssetId(path)
	if LocalAssetIds[path] then
		return LocalAssetIds[path]
	end
	local exists, value = pcall(isfile, path)
	if not (exists and value) then
		return ""
	end
	for attempt = 1, 4 do
		local registered, id = pcall(getcustomasset, path)
		if registered and type(id) == "string" and #id > 0 then
			LocalAssetIds[path] = id
			return id
		end
		if attempt < 4 then
			task.wait(0.05 * attempt)
		end
	end
	return ""
end

Util.GetCDNAsset = function(filename)
	local path = "BlaaBlaaReanim/Assets/" .. filename
	return GetLocalAssetId(path)
end

Util.MakeTriforce = function(tris, color, dur)
	dur = dur or 8
	local function CreateTriangle(parent, radius, width, rotation, color)
		local height = (math.sqrt(3) / 2) * width
		local pivot = Util.Instance("Frame", parent)
		pivot.AnchorPoint = Vector2.new(0.5, 0.5)
		pivot.Position = UDim2.new(0.5, 0, 0.5, 0)
		pivot.Size = UDim2.new(1, 0, 1, 0)
		pivot.BackgroundTransparency = 1
		pivot.BorderSizePixel = 0
		pivot.Rotation = rotation
		local tri = Util.Instance("ImageLabel", pivot)
		tri.AnchorPoint = Vector2.new(0.5, 1)
		tri.Position = UDim2.new(0.5, 0, 0.5 - radius, 0)
		tri.Size = UDim2.new(width, 0, height, 0)
		tri.BackgroundTransparency = 1
		tri.BorderSizePixel = 0
		tri.Image = Util.GetCDNAsset("letriangul.graphic.png")
		local grey = math.max(color.R, color.G, color.B) * 0.5
		tri.ImageColor3 = Color3.new(grey, grey, grey)
		TweenService:Create(tri, TweenInfo.new(dur, Enum.EasingStyle.Linear), {
			ImageColor3 = color,
		}):Play()
	end
	local radius = 0.1
	local pivot = Util.Instance("Frame")
	pivot.AnchorPoint = Vector2.new(0.5, 0.5)
	pivot.Position = UDim2.new(0.5, 0, 0.5, 0)
	pivot.BackgroundTransparency = 1
	pivot.BorderSizePixel = 0
	local width = 2 * radius * math.sin(math.pi / tris) * 2
	for i = 1, tris do
		CreateTriangle(pivot, radius, width, (i / tris) * 360, color)
	end
	return pivot
end
Util.MakeText = function(text)
	text = text:upper()
	local ls = "BCDEIKOPQRSTUVYZ\\_`N^MJ"
	local lt = ""
	-- !, ", #, $, %, &, ', (, ), *, +, ,, -, ., /
	lt ..= "DDDDD@DFF@@@@@FSFSFSF@@@@@@@@@@@@@@EMMUKKTDD@@@@@DEEEEEDDBBBBBD@@@@@@@@@@@@@@@@@@@DE@@@G@@@@@@@@@DABBDEEI"
	-- numbers
	lt ..= "GJJJJJGDVDDDDSGJAGIISRAAGAARWJJSAAASIIRAARGIIRJJGSAABBDDGJJGJJGGJJHAAG"
	-- :, ;, <, =, >, ?, @
	lt ..= "@DD@DD@@DD@DE@@BDEDB@@@G@G@@@EDBDE@GJABD@D@@@@@@@"
	-- capital letters
	lt ..= "DFJSJJJRJJRJJRGJIIIJGRJJJJJRSIIRIISSIIRIIIHIILJJHJJJSJJJGDDDDDGAAAAAJHJKMOMKJIIIIIISJQNJJJJJJPNLJJGJJJJJGRJJRIIIGJJJNGCRJJRMKJGJIGAJGSDDDDDDJJJJJJGJJJJJFDJJJNQJJJJFDFJJJJFDDDDSABDEIS"
	local pixs = {}
	local totalsize = 0
	for i = 0, 6 do
		local row = {}
		for j = 1, text:len() do
			local c = text:byte(j, j)
			local w = 0
			if c ~= 0x20 then
				local k = (c - 33) * 7 + i
				w = lt:byte(k + 1, k + 1)
				if w ~= nil and w > 64 then
					w = ls:byte(w - 64, w - 64) - 65
				else
					w = 0
				end
			end
			for k = 0, 5 do
				local h = (j - 1) * 6 + (4 - k)
				totalsize = math.max(totalsize, h + 1)
				local p = (w // math.pow(2, k)) % 2
				if p > 0 then
					row[h] = true
				end
			end
		end
		pixs[i] = row
	end
	local pivot = Util.Instance("Frame")
	pivot.AnchorPoint = Vector2.new(0.5, 0.5)
	pivot.Position = UDim2.new(0.5, 0, 0.5, 0)
	pivot.Size = UDim2.new(0, totalsize, 0, 7)
	pivot.BackgroundTransparency = 1
	pivot.BorderSizePixel = 0
	for i = 0, 6 do
		local row = pixs[i]
		local olde = nil
		local olds = 0
		for j = 0, totalsize - 1 do
			local pix = row[j]
			if pix == true then
				if olde ~= nil then
					olds += 1
					olde.Size = UDim2.new(olds / totalsize, 0, 1 / 7, 0)
				else
					olde = Util.Instance("Frame", pivot)
					olde.AnchorPoint = Vector2.new(0, 0)
					olde.Position = UDim2.new(j / totalsize, 0, i / 7, 0)
					olde.Size = UDim2.new(1 / totalsize, 0, 1 / 7, 0)
					olde.BackgroundTransparency = 1
					olde.BorderSizePixel = 0
					olds = 1
				end
			else
				olde = nil
				olds = 0
			end
		end
	end
	return pivot
end
