local DevSignalMethods = {}
DevSignalMethods.__index = DevSignalMethods
local function DevSignal()
	return setmetatable({ Connections = {} }, DevSignalMethods)
end
function DevSignalMethods:Connect(callback)
	local signal = self
	local obj = { Connected = true }
	function obj:Disconnect()
		if not self.Connected then return end
		self.Connected = false
		local i = table.find(signal.Connections, self)
		if i then table.remove(signal.Connections, i) end
	end
	obj.Callback = callback
	table.insert(signal.Connections, obj)
	return obj
end
function DevSignalMethods:Fire(...)
	for _, obj in self.Connections do
		if obj.Connected then task.spawn(obj.Callback, ...) end
	end
end

local function DevBindToRenderStep(callback, linkToInstance, alwaysRun)
	local conn
	conn = RunService.PreRender:Connect(function(dt)
		if linkToInstance and not linkToInstance.Parent then
			conn:Disconnect()
			return
		end
		if alwaysRun or not linkToInstance or Util.IsGuiVisible(linkToInstance) then
			callback(os.clock(), dt)
		end
	end)
	if linkToInstance then Util.LinkDestroyI2C(linkToInstance, conn) end
	return conn
end

