local function SetUITheme(index)
	local customIndex = #DevTheme.Themes + 1
	if index == customIndex then
		local custom = nil
		if type(_G.UhhhhhhTheme) == "table" and getmetatable(_G.UhhhhhhTheme) == nil then
			custom = _G.UhhhhhhTheme
			SaveData.UIThemeUserDefined = custom
		elseif type(SaveData.UIThemeUserDefined) == "table" then
			custom = SaveData.UIThemeUserDefined
		end
		DevTheme.Set(custom or 1)
	else
		DevTheme.Set(index)
	end
	if UISound and UISound.Click then
		UISound.Click.SoundId = DevTheme.ClickSoundId
	end
end

