-- Gelatek's ownership display is a separate visual system from the thin
-- wireframe hitboxes above: it puts one thick outline on each body part.  Hat
-- reanimation uses the same per-limb presentation for its controller targets,
-- without touching the physical hats or the controller's transparency.
Util.GetAssemblyOwnership = function(part)
	if typeof(part) ~= "Instance" or not part:IsA("BasePart") or not part.Parent then
		return false, "missing part", nil
	end
	local root = part
	pcall(function() root = part.AssemblyRootPart or part end)
	if part.Anchored or root.Anchored then return false, "anchored assembly", root end
	-- The assembly root's answer is authoritative for this compatibility API.
	-- ReceiveAge is a fallback only when the API cannot answer, not a way to
	-- turn an explicit ownership rejection into success.
	if type(isnetworkowner) == "function" then
		local ok, owned = pcall(isnetworkowner, root)
		if ok and type(owned) == "boolean" then return owned, "isnetworkowner assembly", root end
		if root ~= part then
			local partOk, partOwned = pcall(isnetworkowner, part)
			if partOk and type(partOwned) == "boolean" then return partOwned, "isnetworkowner part", root end
		end
	end
	local ok, age = pcall(function() return root.ReceiveAge end)
	if ok and type(age) == "number" then return age == 0, "ReceiveAge inference (unverified)", root end
	return false, "ownership unavailable", root
end
Util.IsNetworkOwner = function(part)
	local owned = Util.GetAssemblyOwnership(part)
	return owned == true
end

-- Read-only capture: no test poses, hidden setters, simulated ownership or
-- observer confirmation. Late values can be consumed/overwritten by the engine;
-- they are reported separately from immediate read-back at the write boundary.
Util.GetJointReplicationReport = function(physical, controller)
	local function read(fn)
		local ok, value = pcall(fn)
		return ok and tostring(value) or "unavailable"
	end
	local lines = {"=== JOINT REPLICATION DIAGNOSTICS v16 ===",
		"observer=NOT VERIFIED; local values do not establish another client's pose"}
	table.insert(lines, "engine=" .. read(function() return version() end))
	table.insert(lines, "executor=" .. read(function() return identifyexecutor() end))
	table.insert(lines, "clock=" .. tostring(os.clock()))
	local stats = Util.CharacterJointReplicationStats
	for _, entry in ipairs({{Name="physical", Rig=physical}, {Name="controller", Rig=controller}}) do
		local rig = entry.Rig
		table.insert(lines, "--- " .. entry.Name .. " ---")
		if not rig or not rig.Parent then
			table.insert(lines, "rig=missing")
			continue
		end
		local humanoid = rig:FindFirstChildOfClass("Humanoid")
		table.insert(lines, "humanoid=" .. read(function() return humanoid.RigType.Name .. "/" .. humanoid:GetState().Name end))
		local descendants = rig:GetDescendants()
		local animatorCount = 0
		for _, child in ipairs(descendants) do if child:IsA("Animator") then animatorCount += 1 end end
		table.insert(lines, "Animators=" .. tostring(animatorCount))
		local count = 0
		for _, joint in ipairs(descendants) do
			if not Util.IsCharacterJoint(joint) then continue end
			count += 1
			if count > 32 then table.insert(lines, "joint limit=32") break end
			local part0, part1 = Util.GetCharacterJointParts(joint)
			local owned, ownershipSource, root = Util.GetAssemblyOwnership(part0 or part1)
			local sample = stats.Joints[joint]
			table.insert(lines, tostring(joint.Name) .. "/" .. joint.ClassName
				.. " parts=" .. tostring(part0 and part0.Name) .. "->" .. tostring(part1 and part1.Name)
				.. " enabled=" .. read(function() return joint.Enabled end)
				.. " assembly=" .. tostring(root and root.Name)
				.. " owned=" .. tostring(owned) .. " via=" .. ownershipSource
				.. " receiveAge=" .. read(function() return root.ReceiveAge end))
			table.insert(lines, "  local Transform=" .. read(function() return joint.Transform end)
				.. " CurrentAngle=" .. read(function() return joint.CurrentAngle end)
				.. " DesiredAngle=" .. read(function() return joint.DesiredAngle end))
			if sample then
				table.insert(lines, "  write=" .. tostring(sample.WriteAccepted)
					.. " immediateReadback=" .. tostring(sample.ReadbackVerified)
					.. " at=" .. tostring(sample.WrittenAt) .. " error=" .. tostring(sample.LastError)
					.. " requestedOffset=" .. tostring(sample.RequestedOffset)
					.. " requestedAngle=" .. tostring(sample.RequestedAngle))
				table.insert(lines, "  offsetSource=" .. tostring(sample.OffsetSource)
					.. " angleSource=" .. tostring(sample.AngleSource))
			else table.insert(lines, "  no shared-writer sample") end
			if joint:IsA("Motor6D") then
				table.insert(lines, "  lateOffset=" .. read(function() return Util.HiddenPropertyGetter(joint,"ReplicateCurrentOffset6D") end)
					.. " lateAngle=" .. read(function() return Util.HiddenPropertyGetter(joint,"ReplicateCurrentAngle6D") end))
			end
		end
	end
	return table.concat(lines,"\n")
end

