function HatReanimator.ShowHitboxes()
	-- Thick green limb boxes are ownership warnings. They disappear as soon as
	-- every mapped physical accessory Handle for that controller limb is ours.
	local unownedLimbs = {}
	local mapped, owned = 0, 0
	for handle, limbName in HatReanimator.MappedProxyHandles do
		if handle and handle.Parent then
			mapped += 1
			if Util.IsNetworkOwner(handle) then
				owned += 1
			else
				unownedLimbs[limbName] = true
			end
		end
	end
	HatReanimator.Status.Ownership = ("%d/%d mapped hats claimed"):format(owned, mapped)
	local controller = Reanimate.Character
	if controller and controller.Parent then
		for limbName in unownedLimbs do
			local limb = controller:FindFirstChild(limbName)
			if limb and limb:IsA("BasePart") then
				local outline = Util.ShowPartLimbOutline(limb, Color3.fromRGB(125, 240, 125), 0)
				HatReanimator.ActiveLimbOutlines[outline] = true
			end
		end
	end

	-- Keep the original thin physical-hat diagnostics as a separate layer.  The
	-- thick outlines above are the mapped limb targets; these wireframes are the
	-- retained collidable accessory handles.
	local seen = {}
	local function showHandle(handle)
		if
			handle
			and handle:IsA("BasePart")
			and handle:IsDescendantOf(workspace)
			and handle:GetAttribute("_Uhhhhhh_HasCollide")
			and not seen[handle]
		then
			seen[handle] = true
			Util.ShowPartHitbox(handle, Color3.fromRGB(80, 255, 110), 0)
		end
	end
	for handle in HatReanimator.CollidableHandles do
		showHandle(handle)
	end
	local character = HatReanimator.ActiveRealCharacter
	if character and character.Parent then
		for _, v in character:GetChildren() do
			if v:IsA("Accessory") then
				showHandle(v:FindFirstChild("Handle"))
			end
		end
	end
end
HatReanimator.FlingTargets = {}
HatReanimator._TempNotFling = {}
function HatReanimator.Fling(target, duration)
	if HatReanimator.FlingMethod == -1 then
		return
	end
	if not target then
		return false
	end
	for _, v in HatReanimator.FlingTargets do
		if v.Target == target then
			return false
		end
	end
	if target == Reanimate.Character then
		return false
	end
	if target == Player.Character then
		return false
	end
	if target == HatReanimator.ActiveRealCharacter then
		return false
	end
	if typeof(target) == "Instance" then
		if HatReanimator._TempNotFling[target] then
			return
		end
		HatReanimator._TempNotFling[target] = true
		task.delay(1, function()
			HatReanimator._TempNotFling[target] = nil
		end)
	end
	table.insert(HatReanimator.FlingTargets, {
		Target = target,
		Duration = duration,
	})
	if typeof(target) == "Instance" then
		if target:IsA("Model") then
			local h = Util.Instance("Highlight")
			h.Adornee = target
			h.FillColor = Color3.new(1, 0, 0)
			h.OutlineColor = Color3.new(1, 0, 0)
			h.FillTransparency = 0.5
			h.OutlineTransparency = 0
			h.Parent = target
			TweenService:Create(h, TweenInfo.new(5), {
				FillTransparency = 1,
				OutlineTransparency = 1,
			}):Play()
			game.Debris:AddItem(h, 5)
		end
	end
	return true
end
