local function CreateAnimationStudioBanner(parent, title, subtitle)
	local banner = Util.Instance("Frame", parent)
	banner.Name = "AnimationStudioBanner"
	banner.Size = UDim2.new(1, -10, 0, 68)
	banner.BackgroundTransparency = 0.08
	banner.BackgroundColor3 = Color3.fromRGB(10, 14, 22)
	banner.BorderSizePixel = 0
	banner.LayoutOrder = #parent:GetChildren()
	Util.Instance("UICorner", banner).CornerRadius = UDim.new(0, 8)
	local stroke = Util.Instance("UIStroke", banner)
	stroke.Thickness = 1.5
	stroke.Transparency = 0.18
	local accent = Util.Instance("Frame", banner)
	accent.Name = "Accent"
	accent.Size = UDim2.new(0, 5, 1, -12)
	accent.Position = UDim2.new(0, 6, 0, 6)
	accent.BorderSizePixel = 0
	Util.Instance("UICorner", accent).CornerRadius = UDim.new(0, 3)
	local titleText = Util.Instance("TextLabel", banner)
	titleText.BackgroundTransparency = 1
	titleText.Position = UDim2.new(0, 20, 0, 7)
	titleText.Size = UDim2.new(1, -28, 0, 28)
	titleText.Font = Enum.Font.Code
	titleText.Text = title
	titleText.TextSize = 22
	titleText.TextXAlignment = Enum.TextXAlignment.Left
	titleText.TextColor3 = Color3.new(1, 1, 1)
	titleText.RichText = true
	RegisterTextLabel(titleText)
	local subtitleText = Util.Instance("TextLabel", banner)
	subtitleText.BackgroundTransparency = 1
	subtitleText.Position = UDim2.new(0, 20, 0, 35)
	subtitleText.Size = UDim2.new(1, -28, 0, 24)
	subtitleText.Font = Enum.Font.Code
	subtitleText.Text = subtitle
	subtitleText.TextSize = 11
	subtitleText.TextWrapped = true
	subtitleText.TextXAlignment = Enum.TextXAlignment.Left
	subtitleText.TextColor3 = Color3.new(1, 1, 1)
	RegisterTextLabel(subtitleText)
	AddToRenderStep(function(t)
		local themeColor = GetUIColor(t)
		accent.BackgroundColor3 = themeColor
		stroke.Color = themeColor
		banner.BackgroundColor3 = GetUIBGColor(t):Lerp(Color3.fromRGB(8, 16, 28), 0.35)
	end, banner)
	return banner
end

