local function RefreshBodyPartPickers()
	-- Hide Body Parts controls the replicated physical shell. Reanimate.Character
	-- is the invisible animation controller under Limb/Hats/Gelatek, so using it
	-- here can produce an empty/wrong list (especially after Gelatek handoff).
	local figure = type(Reanimate.GetActiveRealCharacter) == "function"
		and Reanimate.GetActiveRealCharacter()
		or nil
	if not figure and not Reanimate.Current then
		figure = Player.Character
	end
	local partNames = GetDetectedDanceEffectBodyParts(figure)
	HiddenBodyPartPicker:Refresh(partNames)
    AnimLib.NormalizePartSelections(Reanimate.Character)
    DisabledBodyPartPicker:Refresh(GetDetectedDanceEffectBodyParts(Reanimate.Character))
end

RefreshBodyPartPickers()
local BodyPartPickerRefreshElapsed = 0
AddToRenderStep(function(_, dt)
	BodyPartPickerRefreshElapsed += dt
	if BodyPartPickerRefreshElapsed >= 0.5 then
		BodyPartPickerRefreshElapsed = 0
		RefreshBodyPartPickers()
	end
end, AnimationOptionsPage)

-- Keep this page in its own closure. Besides making the six-limb controls
-- easier to reason about, this prevents another top-level local-register spike
-- in the already large embedded UI chunk.
;(function()
	local page = UI.CreatePage()
	page.ZIndex = 2
	page.Position = UDim2.new(0.5, 360, 0.5, 0)
	page.Interactable = false
	page.Visible = false

	local function openPage()
		UI.Workspace.Open(page, AnimationOptionsPage)
	end

	local function closePage()
		UI.Workspace.Back(page, AnimationOptionsPage)
	end

	JointMixerQuickButton.Activated:Connect(openPage)
	UI.CreateButton(page, "&lt; Back to Animation Studio", 18).Activated:Connect(closePage)
	CreateAnimationStudioBanner(
		page,
		"<b>ANIMATED JOINTS</b>",
		":3"
	)
	UI.CreateText(
		page,
		"Every switch updates the currently playing animator immediately. It only controls dance pose writing; physical reanimation, collision, and visibility stay untouched.",
		10,
		Enum.TextXAlignment.Center
	)
	UI.CreateSeparator(page)

	local presetNames = { "Custom", "Full Body", "Upper Body", "Lower Body", "Arms Only" }
	if not table.find(presetNames, AnimLib.Settings.JointPreset) then
		AnimLib.Settings.JointPreset = "Custom"
		SavedAnimLibOptions.JointPreset = "Custom"
	end
	local updating = false
	local switches = {}
	local presetSelect = UI.CreateDropdown(
		page,
		"Quick Preset",
		presetNames,
		table.find(presetNames, AnimLib.Settings.JointPreset) or 1
	)
	local statusText = UI.CreateText(page, "", 11, Enum.TextXAlignment.Center)

	local function saveMixer()
		local saved, reason = SaveSettingsNow()
		if not saved then
			warn("Joint Mixer save failed: " .. tostring(reason))
			Util.UINotify("Joint Mixer changed, but settings could not be saved")
		end
	end

	local function refreshControls()
		updating = true
		local animatedCount = 0
		for _, group in AnimLib.JointGroups do
			local animated = AnimLib.IsJointGroupAnimated(group.Key)
			animatedCount += animated and 1 or 0
			if switches[group.Key] then
				switches[group.Key].Value = animated
			end
		end
		presetSelect.Value = table.find(presetNames, AnimLib.Settings.JointPreset) or 1
		updating = false
		statusText.Text = string.format(
			"%d / %d limbs animated  •  LIVE",
			animatedCount,
			#AnimLib.JointGroups
		)
	end

	presetSelect.Changed:Connect(function(index)
		if updating then
			return
		end
		AnimLib.ApplyJointPreset(presetNames[index] or "Custom")
		AnimLib.ApplyDisabledAnimationParts()
		saveMixer()
		refreshControls()
	end)

	UI.CreateText(page, "<b>ANIMATED JOINT GROUPS</b>", 13, Enum.TextXAlignment.Left)
	for _, group in AnimLib.JointGroups do
		local groupKey = group.Key
		local control = UI.CreateSwitch(page, "Animate " .. group.Label, AnimLib.IsJointGroupAnimated(groupKey))
		switches[groupKey] = control
		control.Changed:Connect(function(value)
			if updating then
				return
			end
			AnimLib.SetJointGroupAnimated(groupKey, value == true)
			AnimLib.Settings.JointPreset = "Custom"
			SavedAnimLibOptions.JointPreset = "Custom"
			AnimLib.ApplyDisabledAnimationParts()
			saveMixer()
			refreshControls()
		end)
	end

	UI.CreateSeparator(page)
	UI.CreateButton(page, "Animate All Six Limbs", 16).Activated:Connect(function()
		AnimLib.ApplyJointPreset("Full Body")
		saveMixer()
		refreshControls()
	end)
	UI.CreateButton(page, "Disable All Six Limbs", 16).Activated:Connect(function()
		for _, group in AnimLib.JointGroups do
			AnimLib.SetJointGroupAnimated(group.Key, false)
		end
		AnimLib.Settings.JointPreset = "Custom"
		SavedAnimLibOptions.JointPreset = "Custom"
		AnimLib.ApplyDisabledAnimationParts()
		saveMixer()
		refreshControls()
	end)
	UI.CreateButton(page, "Reset Disabled Joint Poses", 16).Activated:Connect(function()
		AnimLib.ResetDisabledJointPoses(Reanimate.Character)
		Util.UINotify("Disabled joint poses reset")
	end)
	UI.CreateText(
		page,
		"Head, Torso/Waist, Left Arm, Right Arm, Left Leg, and Right Leg each map to the matching R6 part or every segment of that R15 limb.",
		9,
		Enum.TextXAlignment.Center
	)
	refreshControls()
end)()

