local InitLogsText = Steve110.Require("main/bounded_log")(
    UI.CreateText(InitLogsPage, "Loading...", 12, Enum.TextXAlignment.Left))
local STEVE110_BUILTIN_ROOT = STEVE110_ROOT .. "/main/addldata/"
local STEVE110_BUILTINS = {v_moveset1 = true, v_moveset2 = true, v_moveset3 = true,
    v_dance1 = true, v_dance2 = true, d_limbmap = true, d_hatsmap = true}
local function _contentgetgithubraw(path)
    local name = tostring(path):gsub("%.lua$", "")
    if STEVE110_BUILTINS[name] then
        local ok, body = pcall(readfile, STEVE110_BUILTIN_ROOT .. name .. ".lua")
        if ok and HttpBodyIsUsable(body) then return body end
    end
	local rawUrl =
		"https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/"
		.. STEVE_AUDITED_REVISION
		.. "/content/"
		.. path

	InitLogsText.Text ..= "\n[LOG] [GitGET] GET raw./" .. path
	local body, rawError = HttpFetchBody(rawUrl, nil, 3)
	if body then
		return body
	end
	InitLogsText.Text ..=
		"\n[WARN] [GitGET] raw./"
		.. path
		.. " failed: "
		.. tostring(rawError)

	local apiUrl =
		"https://api.github.com/repos/STEVE-916-create/Uhhhhhh/contents/content/"
		.. path
		.. "?ref="
		.. STEVE_AUDITED_REVISION
	InitLogsText.Text ..= "\n[LOG] [GitGET] GET api./" .. path
	local apiBody, apiError =
		HttpFetchBody(
			apiUrl,
			{ Accept = "application/vnd.github.VERSION.raw" },
			2
		)
	if apiBody then
		return apiBody
	end

	InitLogsText.Text ..=
		"\n[ERROR] [GitGET] api./"
		.. path
		.. " failed: "
		.. tostring(apiError)
	RecordContentFailure(
		"builtin-download",
		path,
		rawUrl .. " | " .. apiUrl,
		tostring(rawError) .. " | " .. tostring(apiError)
	)
	return nil
end

local UserModulesListor = {}
local USER_MODULE_ROOT = "BlaaBlaaReanim/Modules/"
local USER_ASSET_FOLDERS = {
	[".anim"] = "Anims",
	[".mp3"] = "Sounds",
	[".ogg"] = "Sounds",
	[".wav"] = "Sounds",
	[".png"] = "Images",
	[".jpg"] = "Images",
