-- Keep the marketplace's many page/controller locals out of the already-large
-- runtime chunk.  Some executor Luau builds enforce the 200-register limit
-- while compiling this embedded source, even though syntax-only checks pass.
;(function()
(function()
    local page = UI.CreatePage()
    page.ZIndex, page.Position = 2, UDim2.new(0.5, 360, 0.5, 0)
    page.Interactable, page.Visible = false, false
    UI.CreateButton(page, "&lt; Back", 20).Activated:Connect(function()
        UI.Workspace.Back(page, MarketPage)
    end)
    UI.CreateText(page, "Addon error details", 20, Enum.TextXAlignment.Left)
    UI.CreateText(page, "Addon failures are quiet by default. Broken random dances are skipped; core errors are not hidden.", 12, Enum.TextXAlignment.Left)
    local debugSwitch = UI.CreateSwitch(page, "Show addon errors (debug)", Util.CommunityDiagnostics.Enabled())
    debugSwitch.Changed:Connect(function(value)
        SaveData.CommunityDiagnosticsEnabled = value == true
        SaveSettingsNow()
    end)
    local text = UI.CreateText(page, "", 12, Enum.TextXAlignment.Left)
    text.RichText = false
    local function refresh() text.Text = Util.CommunityDiagnostics.Describe() end
    UI.CreateButton(page, "Refresh details", 16).Activated:Connect(refresh)
    UI.CreateButton(page, "Copy error log", 16).Activated:Connect(function()
        local copied = pcall(setclipboard, Util.CommunityDiagnostics.Describe())
        Util.UINotify(copied and "Copied addon error log" or "Clipboard unavailable; read the details below")
    end)
    UI.CreateButton(page, "Clear error log", 16).Activated:Connect(function()
        Util.CommunityDiagnostics.Clear()
        refresh()
    end)
    UI.CreateButton(MarketPage, "Addon error details &gt;", 18).Activated:Connect(function()
        refresh()
        UI.Workspace.Open(page, MarketPage)
    end)
end)()
StreamRuntime = Steve110.Require("main/market_stream")({
    UI = UI, Cache = StreamCache, Task = task, Fetch = HttpFetchBody, Compile = CompileAnimationModule,
    Bind = GiveFunctionsToFunction, Folder = MarketCatalog.Folder, RetryAssets=RetryAnimationAssets,
    ClearRows = Util.ClearAllChildrenGui, Notify = Util.UINotify,
    Report = function(kind, name, source, reason)
        Util.CommunityDiagnostics.Report(kind, name, source, reason)
    end,
    DeferInstalled = function(item)
        SaveData.MarketPackModes = SaveData.MarketPackModes or {}
        SaveData.MarketPackModes[item.File:gsub("/*$", "") .. "/"] = "stream"
        SaveSettingsNow()
    end,
    Build = function(factory, context)
        assert(type(factory) == "function", "Entry is not a function")
        local bindOwner=GiveFunctionsToFunction(factory, context)
        local m = factory()
        local valid, reason = ValidateModuleObject(m)
        if not valid then return nil, reason end
        bindOwner(m)
        ResolveModuleAssets(m, context)
        GetModuleHash(m)
        if m.LoadConfig and SaveData.ModuleConfigs[m.Hash] then pcall(m.LoadConfig, SaveData.ModuleConfigs[m.Hash]) end
        return m
    end,
    IsSelected = function(m)
        return m.ModuleType == "DANCE" and CurrentDance == m
            or m.ModuleType == "MOVESET" and MovementStyles[MovementStyleIndex] == m
    end,
    Play = function(m)
        if not Reanimate.Character then Util.UINotify("Start reanimation before playing a streamed entry"); return false end
        if m.ModuleType == "DANCE" then CurrentDance = m
        else
            m.StreamPreviousStyle = MovementStyleIndex
            table.insert(MovementStyles, m)
            MovementStyleIndex = #MovementStyles
        end
        __TheoManualRefreshSerial += 1
        return true
    end,
    Stop = function(m)
        if _CurrentDance == m or CurrentMovementStyle == m then
            TeardownAnimationRuntime(Reanimate.Character, CurrentDance ~= m)
        elseif CurrentDance == m then CurrentDance = nil end
        if m.ModuleType == "DANCE" then UISound.DanceMusic.SoundId = "" end
        local index = table.find(MovementStyles, m)
        if index then
            local selected = MovementStyleIndex == index
            table.remove(MovementStyles, index)
            if selected then MovementStyleIndex = math.clamp(m.StreamPreviousStyle or 2, 1, math.max(1, #MovementStyles))
            elseif MovementStyleIndex > index then MovementStyleIndex -= 1 end
            UISound.MovesetMusic.SoundId = ""
        end
    end,
})
SCREENGUI.Destroying:Connect(function() StreamRuntime.Clear() end)
local function GetMarketList(refresh) return MarketCatalog.Get(refresh) end
local function InstallMarketItem(item, force, targetPath)
    if item.Type ~= "folder" then
        return AssetDownloadAgent(item.Source,item.File,targetPath or ("BlaaBlaaReanim/Modules/"..item.File),force)
    end
    SaveData.MarketPackModes = SaveData.MarketPackModes or {}
    SaveData.MarketPackModes[item.File:gsub("/*$", "") .. "/"] = "installed"
    SaveSettingsNow()
    local ok, failure = pcall(function()
        local modules, context, key = MarketCatalog.Folder(item)
        local contextPath="BlaaBlaaReanim/MarketContexts/"..key..".json"
        local data=HttpService:JSONEncode(context)
        EnsureAssetFolders(contextPath)
        writefile(contextPath,data)
        assert(readfile(contextPath)==data,"Pack context write failed")
        for _,module in ipairs(modules) do
            AssetDownloadAgent(module.Source,module.File,"BlaaBlaaReanim/Modules/"..module.File,force,function(body)
                return "-- UHH_MARKET_CONTEXT "..key.."\n"..body
            end)
        end
        Util.UINotify("Queued "..#modules.." modules from "..item.Name..". Reload modules when downloads finish.")
    end)
    if not ok then Util.CommunityDiagnostics.Report("pack-download", item.Name, item.Source or item.File, failure,
        "Pack download failed: "..tostring(failure):sub(1,180)) end
    return ok
end
local LocalPage = UI.CreateItemListPage()
LocalPage.ZIndex = 2
LocalPage.Position = UDim2.new(0.5, 360, 0.5, 0)
LocalPage.Interactable = false
LocalPage.Visible = false
local function RefreshUserModules()
	Util.ClearAllChildrenGui(LocalPage.List)
	local _, file2name, file2aitemu = GetMarketList()
	local localFiles = {}
	CollectUserModuleFiles(USER_MODULE_ROOT, localFiles, {}, 0)
	for _, path in localFiles do
		if isfile(path) then
			local x = UserModuleRelativePath(path)
			local marketKey = string.gsub(x, "/", ".")
			local item = UI.CreateItemListItem(LocalPage.List)
			local name = file2name[x] or file2name[marketKey] or x
			UI.CreateText(item, name .. " &gt;", 20, Enum.TextXAlignment.Left)
			local desc1 = "(has errors or has no modules loaded or not loaded)"
			local desc2 = "(has errors or has no modules loaded or not loaded)"
			local desc3 = " errors no modules"
			local list = UserModulesListor[x]
			if list and #list > 0 then
				desc1 = "This module contains " .. #list .. " modules."
				desc2 = "This module contains:"
				desc3 = ""
				for _, v in list do
					desc2 ..= "\n - " .. v
					desc3 ..= " " .. v
				end
			end
			UI.CreateText(item, desc1, 12, Enum.TextXAlignment.Left)
			item.Parent.Name = x .. " " .. name .. desc3
			Util.LinkDestroyI2C(
				item,
				item.Activated:Connect(function()
					local page = UI.CreatePage()
					page.ZIndex = 3
					page.Position = UDim2.new(0.5, 360, 0.5, 0)
					page.Interactable = false
					page.Visible = true
					UI.CreateButton(page, " &lt; Hurry back", 20).Activated:Connect(function()
						UI.Workspace.Back(page, LocalPage, true)
					end)
					UI.CreateSeparator(page)
					UI.CreateText(page, name, 20, Enum.TextXAlignment.Left)
					UI.CreateText(page, desc2, 15, Enum.TextXAlignment.Left)
					UI.CreateSeparator(page)
					local aitemu = file2aitemu[x] or file2aitemu[marketKey]
					if aitemu then
						UI.CreateButton(page, "Redownload/Update", 20).Activated:Connect(function()
                            InstallMarketItem(aitemu, true, path)
							RefreshUserModules()
							UI.Workspace.Back(page, LocalPage, true)
						end)
					end
					local destruction, destructiontext = UI.CreateButton(page, "Delete Module", 15)
					local deletion = 0
					destruction.Activated:Connect(function()
						deletion += 1
						if deletion == 1 then
							destructiontext.Text = "Are you admin?"
							task.wait(1)
							if deletion == 1 then
								deletion = 0
								destructiontext.Text = "Delete Module"
							end
						elseif deletion == 2 then
							destructiontext.Text = "Confirmation?"
							task.wait(1)
							if deletion == 2 then
								deletion = 0
								destructiontext.Text = "Delete Module"
							end
						elseif deletion == 3 then
							destructiontext.Text = "Say goodbye..."
							delfile(path)
											ContentCache.Invalidate(path)
							RefreshUserModules()
							UI.Workspace.Back(page, LocalPage, true)
						end
					end)
					UI.Workspace.Open(page, LocalPage)
				end)
			)
		end
	end
end
