MarkettePage.Back.Activated:Connect(function()
	UI.Workspace.Back(MarkettePage, MarketPage)
end)

end)()

ForceModuleReload(false)

end)()
]===],
}

local function ensure(path)
	if not isfolder(path) then makefolder(path) end
end
ensure("BlaaBlaaReanim")
ensure("BlaaBlaaReanim/System")

for path, content in pairs(files) do
	local parent = path:match("^(.*)/[^/]+$")
	local current = ""
	for segment in parent:gmatch("[^/]+") do
		current = current == "" and segment or current .. "/" .. segment
		ensure(current)
	end
	writefile(path, content)
	assert(readfile(path) == content, "Install write verification failed: " .. path)
end

if not isfile("BlaaBlaaReanim/System/config.json") then
	local config = isfile("Theos Dancezzzzz/Bridge/config.json")
		and readfile("Theos Dancezzzzz/Bridge/config.json") or readfile("BlaaBlaaReanim/System/config.default.json")
	config = config:gsub("Theos Dancezzzzz/Bridge", "BlaaBlaaReanim/System")
	writefile("BlaaBlaaReanim/System/config.json", config)
	assert(readfile("BlaaBlaaReanim/System/config.json") == config, "Config migration write verification failed")
end

assert(not _G.UhhhhhhLoaded, "BlaaBlaa is already loaded; rejoin first")
local chunk, err = loadstring(readfile("BlaaBlaaReanim/System/launch.lua"))
assert(type(chunk) == "function", "compile failed: " .. tostring(err))
table.clear(files)
files = nil
if task and type(task.defer) == "function" then
	task.defer(chunk)
	return
end
return chunk()
